const IS_WINDOWS = process.platform === 'win32';

/** The npm safety arguments every install and update uses. */
export function getPiNpmSafetyArgs(): string[] {
  return ['--ignore-scripts', '--no-audit', '--no-fund'];
}

/** The .md profile names in a folder, sorted by name as PowerShell's Get-ChildItem does. */
export function agentFileNames(dir: string): string[] {
  return readdirSync(dir)
    .filter((name) => name.endsWith('.md'))
    .filter((name) => statSync(joinMaxstackPath(dir, name)).isFile())
    .sort();
}

/** The text an installed profile holds once its model line is removed, or null when it has no frontmatter. */
export function getAgentProfileText(path: string): string | null {
  const text = readFileSync(path, 'utf8').replaceAll('\r\n', '\n');
  const frontmatter = /^(?:\uFEFF)?---\n[\s\S]*?\n---\n/.exec(text);
  if (!frontmatter) return null;
  const stripped = frontmatter[0].replace(/^model:.*\n/gm, '');
  return stripped + text.slice(frontmatter[0].length);
}

/** maxstack sets no model, so an installed profile keeps no model line. */
export function removeAgentModel(path: string): void {
  const text = getAgentProfileText(path);
  if (text === null) return;
  writeFileSync(path, text, 'utf8');
}

function getTextSha256(text: string): string {
  return sha256Text(text);
}

/** The process exit code as a number; main sets it for -Strict and skipped wrappers. */
function currentExitCode(): number {
  return typeof process.exitCode === 'number' ? process.exitCode : 0;
}

function trimEndingSeparator(path: string): string {
  return trimMaxstackPathEndingSeparator(path);
}

function workspaceFull(relative: string): string {
  return joinMaxstackPath(S.workspace, convertToMaxstackPath(relative));
}

function getLinkRecordKind(): string {
  return linkRecordKind();
}

function testClaudeLink(child: string, target: string, kind = ''): boolean {
  return maxstackLinkTargetMatches(child, target, kind);
}

// ---- T3 gated instances ---------------------------------------------------------------------------------

function getT3InstancesPlan(
  layers: readonly LayerModel[],
  selectedLayers: readonly string[],
  settings: SettingsDocument,
): Record<string, unknown> | null {
  const relative = '.pstack/pstack-t3-instances.json';
  const prior = getPriorOwnedFileRecord(relative);
  const full = workspaceFull(relative);
  let instances: string[] = [];
  let readOnlyInstances: string[] = [];
  if (settings.present && settings.value !== null) {
    const t3 = getField(settings.value, 't3');
    if (t3 !== null && t3 !== undefined) {
      const gated = getField(t3, 'gatedInstances');
      if (Array.isArray(gated)) instances = gated.map((value) => String(value));
      const readOnly = getField(t3, 'readOnlyInstances');
      if (Array.isArray(readOnly)) readOnlyInstances = readOnly.map((value) => String(value));
    }
  }
  if (instances.length > 0 || readOnlyInstances.length > 0) {
    const selectedModels = layers.filter((layer) => ordinalIn(layer.name, selectedLayers));
    const selectedNames = selectedModels.map((layer) => layer.name);
    let gate = false;
    for (const layer of selectedModels) {
      if (layer.root === null) continue;
      const hooks = joinMaxstackPath(layer.root, 'hooks');
      if (
        isFile(joinMaxstackPath(hooks, 'pre-tool-use.mjs')) &&
        isFile(joinMaxstackPath(hooks, 'lib/codex.mjs'))
      ) {
        gate = true;
        break;
      }
    }
    const entries: Record<string, unknown> = {};
    for (const instance of instances) entries[instance] = { layers: [...selectedNames], gate };
    for (const instance of readOnlyInstances) {
      entries[instance] = { layers: [], gate: false, readOnly: true };
    }
    let text = jsonText({ instances: entries });
    text = text.replaceAll('\r\n', '\n').replaceAll('\r', '\n') + '\n';
    if (pathExists(full) && prior === null) {
      writeHost('Kept .pstack/pstack-t3-instances.json: it exists and was not written by maxstack.');
      return null;
    }
    let preserve = false;
    if (pathExists(full) && prior !== null) {
      preserve = testReparsePoint(full) || !isFile(full);
      if (!preserve) preserve = !ordinalEqual(sha256FileOrNull(full), prior.sha256 ?? null);
    }
    if (preserve) {
      writeHost(
        'Kept .pstack/pstack-t3-instances.json: it changed since the last apply, so it was not overwritten.',
      );
    }
    return {
      path: relative,
      text,
      sha256: getTextSha256(text),
      runtime: 't3-gated-instances',
      layers: [...selectedNames],
      preserve,
    };
  }
  if (prior === null) return null;
  if (
    pathExists(full) &&
    (testReparsePoint(full) ||
      !isFile(full) ||
      !ordinalEqual(sha256FileOrNull(full), prior.sha256 ?? null))
  ) {
    writeHost(
      'Kept .pstack/pstack-t3-instances.json: it changed since the last apply, so it was not removed.',
    );
    return {
      path: relative,
      text: null,
      sha256: prior.sha256 ?? null,
      runtime: 't3-gated-instances',
      layers: [...(prior.layers ?? [])],
      preserve: true,
    };
  }
  return null;
}

function writeT3InstancesFile(plan: Record<string, unknown> | null): void {
  const relative = '.pstack/pstack-t3-instances.json';
  const full = workspaceFull(relative);
  const prior = getPriorOwnedFileRecord(relative);
  if (plan === null) {
    if (prior === null || !isFile(full)) return;
    if (testReparsePoint(full) || !ordinalEqual(sha256FileOrNull(full), prior.sha256 ?? null)) {
      writeHost(
        'Kept .pstack/pstack-t3-instances.json: it changed since the last apply, so it was not removed.',
      );
      return;
    }
    unlinkSync(full);
    writeHost('Removed .pstack/pstack-t3-instances.json: no T3 instances are listed.');
    return;
  }
  if (isTrue(plan.preserve)) return;
  if (
    isFile(full) &&
    ordinalEqual(sha256FileOrNull(full), plan.sha256 as string) &&
    ordinalEqual(readText(full), plan.text as string)
  ) {
    writeHost('T3 instance list already matches: .pstack/pstack-t3-instances.json');
    return;
  }
  mkdirSync(dirname(full), { recursive: true });
  writeFileAtomic(full, plan.text as string);
  writeHost('Wrote .pstack/pstack-t3-instances.json');
}

// ---- Workspace instructions -----------------------------------------------------------------------------

function readWorkspaceInstruction(layer: LayerModel): { layer: string; text: string } | null {
  if (layer.root === null) return null;
  const layerJson = readLayerJson(layer.root);
  const relative = getField(layerJson, 'workspaceInstructions');
  if (relative === null || relative === undefined) return null;
  const label = `Layer '${layer.name}' workspaceInstructions`;
  if (typeof relative !== 'string' || !testRelativePath(relative)) {
    throw new Error(`${label} must be a relative Markdown file path inside the layer folder.`);
  }
  const root = trimEndingSeparator(resolve(layer.root));
  const full = resolve(joinMaxstackPath(root, convertToMaxstackPath(relative)));
  if (!maxstackPathInside(full, root)) throw new Error(`${label} escapes the layer folder.`);
  let current = root;
  const segments = relative.split(/[\\/]/);
  for (let index = 0; index < segments.length; index++) {
    current = joinMaxstackPath(current, segments[index] as string);
    if (pathExists(current)) {
      if (testReparsePoint(current)) {
        throw new Error(`${label} is a symbolic link or junction at '${segments[index]}'.`);
      }
    } else if (index === segments.length - 1) {
      throw new Error(`${label} file is missing at '${relative}'.`);
    }
  }
  if (!isFile(full)) throw new Error(`${label} must name a Markdown file, but '${relative}' is not a file.`);
  const bytes = readFileSync(full);
  if (bytes.length > 4096) {
    throw new Error(`${label} file is ${bytes.length} bytes; the allowed size is 4096 bytes.`);
  }
  let text: string;
  try {
    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    throw new Error(`${label} file is not valid UTF-8.`);
  }
  if (text.startsWith('\uFEFF')) text = text.slice(1);
  text = text.replace(/\r\n?/g, '\n');
  return { layer: layer.name, text };
}

export interface WorkspaceInstructionFile {
  path: string;
  text: string;
  runtime: string;
  layers: string[];
  preserve?: boolean;
}

export interface WorkspaceInstructionPlan {
  text: string | null;
  files: WorkspaceInstructionFile[];
  sourceLayers: string[];
  collisionNames: string[];
}

export function getWorkspaceInstructionPlan(
  layers: readonly LayerModel[],
  selectedRuntimes: readonly string[],
  validateOnly = false,
): WorkspaceInstructionPlan {
  const sources: Array<{ layer: string; text: string }> = [];
  for (const layer of layers) {
    const source = readWorkspaceInstruction(layer);
    if (source !== null) sources.push(source);
  }
  if (sources.length === 0 || selectedRuntimes.length === 0) {
    const retained: WorkspaceInstructionFile[] = [];
    for (const record of S.priorOwned ?? []) {
      if (record === null) continue;
      if (!ordinalEqual(getField(record, 'runtime'), WORKSPACE_INSTRUCTION_RUNTIME)) continue;
      const full = workspaceFull(record.path);
      if (!isFile(full)) continue;
      if (testReparsePoint(full)) {
        retained.push({
          path: record.path,
          text: '',
          runtime: WORKSPACE_INSTRUCTION_RUNTIME,
          layers: [...(record.layers ?? [])],
          preserve: true,
        });
        continue;
      }
      if (ordinalEqual(sha256FileOrNull(full), record.sha256 ?? null)) continue;
      retained.push({
        path: record.path,
        text: readText(full),
        runtime: WORKSPACE_INSTRUCTION_RUNTIME,
        layers: [...(record.layers ?? [])],
        preserve: true,
      });
    }
    return { text: null, files: retained, sourceLayers: [], collisionNames: [] };
  }
  let text = WORKSPACE_INSTRUCTION_HEADER;
  const contributions: Array<{ layer: string; bytes: number }> = [];
  for (const source of sources) {
    let part = `<!-- Layer: ${source.layer} -->\n${source.text}`;
    if (!part.endsWith('\n')) part += '\n';
    text += part;
    contributions.push({ layer: source.layer, bytes: Buffer.byteLength(part, 'utf8') });
  }
  const size = Buffer.byteLength(text, 'utf8');
  if (size > 8192) {
    const detail = contributions.map((item) => `${item.layer}: ${item.bytes} bytes`).join(', ');
    throw new Error(
      `Composed workspace instructions are ${size} bytes; the allowed size is 8192 bytes. Layer contributions: ${detail}.`,
    );
  }
  if (validateOnly) {
    return { text, files: [], sourceLayers: sources.map((source) => source.layer), collisionNames: [] };
  }
  const collisionNames: string[] = [];
  for (const name of ['AGENTS.md', 'CLAUDE.md']) {
    if (ordinalEqual(name, 'CLAUDE.md') && !ordinalIn('claude', selectedRuntimes)) continue;
    const path = workspaceFull(name);
    if (!pathExists(path)) continue;
    const record = getPriorWorkspaceInstructionRecord(name);
    if (record === null || testReparsePoint(path) || !isFile(path)) collisionNames.push(name);
  }
  let instructionPath: string;
  const instructionText = text;
  if (collisionNames.length > 0) {
    instructionPath = '.maxstack/workspace-instructions.md';
    for (const name of collisionNames) {
      writeHost(
        `Kept workspace ${name}: not written by maxstack. Wrote .maxstack/workspace-instructions.md; reference it from your own instructions to load the shared agreements.`,
      );
    }
    const fallback = workspaceFull(instructionPath);
    if (pathExists(fallback) && getPriorWorkspaceInstructionRecord(instructionPath) === null) {
      throw new Error(
        `${instructionPath} already exists and maxstack did not write it, so nothing was written. Move it aside, then rerun -Apply.`,
      );
    }
  } else {
    instructionPath = 'AGENTS.md';
  }
  const files: WorkspaceInstructionFile[] = [
    {
      path: instructionPath,
      text: instructionText,
      runtime: WORKSPACE_INSTRUCTION_RUNTIME,
      layers: sources.map((source) => source.layer),
    },
  ];
  if (ordinalIn('claude', selectedRuntimes) && collisionNames.length === 0) {
    files.push({
      path: 'CLAUDE.md',
      text: `${WORKSPACE_CLAUDE_HEADER}@AGENTS.md\n`,
      runtime: WORKSPACE_INSTRUCTION_RUNTIME,
      layers: sources.map((source) => source.layer),
    });
  }
  if (ordinalIn('copilot', selectedRuntimes)) {
    files.push({
      path: '.maxstack/copilot-instructions/AGENTS.md',
      text,
      runtime: WORKSPACE_INSTRUCTION_RUNTIME,
      layers: sources.map((source) => source.layer),
    });
  }
  for (const file of files) {
    const full = workspaceFull(file.path);
    const prior = getPriorWorkspaceInstructionRecord(file.path);
    if (pathExists(full) && prior === null) {
      throw new Error(
        `${file.path} already exists and maxstack did not write it, so nothing was written. Move it aside, then rerun -Apply.`,
      );
    }
    if (prior !== null && pathExists(full)) {
      let changed = testReparsePoint(full) || !isFile(full);
      if (!changed) changed = !ordinalEqual(sha256FileOrNull(full), prior.sha256 ?? null);
      if (changed) file.preserve = true;
    }
  }
  const wanted = files.map((file) => file.path);
  for (const record of S.priorOwned ?? []) {
    if (record === null) continue;
    if (!ordinalEqual(getField(record, 'runtime'), WORKSPACE_INSTRUCTION_RUNTIME)) continue;
    if (ordinalIn(record.path, wanted)) continue;
    const full = workspaceFull(record.path);
    if (!isFile(full)) continue;
    if (testReparsePoint(full)) {
      files.push({
        path: record.path,
        text: '',
        runtime: WORKSPACE_INSTRUCTION_RUNTIME,
        layers: [...(record.layers ?? [])],
        preserve: true,
      });
      continue;
    }
    if (ordinalEqual(sha256FileOrNull(full), record.sha256 ?? null)) continue;
    files.push({
      path: record.path,
      text: readText(full),
      runtime: WORKSPACE_INSTRUCTION_RUNTIME,
      layers: [...(record.layers ?? [])],
      preserve: true,
    });
  }
  return { text, files, sourceLayers: sources.map((source) => source.layer), collisionNames };
}

function writeWorkspaceInstructionFiles(
  files: readonly WorkspaceInstructionFile[],
  priorOwned: readonly (OwnedRecord | null)[] | null,
): void {
  const wanted = files.map((file) => file.path);
  for (const record of priorOwned ?? []) {
    if (record === null) continue;
    if (!ordinalEqual(getField(record, 'runtime'), WORKSPACE_INSTRUCTION_RUNTIME)) continue;
    if (ordinalIn(record.path, wanted)) continue;
    const full = workspaceFull(record.path);
    if (!isFile(full)) continue;
    if (
      testReparsePoint(full) ||
      !ordinalEqual(sha256FileOrNull(full), record.sha256 ?? null)
    ) {
      writeHost(`Kept ${record.path}: it changed since the last apply, so it was not removed.`);
    } else {
      unlinkSync(full);
      writeHost(`Removed ${record.path}: no longer selected for this workspace.`);
    }
  }
  for (const file of files) {
    const full = workspaceFull(file.path);
    if (isTrue(file.preserve)) {
      writeHost(`Kept ${file.path}: it changed since the last apply, so it was not overwritten.`);
      continue;
    }
    if (isFile(full) && readText(full).trim() === file.text.trim()) {
      writeHost(`Workspace instructions already match: ${file.path}`);
      continue;
    }
    mkdirSync(dirname(full), { recursive: true });
    writeFileAtomic(full, file.text);
    writeHost(`Wrote ${file.path}`);
  }
}

/** Whether a config file is missing, differs from the text, or matches it. */
export function getDriftState(path: string, text: string): string {
  if (!isFile(path)) return 'missing';
  if (readText(path).trim() === text.trim()) return 'matches';
  return 'differs';
}

// ---- OpenCode and Claude --------------------------------------------------------------------------------

export interface OpenCodeSpec {
  entry: string;
  dir: string;
  loader: 'discovery' | 'config';
  agents: string | null;
}

export function getOpenCodeSpec(layer: LayerModel): OpenCodeSpec {
  const runtime = layer.runtimes.opencode;
  const declaredEntry = getField(runtime, 'entry') ?? 'index.ts';
  if (
    typeof declaredEntry !== 'string' ||
    !testRelativePath(declaredEntry) ||
    !/\.(ts|js)$/.test(declaredEntry)
  ) {
    throw new Error(`Layer '${layer.name}' opencode.entry must be a relative .ts or .js file.`);
  }
  const entry = convertToMaxstackLockPath(declaredEntry);
  const slash = entry.lastIndexOf('/');
  const dir = slash < 0 ? '' : entry.slice(0, slash);
  if (ordinalEqual(dir, '') && !ordinalEqual(entry, 'index.ts')) {
    throw new Error(
      `Layer '${layer.name}' has the root entry ${entry}. Only index.ts loads from the plugin folder itself; put other entries in a subfolder.`,
    );
  }
  const agents = getField(runtime, 'agents');
  if (agents !== null && agents !== undefined && !testRelativePath(agents)) {
    throw new Error(`Layer '${layer.name}' opencode.agents must be a relative folder.`);
  }
  return {
    entry,
    dir,
    loader: ordinalEqual(dir, '') ? 'discovery' : 'config',
    agents: (agents as string | null) ?? null,
  };
}

export function getOpenCodeItems(layer: LayerModel, root: string): string[] {
  let files = getField(layer.declared.opencode, 'files');
  if (files === null || files === undefined) files = getField(readLayerJson(root), 'files');
  if (files === null || files === undefined || !Array.isArray(files) || files.length === 0) {
    throw new Error(
      `Layer '${layer.name}' names no OpenCode files: set runtimes.opencode.files, or add a layer.json with files.`,
    );
  }
  return files.map((item) => String(item));
}

export function getOpenCodePluginPath(layer: LayerModel, spec: OpenCodeSpec): string | null {
  if (!ordinalEqual(spec.loader, 'config')) return null;
  return `./.opencode/plugins/${layer.name}/${spec.dir}`;
}

export function getClaudeRecord(layer: LayerModel): Record<string, unknown> | null {
  if (!Object.hasOwn(layer.runtimes, 'claude')) return null;
  if (layer.url !== null) {
    return {
      layer: layer.name,
      plugin: layer.name,
      kind: 'git',
      url: layer.url,
      path: layer.sourcePath,
      commit: layer.commit,
    };
  }
  if (layer.root === null) {
    if (Object.hasOwn(layer.runtimes, 'opencode')) {
      return { layer: layer.name, plugin: layer.name, kind: getLinkRecordKind(), target: `.opencode/plugins/${layer.name}` };
    }
    return { layer: layer.name, plugin: layer.name, kind: 'copy', items: null };
  }
  const manifestPath = joinMaxstackPath(layer.root, '.claude-plugin/plugin.json');
  if (!isFile(manifestPath)) {
    throw new Error(
      `Layer '${layer.name}' has a claude runtime but no .claude-plugin/plugin.json at ${layer.root}. Add the manifest to that repository or remove its claude runtime.`,
    );
  }
  let declared: unknown;
  try {
    declared = getField(JSON.parse(readText(manifestPath)) as unknown, 'name');
  } catch {
    declared = null;
  }
  if (!ordinalEqual(declared, layer.name)) {
    throw new Error(
      `Layer '${layer.name}' is the Claude plugin '${layer.name}' but its .claude-plugin/plugin.json names '${declared}'.`,
    );
  }
  const items = getOpenCodeItems(layer, layer.root);
  if (!ordinalIn('.claude-plugin', items)) {
    if (layer.defaultGit) {
      return { layer: layer.name, plugin: layer.name, kind: 'copy', items: null };
    }
    throw new Error(
      `Layer '${layer.name}' has a claude runtime but its file list omits .claude-plugin, so the installed copy would not carry the manifest.`,
    );
  }
  if (!Object.hasOwn(layer.runtimes, 'opencode')) {
    return { layer: layer.name, plugin: layer.name, kind: 'copy', items };
  }
  return { layer: layer.name, plugin: layer.name, kind: getLinkRecordKind(), target: `.opencode/plugins/${layer.name}` };
}

export function getStalePluginFolders(wanted: readonly string[]): string[] {
  if (!isDirectory(S.opencodePluginsTarget)) return [];
  return readdirSync(S.opencodePluginsTarget, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && !ordinalIn(entry.name, wanted))
    .map((entry) => entry.name);
}

// ---- Selection ------------------------------------------------------------------------------------------

const RUNTIME_ARTIFACTS: Record<string, string[]> = {
  claude: ['.claude/plugins'],
  opencode: ['opencode.jsonc', '.opencode/plugins', '.opencode/agents'],
  copilot: ['.maxstack/bin/copilot.sh'],
  pi: ['.maxstack/bin/pi.sh', '.pi/agent/settings.json'],
  codex: ['.codex/config.toml'],
  cursor: ['.cursor/skills', '.cursor/hooks.json'],
  antigravity: ['.agents/hooks.json'],
};

/** The names a -Runtimes or -Layers value picks. */
export function getNamedValues(values: readonly string[], valid: readonly string[], parameter: string): string[] {
  const names = values
    .flatMap((value) => value.split(','))
    .map((value) => value.trim())
    .filter((value) => value.length > 0);
  const choices = `${valid.join(', ')}, or all`;
  if (names.length === 0) throw new Error(`-${parameter} names no value. Valid names: ${choices}.`);
  const picked: string[] = [];
  for (const name of names) {
    assertBoundaryText(name, `-${parameter} name`);
    if (ordinalEqualIgnoreCase(name, 'all')) {
      picked.push(...valid);
      continue;
    }
    const match = valid.find((candidate) => ordinalEqualIgnoreCase(candidate, name));
    if (match === undefined) {
      throw new Error(`-${parameter} names an unknown name '${name}'. Valid names: ${choices}.`);
    }
    picked.push(match);
  }
  return sortUtf8(ordinalUnique(picked));
}

/** The selection an apply records: named values add to the recorded set and never remove from it. */
export function mergeSelected(
  recorded: readonly string[] | null,
  all: readonly string[],
  named: readonly string[],
  hasNames: boolean,
  label: string,
): string[] {
  if (!hasNames) return sortUtf8(recorded ?? all);
  const merged: string[] = recorded === null ? [] : [...recorded];
  const added = named.filter((name) => !ordinalIn(name, merged));
  if (recorded !== null && added.length === 0) {
    writeHost(
      `Already selected ${label}: ${named.join(', ')}. Flags never narrow the selection; the rest stay selected.`,
    );
  }
  merged.push(...named);
  return sortUtf8(ordinalUnique(merged));
}

/** Fails when copilot or pi is selected without claude. */
export function assertSelectionRuntimes(runtimes: readonly string[], fromSettings: readonly string[] = []): void {
  for (const dependent of ['copilot', 'pi']) {
    if (ordinalIn(dependent, runtimes) && !ordinalIn('claude', runtimes)) {
      const source = ordinalIn(dependent, fromSettings)
        ? ` maxstack.settings.json names '${dependent}'; add claude there or remove '${dependent}' from it.`
        : '';
      throw new Error(
        `Runtime '${dependent}' needs claude: its wrapper or settings name the Claude plugin folders, so select claude with it.${source}`,
      );
    }
  }
}

/** The recorded names that are still valid. */
export function getRecordedNames(
  names: unknown,
  valid: readonly string[],
  kind: string,
  fallback: readonly string[] | null = null,
): string[] {
  const list = Array.isArray(names) ? names : [];
  if (list.length === 0 || list.some((name) => typeof name !== 'string' || name.length === 0)) {
    throw new Error(`stack.lock.json selection needs a list of ${kind} names.`);
  }
  const strings = list.map((name) => String(name));
  if (ordinalUnique(strings).length !== strings.length) {
    throw new Error(`stack.lock.json selection names a ${kind} twice.`);
  }
  for (const name of strings) {
    if (!ordinalIn(name, valid)) {
      writeWarning(
        `The recorded selection names the ${kind} '${name}', which is no longer in layers.json. It is dropped from the selection, and the next apply removes what it installed.`,
      );
    }
  }
  const known = strings.filter((name) => ordinalIn(name, valid));
  if (known.length === 0) return sortUtf8(fallback ?? valid);
  return sortUtf8(known);
}

/** The selection a lock records, or null when there is no lock. */
export function readRecordedSelection(
  stack: Record<string, unknown> | null,
  layerNames: readonly string[],
): { runtimes: string[]; layers: string[] } | null {
  if (stack === null) return null;
  const recorded = getField(stack, 'selection');
  if (recorded === null || recorded === undefined) {
    return { runtimes: sortUtf8(DEFAULT_RUNTIME_NAMES), layers: sortUtf8(layerNames) };
  }
  return {
    runtimes: getRecordedNames(getField(recorded, 'runtimes'), RUNTIME_NAMES, 'runtime', DEFAULT_RUNTIME_NAMES),
    layers: getRecordedNames(getField(recorded, 'layers'), layerNames, 'layer'),
  };
}

export function formatSelection(runtimes: readonly string[], layers: readonly string[]): string {
  return `Selection: runtimes ${runtimes.join(', ')}; layers ${layers.join(', ')}`;
}

/** The lock an earlier apply wrote. */
export function readPriorLock(): StackDocument {
  const text = readText(S.stackTarget);
  assertSurrogateEscapes(text, 'stack.lock.json');
  let parsed: unknown = null;
  if (text.trim().length > 0) {
    try {
      parsed = JSON.parse(text);
    } catch {
      parsed = null;
    }
  }
  if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
    assertTextBoundaryTree(parsed, 'stack.lock.json');
    assertLockShape(parsed);
    return parsed as StackDocument;
  }
  throw new Error(
    `${S.stackTarget} is empty, null, or truncated, so its selection and created-paths record cannot be read. ` +
      `Restore it from ${S.stackTarget}.bak if that file exists and reads, or repair it by hand. ` +
      `Deleting ${S.stackTarget} instead resets the selection to all runtimes and layers and loses the createdDirs and createdFiles record. ` +
      `Keep ${S.stackTarget}.bak either way: it holds the lock the last apply replaced.`,
  );
}

/** The lock is replaced whole, through a temporary file beside it. The replaced lock is kept as .bak. */
export function writeLockAtomically(text: string): void {
  const temp = `${S.stackTarget}.new`;
  writeFileSync(temp, text, 'utf8');
  if (isFile(S.stackTarget)) {
    copyFileSync(S.stackTarget, `${S.stackTarget}.bak`);
    renameSync(temp, S.stackTarget);
  } else {
    renameSync(temp, S.stackTarget);
  }
}

/** The layers and runtimes layers.json names that the selection leaves out. */
export function getUnselectedNotes(
  allLayers: readonly LayerModel[],
  selectedLayers: readonly string[],
  selectedRuntimes: readonly string[],
): Array<{ kind: string; name: string; flag: string }> {
  const notes: Array<{ kind: string; name: string; flag: string }> = [];
  for (const layer of allLayers) {
    if (!ordinalIn(layer.name, selectedLayers)) notes.push({ kind: 'layer', name: layer.name, flag: '-Layers' });
  }
  const declared = ordinalUnique(allLayers.flatMap((layer) => Object.keys(layer.declared)));
  for (const runtime of RUNTIME_NAMES) {
    if (ordinalIn(runtime, declared) && !ordinalIn(runtime, selectedRuntimes)) {
      notes.push({ kind: 'runtime', name: runtime, flag: '-Runtimes' });
    }
  }
  return notes;
}

/** The artifacts of the runtimes that are not selected and that exist on disk. */
export function getNotSelectedPaths(selectedRuntimes: readonly string[]): string[] {
  const found: string[] = [];
  for (const runtime of RUNTIME_NAMES) {
    if (ordinalIn(runtime, selectedRuntimes)) continue;
    for (const path of RUNTIME_ARTIFACTS[runtime] ?? []) {
      if (pathExists(workspaceFull(path))) found.push(path);
    }
  }
  return sortUtf8(found);
}

// ---- npm lock handling ----------------------------------------------------------------------------------

/** The lock files of a folder before npm runs. */
export function getShippedLocks(folder: string): Map<string, Buffer | null> {
  const shipped = new Map<string, Buffer | null>();
  for (const name of NPM_LOCK_NAMES) {
    const path = joinMaxstackPath(folder, name);
    shipped.set(name, isFile(path) ? readFileSync(path) : null);
  }
  return shipped;
}

/** Puts back the bytes a layer ships. */
export function setShippedFile(path: string, bytes: Buffer): void {
  if (!isFile(path)) {
    writeFileSync(path, bytes);
    return;
  }
  if (readFileSync(path).equals(bytes)) return;
  writeFileSync(path, bytes);
}

/** Each npm lock file ends as the layer ships it. */
export function resolveNpmLocks(folder: string, shipped: Map<string, Buffer | null>): void {
  for (const name of NPM_LOCK_NAMES) {
    const path = joinMaxstackPath(folder, name);
    const bytes = shipped.get(name) ?? null;
    if (bytes !== null) {
      setShippedFile(path, bytes);
      continue;
    }
    if (isFile(path)) {
      removeOwnedTree(path);
      writeHost(`Removed ${path}: npm wrote it, and the layer does not ship ${name}`);
    }
  }
}

/** Warns about a layer whose install scripts or native build did not run. */
export function writeIgnoredScriptWarning(name: string, folder: string): void {
  let declared: string[] = [];
  const packagePath = joinMaxstackPath(folder, 'package.json');
  if (isFile(packagePath)) {
    try {
      const scripts = getField(JSON.parse(readText(packagePath)) as unknown, 'scripts');
      declared = ['preinstall', 'install', 'postinstall']
        .filter((script) => getField(scripts, script) !== null && getField(scripts, script) !== undefined)
        .map((script) => `scripts.${script}`);
    } catch {
      declared = [];
    }
  }
  if (isFile(joinMaxstackPath(folder, 'binding.gyp'))) declared.push('binding.gyp');
  if (declared.length > 0) {
    writeWarning(
      `npm ran with --ignore-scripts for layer '${name}': its ${declared.join(', ')} did not run, so what it would build or install is missing.`,
    );
  }
  const dependencies = getScriptedDependencies(folder);
  if (dependencies.length > 0) {
    const shown = dependencies.slice(0, 10);
    const more = dependencies.length - shown.length;
    const tail = more > 0 ? ` (and ${more} more)` : '';
    writeWarning(
      `npm ran with --ignore-scripts for layer '${name}': ${dependencies.length} installed packages declare install scripts or a native build, which did not run: ${shown.join(', ')}${tail}.`,
    );
  }
}

export function getScriptedDependencies(folder: string): string[] {
  try {
    return readScriptedDependencies(folder);
  } catch {
    return [];
  }
}

function readScriptedDependencies(folder: string): string[] {
  const modules = join(folder, 'node_modules');
  if (!isDirectory(modules)) return [];
  const packages: Array<{ name: string; full: string; scope: string | null }> = [];
  for (const entry of readdirSync(modules, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const full = join(modules, entry.name);
    if (entry.name.startsWith('@')) {
      for (const child of readdirSync(full, { withFileTypes: true })) {
        if (child.isDirectory()) packages.push({ name: child.name, full: join(full, child.name), scope: entry.name });
      }
    } else {
      packages.push({ name: entry.name, full, scope: null });
    }
  }
  const scripted: string[] = [];
  for (const pkg of packages) {
    const manifest = join(pkg.full, 'package.json');
    if (!isFile(manifest)) continue;
    let json: unknown;
    try {
      json = JSON.parse(readText(manifest));
    } catch {
      continue;
    }
    const scripts = getField(json, 'scripts');
    const hasScript = ['preinstall', 'install', 'postinstall'].some(
      (script) => getField(scripts, script) !== null && getField(scripts, script) !== undefined,
    );
    if (hasScript || isTrue(getField(json, 'gypfile'))) {
      scripted.push(pkg.scope ? `${pkg.scope}/${pkg.name}` : pkg.name);
    }
  }
  return ordinalSorted(ordinalUnique(scripted));
}

/** Copies the named items of a layer root into a folder. */
export function copyLayerItems(root: string, items: readonly string[], destination: string): void {
  mkdirSync(destination, { recursive: true });
  for (const item of items) {
    const source = joinMaxstackPath(root, convertToMaxstackPath(item));
    if (!pathExists(source)) throw new Error(`Layer item missing: ${source}`);
    const target = joinMaxstackPath(destination, convertToMaxstackPath(item));
    mkdirSync(dirname(target), { recursive: true });
    copyTree(source, target);
  }
}

/** Copies a whole layer folder for Claude, without the cache's .git. */
export function copyWholeFolder(root: string, destination: string): void {
  copyTree(root, destination);
  const git = joinMaxstackPath(destination, '.git');
  if (pathExists(git)) removeOwnedTree(git);
}

// ---- Wrappers -------------------------------------------------------------------------------------------

/** Whether a wrapper can run a path. */
export function testWrapperTarget(path: string, windows = IS_WINDOWS): boolean {
  const extension = extname(path);
  if (windows) return ordinalIn(extension, ['.exe', '.cmd', '.bat']);
  return !ordinalIn(extension, ['.ps1', '.cmd', '.bat']);
}

/** The first application named name that a wrapper can run, outside .maxstack/bin. */
export function findWrappedExecutable(name: string): string | null {
  const binPrefix = `${resolve(S.copilotBinTarget).replace(/[\\/]+$/, '')}/`;
  const consider = (candidate: string): string | null => {
    if (!pathExists(candidate) || !isFile(candidate) || !testWrapperTarget(candidate)) return null;
    if (resolve(candidate).startsWith(binPrefix)) return null;
    return candidate;
  };
  // Get-Command resolves a path itself and only searches PATH for a bare command name.
  if (isAbsolute(name) || name.includes('/') || name.includes('\\')) return consider(resolve(name));
  for (const folder of (process.env.PATH ?? '').split(process.platform === 'win32' ? ';' : ':')) {
    if (!folder) continue;
    const found = consider(join(folder, name));
    if (found !== null) return found;
  }
  return null;
}

/** The Pi CLI a wrapper runs: the workspace copy first, then PATH outside .maxstack/bin. */
export function findPiExecutable(): string | null {
  const localName = IS_WINDOWS ? 'pi.cmd' : 'pi';
  const local = joinMaxstackPath(S.piLocalBinTarget, localName);
  if (isFile(local)) return local;
  return findWrappedExecutable(S.piCommand);
}

/** T3 spawns binaryPath directly, so a .sh wrapper carries the executable bit off Windows. */
export function setShellExecutable(path: string): void {
  if (IS_WINDOWS) return;
  const { chmodSync } = require('node:fs') as typeof import('node:fs');
  chmodSync(path, 0o755);
}

function assertQuotablePath(paths: readonly string[]): void {
  for (const path of paths) {
    if (/["%\r\n]/.test(path)) {
      throw new Error(
        `Path '${path}' holds a quote, a percent sign, or a line break, which the Copilot wrapper cannot quote.`,
      );
    }
  }
}

function assertCopilotInstructionDirectory(path: string): void {
  assertQuotablePath([path]);
  if (path.includes(',')) {
    throw new Error(
      `Copilot instruction directory '${path}' contains a comma, which is ambiguous in COPILOT_CUSTOM_INSTRUCTIONS_DIRS.`,
    );
  }
  if (path.includes('!')) {
    throw new Error(
      `Copilot instruction directory '${path}' contains '!', which cmd delayed expansion can remove. Rename the workspace directory and rerun.`,
    );
  }
}

/** The Windows Copilot wrapper. */
export function newCopilotCmdText(
  executable: string,
  pluginDirs: readonly string[],
  instructionDirectory: string | null,
): string {
  assertQuotablePath([executable, ...pluginDirs]);
  if (instructionDirectory) assertCopilotInstructionDirectory(instructionDirectory);
  const plugins = pluginDirs.map((dir) => ` --plugin-dir "${dir}"`).join('');
  const invoke = ordinalIn(extname(executable), ['.cmd', '.bat']) ? 'call ' : '';
  const lines = [
    '@echo off',
    'rem Generated by scripts\\Install-Workspace.ps1. Rerun the installer instead of editing this file.',
    'rem Starts the GitHub Copilot CLI with the workspace plugin folders, in layer order.',
  ];
  if (instructionDirectory) {
    lines.push(
      `if defined COPILOT_CUSTOM_INSTRUCTIONS_DIRS set "COPILOT_CUSTOM_INSTRUCTIONS_DIRS=%COPILOT_CUSTOM_INSTRUCTIONS_DIRS%,${instructionDirectory}"`,
    );
    lines.push(
      `if not defined COPILOT_CUSTOM_INSTRUCTIONS_DIRS set "COPILOT_CUSTOM_INSTRUCTIONS_DIRS=${instructionDirectory}"`,
    );
  }
  lines.push(`${invoke}"${executable}"${plugins} %*`);
  return `${lines.join('\r\n')}\r\n`;
}

/** The POSIX Copilot wrapper. */
export function newCopilotShText(pluginDirs: readonly string[], instructionDirectory: string | null): string {
  assertQuotablePath(pluginDirs);
  if (instructionDirectory) assertCopilotInstructionDirectory(instructionDirectory);
  const plugins = pluginDirs.map((dir) => ` --plugin-dir "${dir.replaceAll('\\', '/')}"`).join('');
  const reference = IS_WINDOWS ? ' See copilot.cmd.' : '';
  const lines = [
    '#!/bin/sh',
    '# Generated by scripts/Install-Workspace.ps1. Rerun the installer instead of editing this file.',
    `# Starts the GitHub Copilot CLI with the workspace plugin folders, in layer order.${reference}`,
  ];
  if (instructionDirectory) {
    const escaped = instructionDirectory.replaceAll('\\', '/').replaceAll("'", "'\\''");
    lines.push(
      `export COPILOT_CUSTOM_INSTRUCTIONS_DIRS="\${COPILOT_CUSTOM_INSTRUCTIONS_DIRS:+\${COPILOT_CUSTOM_INSTRUCTIONS_DIRS},}"'${escaped}'`,
    );
  }
  lines.push('command -v copilot >/dev/null 2>&1 || { echo "copilot is not on PATH" >&2; exit 127; }');
  lines.push(`exec copilot${plugins} "$@"`);
  return `${lines.join('\n')}\n`;
}

/** The Windows Pi wrapper. */
export function newPiCmdText(
  executable: string,
  agentDir: string,
  npmPrefix: string,
  piLocal: boolean,
): string {
  assertQuotablePath([executable, agentDir, npmPrefix]);
  const updateAction: string[] = [];
  if (piLocal) {
    updateAction.push('node "%~dp0pi-self-update.mjs" %*');
    updateAction.push('exit /b %ERRORLEVEL%');
  } else {
    updateAction.push(
      `echo Refusing to update selected external Pi at "${executable}"; only the managed workspace local Pi can use update --self. 1>&2`,
    );
    updateAction.push('exit /b 2');
  }
  const lines = [
    '@echo off',
    'rem Generated by scripts\\Install-Workspace.ps1. Rerun the installer instead of editing this file.',
    'rem Starts Pi with the workspace agent folder, so its settings load the pstack, org, and personal layers.',
    'if "%~1"=="update" if "%~2"=="--self" goto update_pi',
    `set "PI_CODING_AGENT_DIR=${agentDir}"`,
    `set "PI_BIN=${executable}"`,
    'if defined MAXSTACK_PI_BIN set "PI_BIN=%MAXSTACK_PI_BIN%"',
    'for %%F in ("%PI_BIN%") do set "PI_EXT=%%~xF"',
    'if /i "%PI_EXT%"==".cmd" goto call_pi',
    'if /i "%PI_EXT%"==".bat" goto call_pi',
    '"%PI_BIN%" %*',
    'exit /b %ERRORLEVEL%',
    ':call_pi',
    'call "%PI_BIN%" %*',
    'exit /b %ERRORLEVEL%',
    ':update_pi',
    ...updateAction,
  ];
  return `${lines.join('\r\n')}\r\n`;
}

function assertShellPath(paths: readonly string[]): void {
  for (const path of paths) {
    if (/["$`\r\n]/.test(path)) {
      throw new Error(
        `Path '${path}' holds a double quote, a dollar sign, a backtick, or a line break, so the Pi shell wrapper cannot quote it.`,
      );
    }
  }
}

/** The POSIX Pi wrapper. */
export function newPiShText(
  agentDir: string,
  localExecutable: string,
  npmPrefix: string,
  piLocal: boolean,
  selectedExecutable: string,
): string {
  assertShellPath([agentDir, npmPrefix, selectedExecutable]);
  const safeArgs = getPiNpmSafetyArgs().join(' ');
  let resolveLine = 'pi_bin="${MAXSTACK_PI_BIN:-$(command -v pi 2>/dev/null)}"';
  if (localExecutable) {
    assertShellPath([localExecutable]);
    if (localExecutable.includes('}')) {
      throw new Error(
        `Path '${localExecutable}' holds a closing brace, so the Pi shell wrapper cannot quote it.`,
      );
    }
    resolveLine = `pi_bin="\${MAXSTACK_PI_BIN:-${localExecutable.replaceAll('\\', '/')}}"`;
  }
  const reference = IS_WINDOWS ? ' See pi.cmd.' : '';
  let updateAction: string;
  if (piLocal) {
    updateAction = [
      '  [ "$#" -eq 2 ] || { echo "Usage: pi update --self" >&2; exit 2; } # ordinal-ok: POSIX shell argument count is numeric ASCII',
      '  [ -z "${MAXSTACK_PI_BIN:-}" ] || { echo "MAXSTACK_PI_BIN is set. Refusing to update an overridden Pi; selected local Pi: __SELECTED__" >&2; exit 2; }',
      '  [ -f "__PREFIX__/node_modules/@earendil-works/pi-coding-agent/package.json" ] || { echo "Managed Pi package is missing at __PREFIX__. Refusing to create a new install." >&2; exit 2; }',
      '  command -v npm >/dev/null 2>&1 || { echo "npm was not found on PATH. Refusing to update selected local Pi: __SELECTED__" >&2; exit 127; }',
      '  npm install --prefix "__PREFIX__" __SAFE_ARGS__ @earendil-works/pi-coding-agent@latest',
      '  exit $?',
    ]
      .join('\n')
      .replaceAll('__PREFIX__', npmPrefix.replaceAll('\\', '/'))
      .replaceAll('__SAFE_ARGS__', safeArgs)
      .replaceAll('__SELECTED__', selectedExecutable.replaceAll('\\', '/'));
  } else {
    updateAction = `  echo "Refusing to update selected external Pi at __SELECTED__; only the managed workspace local Pi can use update --self." >&2; exit 2`.replaceAll(
      '__SELECTED__',
      selectedExecutable.replaceAll('\\', '/'),
    );
  }
  const lines = [
    '#!/bin/sh',
    '# Generated by scripts/Install-Workspace.ps1. Rerun the installer instead of editing this file.',
    `# Starts Pi with the workspace agent folder, so its settings load the pstack, org, and personal layers.${reference}`,
    'if [ "$#" -ge 2 ] && [ "$1" = update ] && [ "$2" = --self ]; then',
    updateAction,
    'fi',
    `export PI_CODING_AGENT_DIR="${agentDir.replaceAll('\\', '/')}"`,
    resolveLine,
    '[ -n "$pi_bin" ] || { echo "pi is not on PATH" >&2; exit 127; }',
    'exec "$pi_bin" "$@"',
  ];
  return `${lines.join('\n')}\n`;
}

// ---- Claude children, Pi records, and plan records -----------------------------------------------------

/** Whether a Claude child is missing, differs from what the last apply recorded, or matches it. */
export function getClaudeChildState(
  record: Record<string, unknown>,
  prior: Record<string, unknown> | null,
  child: string,
  target: string | null,
): string {
  if (getEntryItem(child) === null) return 'missing';
  const kind = getField(record, 'kind');
  if (isLinkRecordKind(kind)) {
    if (!testClaudeLink(child, target as string, String(kind))) return 'differs';
    if (!isDirectory(target as string)) return 'differs';
  } else if (isMaxstackLink(child)) {
    return 'differs';
  }
  if (prior === null || !ordinalEqual(getField(prior, 'kind'), kind)) return 'differs';
  if (
    ordinalEqual(kind, 'git') &&
    !ordinalSame(getField(prior, 'commit'), getField(record, 'commit'))
  ) {
    return 'differs';
  }
  const treeRoot = isLinkRecordKind(kind) ? (target as string) : child;
  if (isMaxstackLink(treeRoot)) return 'differs';
  if (!ordinalSame(getField(prior, 'treeSha256'), getLegacyTreeSha256(treeRoot))) return 'differs';
  return 'matches';
}

export interface PiLayerRecord {
  layer: string;
  pi: unknown;
  package: string | null;
  packageRoot: string | null;
  packageEntry: string | null;
  skills: string | null;
  pending: boolean;
  unknownPackage: string;
  unknownSkills: string;
}

/** A layer's Pi record. A pinned package uses the root of its cache; a local package points at the source repo. */
export function getPiLayerRecord(layer: LayerModel): PiLayerRecord | null {
  if (!Object.hasOwn(layer.runtimes, 'pi')) return null;
  const pinned = layer.url !== null;
  const repo = pinned
    ? joinMaxstackPath(S.claudeCacheTarget, layer.name)
    : (layer.repoRoot as string);
  const pluginSource = joinSourceSub(repo, layer.sourcePath);
  const manifest = joinMaxstackPath(repo, 'package.json');
  let piKey: unknown = null;
  if (isFile(manifest)) {
    try {
      piKey = getField(JSON.parse(readText(manifest)) as unknown, 'pi');
    } catch {
      piKey = null;
    }
  }
  const installed = `.claude/plugins/${layer.name}`;
  let packageEntry: string | null = null;
  let packagePath: string | null = pinned ? `.claude/cache/${layer.name}` : installed;
  if (piKey !== null && piKey !== undefined && !pinned) {
    const agentRoot = joinMaxstackPath(S.workspace, '.pi/agent');
    packageEntry = maxstackRelativePath(agentRoot, repo);
    packagePath = maxstackRelativePath(S.workspace, repo);
  }
  const packageRoot =
    piKey !== null && piKey !== undefined && !pinned
      ? repo
      : pinned
        ? joinMaxstackPath(S.claudeCacheTarget, layer.name)
        : null;
  return {
    layer: layer.name,
    pi: piKey,
    package: piKey !== null && piKey !== undefined ? packagePath : null,
    packageRoot,
    packageEntry: pinned ? `../../.claude/cache/${layer.name}` : packageEntry,
    skills: isDirectory(joinMaxstackPath(pluginSource, 'skills')) ? `${installed}/skills` : null,
    pending: layer.root === null,
    unknownPackage: pinned ? `.claude/cache/${layer.name}` : installed,
    unknownSkills: `${installed}/skills`,
  };
}

/** Every path a pi key names must exist in the installed copy, or Pi would load less than the layer declares. */
export function assertPiKeyInstalled(record: PiLayerRecord): void {
  const installed = record.packageRoot as string;
  if (!isFile(joinMaxstackPath(installed, 'package.json'))) {
    throw new Error(
      `Layer '${record.layer}' has a pi key in its package.json, but its installed copy at ${installed} has no package.json. Add package.json to the layer's files list.`,
    );
  }
  for (const kind of ['extensions', 'skills', 'prompts', 'themes']) {
    const entries = getField(record.pi, kind);
    if (!Array.isArray(entries)) continue;
    for (const entry of entries) {
      if (!testNonEmptyString(entry)) continue;
      if (!pathExists(joinMaxstackPath(installed, convertToMaxstackPath(String(entry))))) {
        throw new Error(
          `Layer '${record.layer}' names the ${kind} entry ${String(entry)} in its package.json pi key, but ${installed} does not carry it. Add the folder to the layer's files list.`,
        );
      }
    }
  }
}

/** The Pi entries a previous apply recorded as its own under one key. */
export function getOwnedPiEntries(
  owned: readonly (OwnedRecord | null)[] | null,
  legacyPi: Record<string, unknown> | null,
  key: string,
): unknown[] {
  if (owned === null) {
    const entries = getField(legacyPi, key);
    return Array.isArray(entries) ? entries : [];
  }
  const record = owned.find(
    (entry) =>
      entry !== null &&
      ordinalEqual(entry.kind, 'json-entries') &&
      ordinalEqual(entry.path, '.pi/agent/settings.json') &&
      ordinalEqual(entry.key, key),
  );
  return record ? (record.entries ?? []) : [];
}

export interface PiSettingsResult {
  text: string;
  added: { packages: string[]; skills: string[] };
  sourceSha: string | null;
}

/** The workspace Pi settings the installer would write, and the entries it adds to each list. */
export function getPiSettings(
  packages: readonly string[],
  skills: readonly string[],
  ownedPackages: readonly unknown[],
  ownedSkills: readonly unknown[],
): PiSettingsResult {
  const sourceSha = sha256FileOrNull(S.piSettingsTarget);
  let root: Record<string, unknown> = {};
  if (sourceSha !== null) {
    try {
      root = readStrictJsonObject(readFileSync(S.piSettingsTarget, 'utf8'));
    } catch (error) {
      throw new Error(
        `${S.piSettingsTarget} is not strict JSON (${(error as Error).message}): it has comments, trailing commas, or is not an object. The installer will not rewrite it. Remove those, then rerun -Apply.`,
      );
    }
  }
  const added: { packages: string[]; skills: string[] } = {
    packages: mergeJsonEntries(root, 'packages', packages, ownedPackages),
    skills: mergeJsonEntries(root, 'skills', skills, ownedSkills),
  };
  return { text: `${jsonText(root)}\n`, added, sourceSha };
}

// ---- Wrapper ownership ----------------------------------------------------------------------------------

function assertWritten(path: string, disk: string | null, planned: string | null): void {
  // PowerShell's -ne compares hex digests without regard to case, so a lowercase planned hash still matches.
  if (!(disk === planned || ordinalEqualIgnoreCase(disk, planned))) {
    throw new Error(
      `${path} holds different content from what the install wrote, so no ownership record was written. Remove the file or folder and apply again.`,
    );
  }
}

/** The lock's record of a wrapper the installer wrote, or null. */
export function getWrapperRecord(relative: string): OwnedRecord | null {
  if (S.priorOwned === null) return null;
  return (
    S.priorOwned.find(
      (record) =>
        record !== null && ordinalEqual(record.path, relative) && ordinalEqual(record.kind, 'file'),
    ) ?? null
  );
}

/** A stale wrapper goes only when it is the installer's recorded copy. */
export function removeWrapperIfRecorded(path: string): void {
  const record = getWrapperRecord(`.maxstack/bin/${path.slice(path.lastIndexOf('/') + 1)}`);
  if (record === null || !testRecordedFile(path, record.sha256 ?? null)) {
    writeHost(`Kept ${path}: it is not the installer's recorded copy (changed by hand, or never recorded)`);
    return;
  }
  removeOwnedTree(path);
  writeHost(`Removed the stale wrapper ${path}`);
}

/** The text of a wrapper the lock records as the installer's own, or null. */
export function getRecordedWrapperText(relative: string): string | null {
  const full = joinMaxstackPath(S.workspace, convertToMaxstackPath(relative));
  const record = getWrapperRecord(relative);
  if (record === null || !testRecordedFile(full, record.sha256 ?? null)) return null;
  return readText(full);
}

export interface KeptWrapperPair {
  cmd: string | null;
  sh: string;
}

/** The text of a runtime's wrapper pair, kept when this run cannot find the CLI the pair runs. */
export function getKeptWrapperPair(cmdRelative: string, shRelative: string): KeptWrapperPair | null {
  const cmdText = IS_WINDOWS ? getRecordedWrapperText(cmdRelative) : 'kept-shell-only';
  const shText = getRecordedWrapperText(shRelative);
  const entries: Array<{ path: string; text: string | null }> = [];
  if (IS_WINDOWS) entries.push({ path: cmdRelative, text: cmdText });
  entries.push({ path: shRelative, text: shText });
  for (const entry of entries) {
    const full = joinMaxstackPath(S.workspace, entry.path);
    if (entry.text === null && isFile(full)) {
      writeHost(`Kept ${full}: it is not the installer's recorded copy (changed by hand, or never recorded)`);
    }
  }
  if ((IS_WINDOWS && cmdText === null) || shText === null) return null;
  return { cmd: cmdText, sh: shText };
}

// ---- Ownership plan -------------------------------------------------------------------------------------

export interface OwnedPlanOptions {
  document: string | null;
  layers: readonly LayerModel[];
  claudeRecords: ReadonlyArray<Record<string, unknown>>;
  openCodeLayers: readonly LayerModel[];
  openCodeSpecs: Map<string, OpenCodeSpec>;
  copilotCmdText: string | null;
  copilotShText: string | null;
  piCmdText: string | null;
  piShText: string | null;
  piUpdaterText: string | null;
  piUpdaterPreserveRecord: OwnedRecord | null;
  piSettings: PiSettingsResult | null;
  piPending: boolean;
  piUnknown: { packages: string[]; skills: string[] };
  codexSkills?: readonly SkillEntry[];
  skillRuntimeClaims?: string[];
  cursorSkills?: readonly SkillEntry[];
  workspaceInstructionFiles?: readonly WorkspaceInstructionFile[];
  agentHookPlans?: ReadonlyArray<HookConfigPlan | null>;
  configBackupTarget: BackupTarget;
  settingsBackupTarget: BackupTarget;
}

/** What the installer would own after an apply, from the same layers and texts the apply writes. */
export function getOwnedPlan(options: OwnedPlanOptions): OwnedRecord[] {
  const records: OwnedRecord[] = [];
  const layerByName = new Map<string, LayerModel>();
  for (const layer of options.layers) layerByName.set(layer.name, layer);

  if (options.document !== null) {
    const configExists = isFile(S.configTarget);
    const configText = configExists ? readText(S.configTarget) : null;
    const configUnchanged =
      configText !== null && ordinalEqual(configText.trim(), options.document.trim());
    let configSha: string | null = getTextSha256(options.document);
    if (configUnchanged) configSha = sha256FileOrNull(S.configTarget);
    records.push(newOwnedRecord({ path: 'opencode.jsonc', kind: 'file', sha256: configSha, runtime: 'opencode' }));
    records.push(...getBackupRecordsFor('opencode.jsonc', options.configBackupTarget, 'opencode'));
  }

  for (const record of options.claudeRecords) {
    const path = `.claude/plugins/${String(record.plugin)}`;
    const kind = getField(record, 'kind');
    if (isLinkRecordKind(kind)) {
      records.push(
        newOwnedRecord({
          path,
          kind: 'link',
          target: getField(record, 'target') as string,
          runtime: 'claude',
          layers: [String(record.layer)],
        }),
      );
      continue;
    }
    const root = getLayerRoot(layerByName.get(String(record.layer)) as LayerModel, S.claudeCacheTarget);
    let sha: string | null = null;
    const items = getField(record, 'items');
    if (root !== null && ordinalEqual(kind, 'copy') && Array.isArray(items)) {
      sha = getItemsTreeSha256(root, items.map(String));
    } else if (root !== null) {
      sha = getTreeSha256(root);
    }
    records.push(
      newOwnedRecord({
        path,
        kind: 'dir',
        sha256: sha,
        runtime: 'claude',
        layers: [String(record.layer)],
      }),
    );
  }

  for (const layer of options.layers.filter((entry) => entry.url !== null)) {
    let sha: string | null = null;
    if (testCacheAtPin(layer, S.claudeCacheTarget)) {
      sha = getTreeSha256(joinMaxstackPath(S.claudeCacheTarget, layer.name));
    }
    records.push(
      newOwnedRecord({ path: `.claude/cache/${layer.name}`, kind: 'dir', sha256: sha, layers: [layer.name] }),
    );
  }

  const agents = new Map<string, OwnedRecord>();
  for (const layer of options.openCodeLayers) {
    const root = getLayerRoot(layer, S.claudeCacheTarget);
    let sha: string | null = null;
    if (root !== null) {
      const claudeDeclared = Object.hasOwn(layer.runtimes, 'claude');
      const items = getOpenCodeItems(layer, root).filter(
        (item) => !ordinalEqual(item, '.claude-plugin') || claudeDeclared,
      );
      sha = getItemsTreeSha256(root, items);
      const spec = options.openCodeSpecs.get(layer.name) as OpenCodeSpec;
      const agentsSource = spec.agents
        ? joinMaxstackPath(root, convertToMaxstackPath(spec.agents))
        : null;
      if (agentsSource !== null && isDirectory(agentsSource)) {
        // PowerShell's Get-ChildItem sorts by name; readdir does not, so the lock order would differ.
        for (const name of agentFileNames(agentsSource)) {
          const agentPath = joinMaxstackPath(agentsSource, name);
          const text = getAgentProfileText(agentPath);
          const agentSha = text !== null ? getTextSha256(text) : sha256FileOrNull(agentPath);
          const path = `.opencode/agents/${name}`;
          agents.set(
            path,
            newOwnedRecord({ path, kind: 'file', sha256: agentSha, runtime: 'opencode', layers: [layer.name] }),
          );
        }
      }
    }
    records.push(
      newOwnedRecord({
        path: `.opencode/plugins/${layer.name}`,
        kind: 'dir',
        sha256: sha,
        runtime: 'opencode',
        layers: [layer.name],
      }),
    );
  }
  for (const agent of agents.values()) records.push(agent);

  if (options.copilotCmdText) {
    if (IS_WINDOWS) {
      records.push(
        newOwnedRecord({
          path: '.maxstack/bin/copilot.cmd',
          kind: 'file',
          sha256: getTextSha256(options.copilotCmdText),
          runtime: 'copilot',
        }),
      );
    }
    records.push(
      newOwnedRecord({
        path: '.maxstack/bin/copilot.sh',
        kind: 'file',
        sha256: getTextSha256(options.copilotShText as string),
        runtime: 'copilot',
      }),
    );
  }
  if (options.piCmdText) {
    if (IS_WINDOWS) {
      records.push(
        newOwnedRecord({
          path: '.maxstack/bin/pi.cmd',
          kind: 'file',
          sha256: getTextSha256(options.piCmdText),
          runtime: 'pi',
        }),
      );
    }
    if (IS_WINDOWS && options.piUpdaterText) {
      records.push(
        newOwnedRecord({
          path: '.maxstack/bin/pi-self-update.mjs',
          kind: 'file',
          sha256: getTextSha256(options.piUpdaterText),
          runtime: 'pi',
        }),
      );
    }
    records.push(
      newOwnedRecord({
        path: '.maxstack/bin/pi.sh',
        kind: 'file',
        sha256: getTextSha256(options.piShText as string),
        runtime: 'pi',
      }),
    );
  }
  if (options.piUpdaterPreserveRecord !== null) records.push(options.piUpdaterPreserveRecord);

  // A shared .agents skill records both claims, so removing one runtime keeps the other. A codex-only skill keeps the
  // legacy single runtime field the tests and older locks read.
  const sharedSkillClaims = (options.skillRuntimeClaims ?? []).includes('antigravity');
  for (const skill of options.codexSkills ?? []) {
    const skillSha = isTrue(getField(skill, 'preserve')) ? skill.prior?.sha256 : skill.sha256;
    const skillRecord = newOwnedRecord({
      path: `${CODEX_SKILL_FOLDER}/${skill.name}`,
      kind: 'dir',
      sha256: skillSha,
      layers: [skill.layer],
      runtime: 'codex',
      runtimeClaims: sharedSkillClaims ? options.skillRuntimeClaims : [],
    });
    if (isTrue(getField(skill, 'preserve'))) skillRecord.preserve = true;
    records.push(skillRecord);
  }

  for (const skill of options.cursorSkills ?? []) {
    if (isTrue(getField(skill, 'preserve'))) {
      const prior = skill.prior as OwnedRecord;
      records.push({
        path: prior.path,
        kind: prior.kind,
        sha256: prior.sha256,
        runtime: prior.runtime,
        layers: [...(prior.layers ?? [])],
        preserve: true,
      });
    } else {
      records.push(
        newOwnedRecord({
          path: `${CURSOR_SKILL_FOLDER}/${skill.name}`,
          kind: 'dir',
          sha256: skill.sha256,
          runtime: 'cursor',
          layers: [skill.layer],
        }),
      );
    }
  }

  for (const hookPlan of (options.agentHookPlans ?? []).filter(
    (entry): entry is HookConfigPlan => entry !== null,
  )) {
    if (isTrue(getField(hookPlan, 'remove'))) continue;
    if (isTrue(getField(hookPlan, 'preserve'))) {
      const priorHook = getPriorOwnedFileRecord(hookPlan.path);
      if (priorHook !== null) {
        const preservedHook: OwnedRecord = {
          path: priorHook.path,
          kind: priorHook.kind,
          sha256: priorHook.sha256,
          runtime: priorHook.runtime,
          layers: [...(priorHook.layers ?? [])],
          preserve: true,
        };
        if (getField(priorHook, 'hookHash') !== null) preservedHook.hookHash = priorHook.hookHash;
        records.push(preservedHook);
      }
    } else {
      const hookRecord = newOwnedRecord({
        path: hookPlan.path,
        kind: 'file',
        sha256: hookPlan.sha256,
        runtime: hookPlan.runtime,
        layers: hookPlan.layers,
      });
      if (getField(hookPlan, 'hookHash') !== null) hookRecord.hookHash = hookPlan.hookHash;
      records.push(hookRecord);
    }
  }

  for (const file of options.workspaceInstructionFiles ?? []) {
    const record = newOwnedRecord({
      path: file.path,
      kind: 'file',
      sha256: getTextSha256(file.text),
      runtime: file.runtime,
      layers: file.layers,
    });
    if (isTrue(getField(file, 'preserve'))) record.preserve = true;
    records.push(record);
  }

  if (options.piSettings !== null) {
    records.push(
      ...getBackupRecordsFor('.pi/agent/settings.json', options.settingsBackupTarget, 'pi'),
    );
    const piLayerNames = options.layers
      .filter((layer) => Object.hasOwn(layer.runtimes, 'pi'))
      .map((layer) => layer.name);
    for (const key of ['packages', 'skills'] as const) {
      const known = options.piSettings.added[key];
      const unknown = options.piUnknown[key].filter((entry) => !known.includes(entry));
      if (known.length === 0 && unknown.length === 0) continue;
      const record = newOwnedRecord({
        path: '.pi/agent/settings.json',
        kind: 'json-entries',
        key,
        entries: known,
        runtime: 'pi',
        layers: piLayerNames,
      });
      record.unknown = unknown;
      records.push(record);
    }
  }
  return records;
}

/** The lock's records for the plan, once the disk matches it. */
export function getOwnedRecords(
  plan: readonly OwnedRecord[],
  createdKeys: Map<string, boolean>,
): OwnedRecord[] {
  const records: OwnedRecord[] = [];
  for (const record of plan) {
    const full = joinMaxstackPath(S.workspace, convertToMaxstackPath(record.path));
    if (isTrue(getField(record, 'backup')) && !isFile(full)) continue;
    if (isTrue(getField(record, 'preserve'))) {
      const prior =
        (S.priorOwned ?? []).find(
          (entry) =>
            entry !== null &&
            ordinalEqual(entry.path, record.path) &&
            ordinalEqual(entry.kind, record.kind),
        ) ?? null;
      if (prior !== null && getField(record, 'runtimes') !== null) {
        records.push(
          newOwnedRecord({
            path: record.path,
            kind: record.kind,
            sha256: prior.sha256,
            runtimeClaims: record.runtimes,
            layers: record.layers,
          }),
        );
      } else if (prior !== null) {
        records.push(prior);
      }
      continue;
    }
    const runtimeClaims = getField(record, 'runtimes');
    const attribution = {
      runtime: runtimeClaims !== null ? null : (getField(record, 'runtime') as string | null),
      runtimeClaims: runtimeClaims !== null ? (record.runtimes as string[]) : undefined,
      layers: record.layers ?? [],
      role: (getField(record, 'role') as string | null) ?? null,
    };
    if (record.kind === 'file') {
      const disk = sha256FileOrNull(full);
      assertWritten(record.path, disk, record.sha256 ?? null);
      const ownedFile = newOwnedRecord({ path: record.path, kind: 'file', sha256: disk, ...attribution });
      if (getField(record, 'hookHash') !== null) ownedFile.hookHash = record.hookHash;
      records.push(ownedFile);
    } else if (record.kind === 'dir') {
      const disk = getTreeSha256(full);
      assertWritten(record.path, disk, record.sha256 ?? null);
      records.push(newOwnedRecord({ path: record.path, kind: 'dir', sha256: disk, ...attribution }));
    } else if (record.kind === 'link') {
      records.push(
        newOwnedRecord({ path: record.path, kind: 'link', target: record.target, ...attribution }),
      );
    } else if (record.kind === 'json-entries') {
      const entries = (record.entries ?? []).filter((entry) => entry !== null && entry !== undefined);
      if (entries.length > 0) {
        records.push(
          newOwnedRecord({
            path: record.path,
            kind: 'json-entries',
            key: record.key,
            entries,
            createdKey: Boolean(createdKeys.get(String(record.key))),
            ...attribution,
          }),
        );
      }
    }
  }
  return sortOwnedRecords(records);
}

/** The state of one recorded file, folder, or link. */
export function getOwnedState(record: OwnedRecord, planned: OwnedRecord | null): string {
  const full = joinMaxstackPath(S.workspace, convertToMaxstackPath(record.path));
  let plannedSame = planned !== null && ordinalEqual(planned.kind, record.kind);
  if (record.kind === 'link') {
    if (getEntryItem(full) === null) return 'missing';
    if (
      !testClaudeLink(
        full,
        joinMaxstackPath(S.workspace, convertToMaxstackPath(record.target as string)),
      )
    ) {
      return 'modified';
    }
    plannedSame = plannedSame && ordinalEqual(planned?.target, record.target);
  } else if (record.kind === 'file') {
    if (!isFile(full)) return 'missing';
    if (testReparsePoint(full)) return 'modified';
    if (!ordinalEqual(sha256FileOrNull(full), record.sha256 ?? null)) return 'modified';
    plannedSame = plannedSame && ordinalEqual(planned?.sha256, record.sha256);
  } else if (record.kind === 'dir') {
    if (!isDirectory(full)) return 'missing';
    if (isMaxstackLink(full)) return 'modified';
    if (!ordinalEqual(getTreeSha256(full), record.sha256 ?? null)) return 'modified';
    plannedSame = plannedSame && ordinalEqual(planned?.sha256, record.sha256);
  }
  if (plannedSame) return 'matching';
  return 'drifted';
}

export interface OwnershipRow {
  state: string;
  label: string;
}

/** Compares the recorded ownership with the disk and with the plan, and writes nothing. */
export function getOwnershipReport(args: {
  recorded: readonly OwnedRecord[];
  plan: readonly OwnedRecord[];
  selectedRuntimes: readonly string[];
  notSelected: readonly string[];
  skippedLayers?: readonly string[];
}): OwnershipRow[] {
  const results: OwnershipRow[] = [];
  const plannedByKey = new Map<string, OwnedRecord>();
  for (const planned of args.plan) plannedByKey.set(getOwnedKey(planned), planned);
  const recordedKeys = new Set<string>();
  const recordedPaths = new Set<string>();
  const recordedEntries = new Set<string>();
  const notSelectedLabels = new Set<string>();
  for (const record of args.recorded) {
    recordedKeys.add(getOwnedKey(record));
    recordedPaths.add(record.path);
  }
  for (const path of args.notSelected) {
    if (!notSelectedLabels.has(path)) {
      notSelectedLabels.add(path);
      results.push({ state: 'not selected', label: path });
    }
  }

  for (const record of args.recorded) {
    const consumers = getOwnedRuntimeClaims(record);
    if (
      consumers.length > 0 &&
      consumers.filter((name) => ordinalIn(name, args.selectedRuntimes)).length === 0 &&
      !ordinalEqual(getOwnedRuntime(record.path), 't3-gated-instances')
    ) {
      if (!notSelectedLabels.has(record.path)) {
        notSelectedLabels.add(record.path);
        results.push({ state: 'not selected', label: record.path });
      }
      continue;
    }
    const recordLayers = record.layers ?? [];
    if (
      recordLayers.length > 0 &&
      !plannedByKey.has(getOwnedKey(record)) &&
      recordLayers.every((layer) => ordinalIn(layer, args.skippedLayers ?? []))
    ) {
      results.push({ state: 'skipped', label: record.path });
      continue;
    }
    if (!ordinalEqual(record.kind, 'json-entries')) {
      results.push({
        state: getOwnedState(record, plannedByKey.get(getOwnedKey(record)) ?? null),
        label: record.path,
      });
      continue;
    }
    const settingsPath = joinMaxstackPath(S.workspace, convertToMaxstackPath(record.path));
    let settings: unknown = null;
    if (isFile(settingsPath)) {
      try {
        settings = JSON.parse(readText(settingsPath));
      } catch {
        settings = null;
      }
    }
    const present = new Set<string>();
    const presentList = getField(settings, record.key ?? '');
    if (Array.isArray(presentList)) {
      for (const entry of presentList) {
        if (entry !== null && entry !== undefined) present.add(getPiEntryKey(entry));
      }
    }
    const planned = plannedByKey.get(getOwnedKey(record)) ?? null;
    const known = new Set<string>();
    if (planned !== null) {
      for (const entry of planned.entries ?? []) {
        if (entry !== null && entry !== undefined) known.add(getPiEntryKey(entry));
      }
    }
    for (const entry of record.entries ?? []) {
      const entryKey = getPiEntryKey(entry);
      recordedEntries.add(`${record.path}\t${record.key}\t${entryKey}`);
      let state: string;
      if (!present.has(entryKey)) state = 'missing';
      else if (known.has(entryKey)) state = 'matching';
      else state = 'drifted';
      results.push({ state, label: `${record.path} [${record.key}] ${entryKey}` });
    }
  }

  for (const planned of args.plan) {
    if (!ordinalEqual(planned.kind, 'json-entries')) {
      if (
        isTrue(getField(planned, 'backup')) &&
        !isFile(joinMaxstackPath(S.workspace, convertToMaxstackPath(planned.path)))
      ) {
        continue;
      }
      if (!recordedKeys.has(getOwnedKey(planned))) {
        results.push({
          state: isTrue(getField(planned, 'preserve')) ? 'untracked' : 'drifted',
          label: planned.path,
        });
      }
      continue;
    }
    const candidates = [...(planned.entries ?? []), ...((getField(planned, 'unknown') as unknown[]) ?? [])];
    for (const entry of candidates) {
      if (entry === null || entry === undefined) continue;
      const entryKey = getPiEntryKey(entry);
      if (recordedEntries.has(`${planned.path}\t${planned.key}\t${entryKey}`)) continue;
      results.push({ state: 'drifted', label: `${planned.path} [${planned.key}] ${entryKey}` });
    }
  }

  const bin = joinMaxstackPath(S.workspace, '.maxstack/bin');
  if (isDirectory(bin)) {
    for (const entry of readdirSync(bin, { withFileTypes: true })) {
      if (!entry.isFile()) continue;
      const path = `.maxstack/bin/${entry.name}`;
      if (!recordedPaths.has(path) && !notSelectedLabels.has(path)) {
        results.push({ state: 'untracked', label: path });
      }
    }
  }
  const cursorSkillsRoot = joinMaxstackPath(S.workspace, convertToMaxstackPath(CURSOR_SKILL_FOLDER));
  if (ordinalIn('cursor', args.selectedRuntimes) && isDirectory(cursorSkillsRoot)) {
    for (const entry of readdirSync(cursorSkillsRoot, { withFileTypes: true })) {
      const path = `${CURSOR_SKILL_FOLDER}/${entry.name}`;
      if (!recordedPaths.has(path)) results.push({ state: 'untracked', label: path });
    }
  }
  if ((args.skippedLayers ?? []).length > 0) {
    for (const item of results) {
      if (!ordinalEqual(item.state, 'not selected') && skippedLabel(item.label, args.skippedLayers ?? [])) {
        item.state = 'skipped';
      }
    }
  }
  return results;
}

/** The -Update report: what the recorded sources would move to, and what the plan would change. */
export function writeUpdateReport(args: {
  layers: readonly LayerModel[];
  priorStack: Record<string, unknown> | null;
  selectedLayers: readonly string[];
  selectedRuntimes: readonly string[];
  plan: readonly OwnedRecord[];
  owned: readonly OwnedRecord[] | null;
  notSelected: readonly string[];
}): number {
  writeHost('Layer sources (-Update):');
  let changes = 0;
  for (const layer of args.layers.filter((entry) => ordinalIn(entry.name, args.selectedLayers))) {
    const prior = getPriorLayerRecord(args.priorStack, layer.name);
    const priorSource = prior !== null ? getRecordedSourceOf(prior) : null;
    const update = getSourceUpdate(layer, priorSource);
    writeHost(update.line);
    if (update.changed) changes++;
    const hint = getPinHint(layer);
    if (hint !== null) writeHost(hint);
  }
  if (args.owned === null) {
    writeHost('no ownership record; -Update -Apply writes one');
    return changes;
  }
  const results = getOwnershipReport({
    recorded: args.owned,
    plan: args.plan,
    selectedRuntimes: args.selectedRuntimes,
    notSelected: args.notSelected,
  });
  const moving = results.filter((row) => ordinalIn(row.state, ['drifted', 'modified', 'missing']));
  for (const item of moving) writeHost(`  would change ${item.state.padEnd(9)} ${item.label}`);
  return changes + moving.length;
}

// ---- Removal: -Remove and -Uninstall --------------------------------------------------------------------

export interface RemovalItem {
  state: string;
  path: string;
  reason: string;
  action: string;
  records: OwnedRecord[];
  gone: string[];
  full: string | null;
  source: string | null;
  text: string | null;
  expectSha: string | null;
  expectSource: string | null;
  expectTarget: string | null;
  quarantine: string | null;
}

function getEntryItem(path: string): Stats | null {
  try {
    return lstatSync(path);
  } catch {
    return null;
  }
}

/** The full path of a recorded workspace-relative path, refused unless it stays inside the workspace. */
export function resolveWorkspaceEntry(relative: string): {
  ok: boolean;
  full: string | null;
  reason: string | null;
} {
  const refused = 'outside the workspace: the record does not name a workspace path';
  if (
    !testRelativePath(relative) ||
    relative.includes('\\') ||
    ordinalIn(relative, ['stack.lock.json', 'stack.lock.json.bak', 'stack.lock.json.new'])
  ) {
    return { ok: false, full: null, reason: refused };
  }
  const root = trimEndingSeparator(resolve(S.workspace));
  const full = resolve(joinMaxstackPath(root, convertToMaxstackPath(relative)));
  if (!maxstackPathInside(full, root)) {
    return { ok: false, full: null, reason: 'outside the workspace: the path resolves outside it' };
  }
  let folder = dirname(full);
  while (folder.length > root.length) {
    if (pathExists(folder) && testReparsePoint(folder)) {
      return { ok: false, full: null, reason: 'outside the workspace: a folder on its path is a junction' };
    }
    folder = dirname(folder);
  }
  return { ok: true, full, reason: null };
}

/** Whether a target, read from a link, is inside the workspace. */
export function testInsideWorkspace(target: string): boolean {
  if (!target) return false;
  const root = trimEndingSeparator(resolve(S.workspace));
  const full = trimEndingSeparator(resolve(target));
  return maxstackPathEqual(full, root) || maxstackPathInside(full, root);
}

/** Whether a path is a real file whose SHA-256 is the recorded one. */
export function testRecordedFile(full: string, sha256: string | null): boolean {
  if (!sha256) return false;
  const item = getEntryItem(full);
  if (item === null || item.isDirectory() || testReparsePoint(full)) return false;
  return ordinalEqual(sha256FileOrNull(full), sha256);
}

export function newRemovalItem(partial: Partial<RemovalItem> & { state: string; path: string; reason: string }): RemovalItem {
  return {
    action: 'none',
    records: [],
    gone: [],
    full: null,
    source: null,
    text: null,
    expectSha: null,
    expectSource: null,
    expectTarget: null,
    quarantine: null,
    ...partial,
  };
}

export function newSkipItem(path: string, reason: string): RemovalItem {
  return newRemovalItem({ state: 'SKIP', path, reason });
}

export function newGoneItem(
  path: string,
  records: OwnedRecord[],
  reason = 'already gone: nothing to delete',
): RemovalItem {
  return newRemovalItem({ state: 'GONE', path, reason, records });
}

export function getFileRemovalItem(record: OwnedRecord): RemovalItem {
  const entry = resolveWorkspaceEntry(record.path);
  if (!entry.ok) return newSkipItem(record.path, entry.reason as string);
  const item = getEntryItem(entry.full as string);
  if (item === null) return newGoneItem(record.path, [record]);
  if (testReparsePoint(entry.full as string)) {
    return newSkipItem(record.path, 'modified by hand: a link stands where the file was recorded');
  }
  if (item.isDirectory()) {
    return newSkipItem(record.path, 'modified by hand: a folder stands where the file was recorded');
  }
  if (!testRecordedFile(entry.full as string, record.sha256 ?? null)) {
    return newSkipItem(
      record.path,
      'modified by hand: its SHA-256 differs from the record, or the record has none',
    );
  }
  return newRemovalItem({
    state: 'DELETE',
    path: record.path,
    reason: 'SHA-256 matches the record',
    action: 'remove-file',
    records: [record],
    gone: [record.path],
    full: entry.full,
    expectSha: record.sha256 ?? null,
  });
}

interface ExcludedSubtreeReport {
  subtrees: Array<{ path: string; files: number; bytes: number }>;
  outside: string | null;
}

function getExcludedSubtreeReport(root: string): ExcludedSubtreeReport {
  const report: ExcludedSubtreeReport = { subtrees: [], outside: null };
  findExcludedSubtrees(root, '', report);
  return report;
}

function findExcludedSubtrees(dir: string, relative: string, report: ExcludedSubtreeReport): void {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const child of entries) {
    const name = child.name;
    const relativeChild = ordinalEqual(relative, '') ? name : `${relative}/${name}`;
    const childPath = join(dir, name);
    if (testTreeFolderExcluded(relativeChild, 'owned')) {
      measureExcludedSubtree(childPath, relativeChild, report);
    } else if (child.isDirectory() && !testReparsePoint(childPath)) {
      findExcludedSubtrees(childPath, relativeChild, report);
    }
  }
}

function measureExcludedSubtree(dir: string, relative: string, report: ExcludedSubtreeReport): void {
  if (testReparsePoint(dir)) {
    if (!testInsideWorkspace(maxstackLinkTarget(dir))) report.outside = relative;
    report.subtrees.push({ path: relative, files: 0, bytes: 0 });
    return;
  }
  let files = 0;
  let bytes = 0;
  const pending = [dir];
  while (pending.length > 0) {
    const current = pending.pop() as string;
    let entries;
    try {
      entries = readdirSync(current, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const child of entries) {
      const childPath = join(current, child.name);
      if (testReparsePoint(childPath)) {
        if (!testInsideWorkspace(maxstackLinkTarget(childPath))) report.outside = relative;
      } else if (child.isDirectory()) {
        pending.push(childPath);
      } else if (child.isFile()) {
        files++;
        try {
          bytes += statSync(childPath).size;
        } catch {
          // ignore
        }
      }
    }
  }
  report.subtrees.push({ path: relative, files, bytes });
}

function getQuarantineResumeItem(record: OwnedRecord, quarantine: string): RemovalItem {
  const leaf = quarantine.slice(quarantine.lastIndexOf('/') + 1);
  if (
    ordinalEqual(getField(record, 'quarantine'), leaf) &&
    !testReparsePoint(quarantine) &&
    isDirectory(quarantine) &&
    ordinalEqual(getTreeSha256(quarantine), record.sha256 ?? null)
  ) {
    return newRemovalItem({
      state: 'DELETE',
      path: record.path,
      reason: `resumes the removal of the folder quarantined as ${leaf}`,
      action: 'resume-quarantine',
      records: [record],
      gone: [record.path],
      full: quarantine,
      quarantine,
      expectSha: record.sha256 ?? null,
    });
  }
  if (ordinalEqual(getField(record, 'quarantine'), leaf)) {
    return newSkipItem(
      record.path,
      `in the way: ${leaf} holds files that changed since its removal began, so it is kept; delete or move it aside by hand`,
    );
  }
  return newSkipItem(
    record.path,
    `in the way: a folder named ${leaf} exists, and it is not the one an earlier removal quarantined for this path`,
  );
}

export function getDirRemovalItem(record: OwnedRecord): RemovalItem {
  const entry = resolveWorkspaceEntry(record.path);
  if (!entry.ok) return newSkipItem(record.path, entry.reason as string);
  const quarantine = `${entry.full}${QUARANTINE_SUFFIX}`;
  const item = getEntryItem(entry.full as string);
  if (item === null) {
    if (pathExists(quarantine)) return getQuarantineResumeItem(record, quarantine);
    return newGoneItem(record.path, [record]);
  }
  if (testReparsePoint(entry.full as string)) {
    return newSkipItem(record.path, 'modified by hand: a link stands where the folder was recorded');
  }
  if (!item.isDirectory()) {
    return newSkipItem(record.path, 'modified by hand: a file stands where the folder was recorded');
  }
  if (!ordinalEqual(getTreeSha256(entry.full as string), record.sha256 ?? null)) {
    return newSkipItem(
      record.path,
      'modified by hand: a file in it was added, changed, or removed since the install, or the record has no hash',
    );
  }
  if (pathExists(quarantine)) {
    const leaf = quarantine.slice(quarantine.lastIndexOf('/') + 1);
    if (ordinalEqual(getField(record, 'quarantine'), leaf)) {
      return newSkipItem(
        record.path,
        `in the way: ${leaf} holds files that changed since its removal began, so it is kept; delete or move it aside by hand`,
      );
    }
    return newSkipItem(
      record.path,
      `in the way: a folder named ${leaf} already exists, and no removal journal names it`,
    );
  }
  const excluded = getExcludedSubtreeReport(entry.full as string);
  if (excluded.outside !== null) {
    return newSkipItem(
      record.path,
      `refused: a junction under ${record.path}/${excluded.outside} leads outside the workspace`,
    );
  }
  let reason = 'tree hash matches the record';
  const notes = excluded.subtrees.map(
    (subtree) => `${record.path}/${subtree.path} (${subtree.files} files, ${subtree.bytes} bytes)`,
  );
  if (notes.length > 0) reason += `; also deletes the excluded folders ${notes.join(', ')}`;
  return newRemovalItem({
    state: 'DELETE',
    path: record.path,
    reason,
    action: 'remove-dir',
    records: [record],
    gone: [record.path],
    full: entry.full,
    expectSha: record.sha256 ?? null,
    quarantine,
  });
}

export function getLinkRemovalItem(record: OwnedRecord): RemovalItem {
  const entry = resolveWorkspaceEntry(record.path);
  if (!entry.ok) return newSkipItem(record.path, entry.reason as string);
  const target = resolveWorkspaceEntry(record.target as string);
  if (!target.ok) return newSkipItem(record.path, 'its recorded target is outside the workspace');
  const item = getEntryItem(entry.full as string);
  if (item === null) return newGoneItem(record.path, [record]);
  if (!testReparsePoint(entry.full as string)) {
    return newSkipItem(record.path, 'modified by hand: a folder or file stands where the link was recorded');
  }
  if (!testClaudeLink(entry.full as string, target.full as string)) {
    return newSkipItem(record.path, 'modified by hand: the link no longer points at its recorded target');
  }
  return newRemovalItem({
    state: 'DELETE',
    path: record.path,
    reason: 'removed as a link; its target is kept',
    action: 'remove-link',
    records: [record],
    gone: [record.path],
    full: entry.full,
    expectTarget: record.target as string,
  });
}

/** The state of a backup: missing, intact, or modified. */
export function getBackupState(backup: OwnedRecord): string {
  const entry = resolveWorkspaceEntry(backup.path);
  if (!entry.ok) return 'modified';
  if (getEntryItem(entry.full as string) === null) return 'missing';
  if (testRecordedFile(entry.full as string, backup.sha256 ?? null)) return 'intact';
  return 'modified';
}

/** Why a backup a removal does not restore is kept. */
export function getKeepCopyReason(backup: OwnedRecord): string {
  if (ordinalEqual(getBackupRole(backup), 'user')) {
    return 'kept: a backup the installer did not write, so it is never restored or deleted';
  }
  return 'kept: a copy of an earlier version, not restored';
}

/** The original backup of a file that the installer replaced. */
export function getOriginalBackup(backups: readonly OwnedRecord[]): OwnedRecord | null {
  return backups.find((backup) => ordinalEqual(getBackupRole(backup), 'original')) ?? null;
}

export function newKeepBackupItem(backup: OwnedRecord, reason: string): RemovalItem {
  return newRemovalItem({ state: 'KEEP', path: backup.path, reason, records: [backup] });
}

/** Puts the original backup back in place of the file it replaced. */
export function newRestoreItem(
  replaced: string,
  original: OwnedRecord,
  expectSha: string | null,
  records: OwnedRecord[],
): RemovalItem {
  const replacedEntry = resolveWorkspaceEntry(replaced);
  const originalEntry = resolveWorkspaceEntry(original.path);
  return newRemovalItem({
    state: 'RESTORE',
    path: replaced,
    reason: `put back from ${original.path}`,
    action: 'restore',
    records: [original, ...records],
    gone: [original.path],
    full: replacedEntry.full,
    source: originalEntry.full,
    expectSha,
    expectSource: original.sha256 ?? null,
  });
}

/** The opencode.jsonc group: the config the installer wrote, and its backups. */
export function getConfigGroupItems(
  file: OwnedRecord | null,
  backups: readonly OwnedRecord[],
  created: boolean,
): RemovalItem[] {
  const name = 'opencode.jsonc';
  const items: RemovalItem[] = [];
  let original = getOriginalBackup(backups);
  for (const copy of backups.filter((backup) => original === null || !ordinalEqual(backup.path, original.path))) {
    items.push(newKeepBackupItem(copy, getKeepCopyReason(copy)));
  }
  const legacy = original !== null && getField(original, 'role') === null;
  if (legacy && file !== null && ordinalEqual(original?.sha256, file.sha256)) {
    items.push(newKeepBackupItem(original as OwnedRecord, "kept: a copy of the installer's own text, not restored"));
    original = null;
  }
  if (original !== null) {
    const state = getBackupState(original);
    const replacedEntry = resolveWorkspaceEntry(name);
    if (ordinalEqual(state, 'missing')) {
      if (replacedEntry.ok && testRecordedFile(replacedEntry.full as string, original.sha256 ?? null)) {
        const restored = [original];
        if (file !== null) restored.push(file);
        items.push(
          newGoneItem(
            name,
            restored,
            `already restored: ${name} holds the bytes of its original backup, which an earlier run restored before it stopped`,
          ),
        );
        return items;
      }
      items.push(newGoneItem(original.path, [original], 'already gone: the original backup is missing'));
    } else if (ordinalEqual(state, 'modified')) {
      items.push(newKeepBackupItem(original, 'kept: the original backup changed by hand, so it is not restored'));
    } else if (file === null) {
      items.push(newKeepBackupItem(original, 'kept: the file it replaced is not in the record'));
      return items;
    } else if (replacedEntry.ok && testRecordedFile(replacedEntry.full as string, original.sha256 ?? null)) {
      items.push(
        newRemovalItem({
          state: 'RESTORE',
          path: name,
          reason: `already holds ${original.path}: its backup is removed`,
          action: 'drop-backup',
          records: [original, file],
          gone: [original.path],
          source: resolveWorkspaceEntry(original.path).full,
          expectSource: original.sha256 ?? null,
        }),
      );
      return items;
    } else if (
      replacedEntry.ok &&
      getEntryItem(replacedEntry.full as string) !== null &&
      testRecordedFile(replacedEntry.full as string, file.sha256 ?? null)
    ) {
      items.push(newRestoreItem(name, original, file.sha256 ?? null, [file]));
      return items;
    } else if (getEntryItem(replacedEntry.full as string) === null) {
      items.push(newKeepBackupItem(original, 'kept: the config is missing, so the original is kept'));
      items.push(newGoneItem(name, [file], 'already gone: opencode.jsonc is missing'));
      return items;
    } else if (legacy) {
      items.push(
        newRemovalItem({
          state: 'KEEP',
          path: name,
          reason: `kept: it changed since the install, so the original is not restored; the original is in ${original.path}`,
          records: [file],
        }),
      );
      items.push(newKeepBackupItem(original, 'kept: the config changed since the install, so this original is not restored'));
      return items;
    } else {
      items.push(newSkipItem(name, 'modified by hand: kept with its original backup, which is not restored'));
      items.push(newKeepBackupItem(original, 'kept: the config was modified by hand'));
      return items;
    }
  }
  if (file === null) return items;
  const fileRemoval = getFileRemovalItem(file);
  if (
    ordinalEqual(fileRemoval.state, 'DELETE') &&
    !created &&
    original === null &&
    backups.length === 0
  ) {
    items.push(
      newRemovalItem({
        state: 'KEEP',
        path: name,
        reason: 'it existed before the install and holds the text the installer wrote, so it is kept',
        records: [file],
      }),
    );
    return items;
  }
  items.push(fileRemoval);
  return items;
}

/** The Pi settings group: the original backup, and the installer entries. */
export function getSettingsGroupItems(
  records: readonly OwnedRecord[],
  backups: readonly OwnedRecord[],
  lastSha: string | null,
  created: boolean,
): RemovalItem[] {
  const name = '.pi/agent/settings.json';
  const items: RemovalItem[] = [];
  const original = getOriginalBackup(backups);
  for (const copy of backups.filter((backup) => original === null || !ordinalEqual(backup.path, original.path))) {
    items.push(newKeepBackupItem(copy, getKeepCopyReason(copy)));
  }
  let originalHandled = false;
  if (original !== null) {
    const state = getBackupState(original);
    const replacedEntry = resolveWorkspaceEntry(name);
    if (ordinalEqual(state, 'missing')) {
      items.push(newGoneItem(original.path, [original], 'already gone: the original backup is missing'));
      originalHandled = true;
    } else if (ordinalEqual(state, 'modified')) {
      items.push(newKeepBackupItem(original, 'kept: the original backup changed by hand, so it is not restored'));
      originalHandled = true;
    } else if (
      replacedEntry.ok &&
      getEntryItem(replacedEntry.full as string) !== null &&
      testRecordedFile(replacedEntry.full as string, lastSha)
    ) {
      items.push(newRestoreItem(name, original, lastSha, [...records]));
      return items;
    }
  }
  const edits = getSettingsEditItems(records, created && original === null);
  items.push(...edits);
  if (!originalHandled && original !== null) {
    if (edits.some((item) => ordinalEqual(item.state, 'SKIP'))) {
      items.push(newSkipItem(original.path, 'kept: the settings file could not be edited, so its original stays in place'));
    } else {
      items.push(newKeepBackupItem(original, 'kept: the original is not restored; only the installer entries were removed'));
    }
  }
  return items;
}

/** The Pi settings file, with the recorded entries taken out of their keys by a strict JSON parse. */
export function getSettingsEditItems(records: readonly OwnedRecord[], created: boolean): RemovalItem[] {
  const name = '.pi/agent/settings.json';
  const entry = resolveWorkspaceEntry(name);
  if (!entry.ok) {
    return records.map((record) => newSkipItem(name, `[${record.key}] ${entry.reason}`));
  }
  const item = getEntryItem(entry.full as string);
  if (item === null) {
    return records.map((record) => newGoneItem(name, [record], `[${record.key}] already gone: the settings file is missing`));
  }
  if (testReparsePoint(entry.full as string) || item.isDirectory()) {
    return records.map((record) =>
      newSkipItem(name, `[${record.key}] modified by hand: a link or folder stands where the file was recorded`),
    );
  }
  const text = readText(entry.full as string);
  let root: Record<string, unknown>;
  try {
    root = readStrictJsonObject(text);
  } catch {
    return records.map((record) =>
      newSkipItem(
        name,
        `[${record.key}] not strict JSON: it has comments, trailing commas, or is not an object, so it is left as it is`,
      ),
    );
  }
  const expectSha = sha256FileOrNull(entry.full as string);
  const result = getSettingsAfterRemoval(root, records, created);
  const list = [...records];
  if (created && testInstallerShape(result.root)) {
    return [
      newRemovalItem({
        state: 'DELETE',
        path: name,
        reason: 'the installer created it, and only its empty lists remain',
        action: 'remove-json-file',
        records: list,
        gone: [name],
        full: entry.full,
        expectSha,
      }),
    ];
  }
  if (result.removed === 0) {
    return [newGoneItem(name, list, 'already gone: none of the recorded entries is in the file')];
  }
  const countText = [...result.counts.entries()].map(([key, count]) => `${key} ${count}`).join(', ');
  const state = created ? 'KEEP' : 'DELETE';
  const reason = `removes the recorded entries (${countText}); every other key and entry stays`;
  return [
    newRemovalItem({
      state,
      path: name,
      reason,
      action: 'write-json',
      records: list,
      full: entry.full,
      text: `${jsonText(result.root)}\n`,
      expectSha,
    }),
  ];
}

/** Takes the recorded entries out of their keys, in place. */
export function getSettingsAfterRemoval(
  root: Record<string, unknown>,
  records: readonly OwnedRecord[],
  createdFile: boolean,
): { root: Record<string, unknown>; counts: Map<string, number>; removed: number } {
  const counts = new Map<string, number>();
  let removed = 0;
  for (const record of records) {
    let taken = 0;
    const list = root[String(record.key)];
    if (Array.isArray(list)) {
      for (const recorded of record.entries ?? []) {
        const entryKey = jsonEntryKeyFromValue(recorded);
        for (let index = 0; index < list.length; index++) {
          if (ordinalEqual(jsonEntryKey(list[index]), entryKey)) {
            list.splice(index, 1);
            taken++;
            break;
          }
        }
      }
      const createdKey = createdFile || isTrue(getField(record, 'createdKey'));
      if (taken > 0 && list.length === 0 && createdKey) delete root[String(record.key)];
    }
    counts.set(String(record.key), taken);
    removed += taken;
  }
  return { root, counts, removed };
}

/** Whether only the keys the installer writes remain, and each of them is an empty list. */
export function testInstallerShape(root: Record<string, unknown>): boolean {
  for (const [key, value] of Object.entries(root)) {
    if (!ordinalIn(key, ['packages', 'skills'])) return false;
    if (!Array.isArray(value) || value.length > 0) return false;
  }
  return true;
}

/** The folders the installer created, deepest first. */
export function getCreatedDirItems(
  dirs: readonly string[],
  gone: readonly string[],
  report: boolean,
): RemovalItem[] {
  const goneFull = new Set<string>();
  for (const path of gone) {
    const entry = resolveWorkspaceEntry(path);
    if (entry.ok) goneFull.add((entry.full as string).toLowerCase());
  }
  const items: RemovalItem[] = [];
  const ordered = [...dirs].sort((left, right) => {
    const depth = right.split('/').length - left.split('/').length;
    if (depth !== 0) return depth;
    return compareUtf8Bytes(right, left);
  });
  for (const dir of ordered) {
    const entry = resolveWorkspaceEntry(dir);
    if (!entry.ok) {
      items.push(newSkipItem(dir, entry.reason as string));
      continue;
    }
    if (goneFull.has((entry.full as string).toLowerCase())) continue;
    const item = getEntryItem(entry.full as string);
    if (item === null || !item.isDirectory()) continue;
    if (testReparsePoint(entry.full as string)) {
      if (report) items.push(newRemovalItem({ state: 'KEEP', path: dir, reason: 'a link, which is left alone' }));
      continue;
    }
    let left: string[];
    try {
      left = readdirSync(entry.full as string).filter(
        (name) => !goneFull.has(join(entry.full as string, name).toLowerCase()),
      );
    } catch {
      left = [];
    }
    if (left.length === 0) {
      items.push(
        newRemovalItem({
          state: 'DELETE',
          path: dir,
          reason: 'empty, and the installer created it',
          action: 'delete-empty',
          full: entry.full,
        }),
      );
      goneFull.add((entry.full as string).toLowerCase());
    } else if (report) {
      items.push(newRemovalItem({ state: 'KEEP', path: dir, reason: 'holds entries that stay' }));
    }
  }
  return items;
}

/** The SHA-256 values the lock or the apply knows for one file. */
export function getKnownShas(
  path: string,
  known: readonly (OwnedRecord | null)[],
  configSha: string | null,
  settingsSha: string | null,
): Set<string> {
  const shas = new Set<string>();
  const escaped = path.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = new RegExp(`^${escaped}\\.bak(\\.\\d+)?$`);
  for (const record of known) {
    if (record === null || !ordinalEqual(record.kind, 'file') || !record.sha256) continue;
    if (ordinalEqual(record.path, path) || pattern.test(record.path)) shas.add(record.sha256);
  }
  if (ordinalEqual(path, 'opencode.jsonc') && configSha) shas.add(configSha);
  if (ordinalEqual(path, '.pi/agent/settings.json') && settingsSha) shas.add(settingsSha);
  return shas;
}

/** The leftover copies beside each recorded file. */
export function getStrayItems(
  candidates: readonly OwnedRecord[],
  known: readonly (OwnedRecord | null)[],
  configSha: string | null,
  settingsSha: string | null,
): RemovalItem[] {
  const items: RemovalItem[] = [];
  const bases = sortUtf8(
    ordinalUnique(
      candidates
        .filter((record) => ordinalIn(record.kind, ['file', 'json-entries']))
        .map((record) => record.path),
    ),
  );
  for (const base of bases) {
    const baseEntry = resolveWorkspaceEntry(base);
    if (!baseEntry.ok) continue;
    const shas = getKnownShas(base, known, configSha, settingsSha);
    for (const suffix of STRAY_FILE_SUFFIXES) {
      const stray = `${base}${suffix}`;
      const strayEntry = resolveWorkspaceEntry(stray);
      if (!strayEntry.ok) continue;
      const strayItem = getEntryItem(strayEntry.full as string);
      if (strayItem === null) continue;
      if (strayItem.isDirectory() || testReparsePoint(strayEntry.full as string)) {
        items.push(newSkipItem(stray, 'a leftover folder or link beside a recorded file, so it is kept'));
        continue;
      }
      const sha = sha256FileOrNull(strayEntry.full as string);
      if (sha !== null && shas.has(sha)) {
        items.push(
          newRemovalItem({
            state: 'DELETE',
            path: stray,
            reason: `a leftover copy of ${base} from an interrupted run; its bytes match the lock`,
            action: 'remove-file',
            full: strayEntry.full,
            expectSha: sha,
          }),
        );
      } else {
        items.push(
          newSkipItem(stray, `a leftover copy of ${base} whose bytes the lock does not record, so it is kept`),
        );
      }
    }
  }
  return items;
}

/** Whether a path is one of the file groups or a backup of one. */
export function testGroupMember(path: string): boolean {
  for (const group of GROUP_FILE_NAMES) {
    const escaped = group.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (ordinalEqual(path, group) || new RegExp(`^${escaped}\\.bak(\\.\\d+)?$`).test(path)) return true;
  }
  return false;
}

/** The plan for the candidate records: each record, each file group, and each folder the installer created. */
export function getRemovalPlanItems(args: {
  candidates: readonly OwnedRecord[];
  createdDirs: readonly string[];
  createdFiles: readonly string[];
  settingsSha: string | null;
  report: boolean;
}): RemovalItem[] {
  const items: RemovalItem[] = [];
  for (const group of GROUP_FILE_NAMES) {
    const escaped = group.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const pattern = new RegExp(`^${escaped}\\.bak(\\.\\d+)?$`);
    const members = args.candidates.filter(
      (record) => ordinalEqual(record.path, group) || pattern.test(record.path),
    );
    if (members.length === 0) continue;
    const file =
      members.find((record) => ordinalEqual(record.path, group) && ordinalEqual(record.kind, 'file')) ??
      null;
    const backups = members.filter((record) => pattern.test(record.path));
    const created =
      ordinalIn(group, args.createdFiles) || (S.priorLegacy && backups.length === 0);
    let groupItems: RemovalItem[];
    try {
      if (ordinalEqual(group, 'opencode.jsonc')) {
        groupItems = getConfigGroupItems(file, backups, created);
      } else {
        const records = members.filter((record) => ordinalEqual(record.kind, 'json-entries'));
        groupItems = getSettingsGroupItems(records, backups, args.settingsSha, created);
      }
    } catch (error) {
      groupItems = [newSkipItem(group, `could not be checked: ${(error as Error).message}`)];
    }
    items.push(...groupItems);
  }
  for (const record of args.candidates) {
    if (testGroupMember(record.path)) continue;
    try {
      if (record.kind === 'file') items.push(getFileRemovalItem(record));
      else if (record.kind === 'dir') items.push(getDirRemovalItem(record));
      else if (record.kind === 'link') items.push(getLinkRemovalItem(record));
      else items.push(newSkipItem(record.path, 'the record names an entry kind this installer does not remove'));
    } catch (error) {
      items.push(newSkipItem(record.path, `could not be checked: ${(error as Error).message}`));
    }
  }
  items.push(
    ...getStrayItems(
      args.candidates,
      S.priorOwned ?? [],
      getField(S.priorStack, 'configSha256') as string | null,
      S.priorSettingsSha ?? null,
    ),
  );
  const gone = items
    .filter((item) => ordinalIn(item.state, ['DELETE', 'RESTORE']))
    .flatMap((item) => item.gone);
  items.push(...getCreatedDirItems(args.createdDirs, gone, args.report));
  return items;
}

/** An apply prints the leftover copies beside the recorded files, and deletes the ones whose bytes the lock knows. */
export function invokeStrayReport(
  known: readonly (OwnedRecord | null)[],
  configSha: string | null,
  settingsSha: string | null,
  keptJournals: Set<string>,
): void {
  for (const item of getStrayItems(
    known.filter((record): record is OwnedRecord => record !== null),
    known,
    configSha,
    settingsSha,
  )) {
    if (ordinalEqual(item.state, 'DELETE')) {
      try {
        confirmRemovalItem(item);
        invokeRemovalAction(item);
      } catch (error) {
        item.state = 'SKIP';
        item.reason = `could not be deleted: ${(error as Error).message}`;
      }
    }
    writeHost(`${item.state.padEnd(8)} ${item.path}  ${item.reason}`);
  }
  const dirRecords = new Map<string, OwnedRecord>();
  for (const record of known) {
    if (record === null || !ordinalEqual(record.kind, 'dir')) continue;
    if (!dirRecords.has(record.path)) dirRecords.set(record.path, record);
  }
  for (const record of sortUtf8([...dirRecords.keys()]).map((key) => dirRecords.get(key) as OwnedRecord)) {
    if (keptJournals.has(record.path)) continue;
    const entry = resolveWorkspaceEntry(record.path);
    if (!entry.ok) continue;
    const leftover = `${entry.full}${QUARANTINE_SUFFIX}`;
    if (pathExists(leftover)) {
      writeHost(
        `SKIP     ${record.path}${QUARANTINE_SUFFIX}  a folder with the removal quarantine name is beside a recorded folder, and no removal journal names it, so it is kept; delete or move it aside by hand`,
      );
    }
  }
}

/** The records a removal deletes. */
export function getRemovalCandidates(args: {
  records: readonly OwnedRecord[];
  keepRuntimes: readonly string[];
  keepLayers: readonly string[];
  produced: Set<string>;
  all: boolean;
}): OwnedRecord[] {
  const candidates: OwnedRecord[] = [];
  for (const record of args.records) {
    if (args.all) {
      candidates.push(record);
      continue;
    }
    if (args.produced.has(record.path)) continue;
    const consumers = getOwnedRuntimeClaims(record);
    const runtimeGone =
      consumers.length > 0 && consumers.filter((name) => ordinalIn(name, args.keepRuntimes)).length === 0;
    const layerGone = (record.layers ?? []).some((layer) => !ordinalIn(layer, args.keepLayers));
    if (runtimeGone || layerGone) candidates.push(record);
  }
  return candidates;
}

export function getPlannedPathSet(plan: readonly OwnedRecord[]): Set<string> {
  return new Set(plan.map((record) => record.path));
}

/** The runtimes or layers still selected after -Remove: the recorded ones less the named ones. */
export function getRemainingSelection(
  recorded: readonly string[],
  named: readonly string[],
  label: string,
): string[] {
  for (const name of named) {
    if (!ordinalIn(name, recorded)) {
      writeHost(`${label} '${name}' is not selected, so there is nothing to remove for it.`);
    }
  }
  return sortUtf8(recorded.filter((name) => !ordinalIn(name, named)));
}

/** A removal that empties the selection, or leaves a runtime that needs an unselected one, is refused. */
export function assertRemainingSelection(runtimes: readonly string[], layers: readonly string[]): void {
  if (runtimes.length === 0 || layers.length === 0) {
    throw new Error(
      'Removing every runtime, or every layer, leaves nothing selected. Use -Uninstall to remove the whole bundle.',
    );
  }
  const dependents = ['copilot', 'pi'].filter(
    (name) => ordinalIn(name, runtimes) && !ordinalIn('claude', runtimes),
  );
  if (dependents.length > 0) {
    const list = dependents.join(',');
    throw new Error(
      `Removing claude would leave ${dependents.join(' and ')} selected, and each needs claude. Remove them in the same command: -Remove -Runtimes claude,${list}.`,
    );
  }
}

/** Writes the lock with the records still owed. */
export function saveRemovalProgress(
  stack: StackDocument | null,
  keep: readonly (OwnedRecord | null)[],
  pending: readonly (OwnedRecord | null)[],
): void {
  if (stack === null) return;
  const pendingList = pending.filter((record): record is OwnedRecord => record !== null);
  const owed = [
    ...keep.filter((record): record is OwnedRecord => record !== null),
    ...pendingList,
  ];
  stack.owned = owed.length > 0 ? sortOwnedRecords(owed) : [];
  stack.createdDirs = selectPresentPaths(stack.createdDirs ?? [], 'Container');
  stack.createdFiles = selectPresentPaths(stack.createdFiles ?? [], 'Leaf');
  const settingsOwed = pendingList.some((record) =>
    record.path.startsWith('.pi/agent/settings.json'),
  );
  let settingsSha = S.priorSettingsSha ?? null;
  if (!settingsOwed) {
    settingsSha = null;
    if (ordinalIn('pi', S.selectedRuntimes) && isFile(S.piSettingsTarget)) {
      settingsSha = sha256FileOrNull(S.piSettingsTarget);
    }
  }
  const pi = stack.pi as Record<string, unknown> | null;
  if (pi !== null && pi !== undefined) pi.settingsSha256 = settingsSha;
  writeLockAtomically(`${JSON.stringify(stack, null, 2)}\n`);
}

/** A test seam: MAXSTACK_TEST_HOOK holds one fault. */
export function invokeRemovalTestHook(stage: string, path: string): void {
  const hook = process.env.MAXSTACK_TEST_HOOK;
  if (!hook) return;
  const parts = hook.split(':');
  if (parts.length !== 2 || !ordinalEqual(parts[1], path)) return;
  if (ordinalEqual(stage, 'before') && ordinalEqual(parts[0], 'swap')) {
    const full = resolveWorkspaceEntry(path).full;
    if (full !== null && isFile(full)) {
      unlinkSync(full);
      mkdirSync(full, { recursive: true });
    }
  }
  if (ordinalEqual(stage, 'after') && ordinalEqual(parts[0], 'crash')) {
    throw new Error(`injected fault after the action on ${path}, before the lock was written`);
  }
}

/** The SHA-256 a planned action was based on must still be the one the plan saw. */
export function confirmRemovalItem(item: RemovalItem): void {
  if (ordinalEqual(item.action, 'none')) return;
  const entry = resolveWorkspaceEntry(item.path);
  if (!entry.ok) throw new Error(entry.reason as string);
  const changed = 'changed since the plan: rerun the command to plan it again';
  if (item.action === 'remove-file') {
    if (!testRecordedFile(entry.full as string, item.expectSha)) throw new Error(changed);
  } else if (item.action === 'remove-json-file' || item.action === 'write-json') {
    if (!ordinalEqual(sha256FileOrNull(entry.full as string), item.expectSha)) throw new Error(changed);
  } else if (item.action === 'remove-link') {
    const target = resolveWorkspaceEntry(item.expectTarget as string);
    if (!target.ok || !testClaudeLink(entry.full as string, target.full as string)) {
      throw new Error(changed);
    }
  } else if (item.action === 'remove-dir') {
    const current = getEntryItem(entry.full as string);
    if (current === null || !current.isDirectory() || testReparsePoint(entry.full as string)) {
      throw new Error(changed);
    }
    if (!ordinalEqual(getTreeSha256(entry.full as string), item.expectSha ?? null)) throw new Error(changed);
  } else if (item.action === 'restore') {
    if (!testRecordedFile(entry.full as string, item.expectSha)) throw new Error(changed);
    if (!testRecordedFile(item.source as string, item.expectSource)) {
      throw new Error('the backup changed since the plan');
    }
  } else if (item.action === 'drop-backup') {
    if (!testRecordedFile(item.source as string, item.expectSource)) {
      throw new Error('the backup changed since the plan');
    }
  } else if (item.action === 'resume-quarantine') {
    if (!isDirectory(item.quarantine as string) || testReparsePoint(item.quarantine as string)) {
      throw new Error(changed);
    }
    if (!ordinalEqual(getTreeSha256(item.quarantine as string), item.expectSha ?? null)) {
      throw new Error(changed);
    }
  } else if (item.action === 'delete-empty') {
    const current = getEntryItem(entry.full as string);
    if (current === null || !current.isDirectory() || testReparsePoint(entry.full as string)) {
      throw new Error(changed);
    }
    if (readdirSync(entry.full as string).length > 0) throw new Error(changed);
  }
}

/** Renames the folder to its quarantine name, then deletes the quarantine. */
export function removeQuarantinedDir(item: RemovalItem): void {
  renameSync(item.full as string, item.quarantine as string);
  removeOwnedTree(item.quarantine as string);
}

/** Puts the original back in place of the file it replaced. */
export function restoreOriginal(item: RemovalItem): void {
  const temp = `${item.full}.uninstall-restore`;
  const replaced = `${item.full}.uninstall-replaced`;
  try {
    if (pathExists(replaced)) unlinkSync(replaced);
    copyFileSync(item.source as string, temp);
    renameSync(temp, item.full as string);
  } finally {
    for (const stray of [temp, replaced]) {
      if (isFile(stray)) unlinkSync(stray);
    }
  }
  unlinkSync(item.source as string);
}

export function invokeRemovalAction(item: RemovalItem): void {
  if (
    ordinalEqual(item.action, 'remove-file') ||
    ordinalEqual(item.action, 'remove-json-file') ||
    ordinalEqual(item.action, 'remove-link')
  ) {
    removeOwnedTree(item.full as string);
  } else if (ordinalEqual(item.action, 'remove-dir')) {
    removeQuarantinedDir(item);
  } else if (ordinalEqual(item.action, 'resume-quarantine')) {
    removeOwnedTree(item.quarantine as string);
  } else if (ordinalEqual(item.action, 'restore')) {
    restoreOriginal(item);
  } else if (ordinalEqual(item.action, 'drop-backup')) {
    unlinkSync(item.source as string);
  } else if (ordinalEqual(item.action, 'write-json')) {
    assertUnchangedSince(item.full as string, item.expectSha);
    writeFileAtomic(item.full as string, item.text as string);
  } else if (ordinalEqual(item.action, 'delete-empty')) {
    rmdirSync(item.full as string);
  }
}

/** The reason an action failed. */
export function getActionFailureReason(item: RemovalItem, error: Error): string {
  const message = error.message;
  if (ordinalIn(item.action, ['remove-dir', 'resume-quarantine'])) {
    if (item.quarantine && pathExists(item.quarantine)) {
      const leaf = item.quarantine.slice(item.quarantine.lastIndexOf('/') + 1);
      return `in use: part of it could not be deleted; it is quarantined as ${leaf}, and a rerun resumes it (${message})`;
    }
    return `in use: could not be renamed, so the folder is unchanged (${message})`;
  }
  return `could not be removed: ${message}`;
}

/** Prints each item's state, path, and reason, and with execute runs the items that act. */
export function invokeRemovalItems(args: {
  stack: StackDocument | null;
  keep: readonly (OwnedRecord | null)[];
  candidates: readonly OwnedRecord[];
  items: RemovalItem[];
  execute: boolean;
}): void {
  const finished = new Set<string>();
  for (const item of args.items) {
    const acts =
      !ordinalEqual(item.action, 'none') &&
      !ordinalEqual(item.state, 'SKIP') &&
      !ordinalEqual(item.state, 'GONE');
    if (args.execute && acts) {
      try {
        invokeRemovalTestHook('before', item.path);
        confirmRemovalItem(item);
        if (ordinalEqual(item.action, 'remove-dir') && args.stack !== null) {
          item.records[0].quarantine = (item.quarantine as string).slice(
            (item.quarantine as string).lastIndexOf('/') + 1,
          );
          saveRemovalProgress(
            args.stack,
            args.keep,
            getPendingRecords(args.candidates, finished),
          );
        }
        invokeRemovalAction(item);
      } catch (error) {
        item.state = 'SKIP';
        item.reason = getActionFailureReason(item, error as Error);
      }
    }
    writeHost(`${item.state.padEnd(8)} ${item.path}  ${item.reason}`);
    if (args.execute && !ordinalEqual(item.state, 'SKIP')) {
      if (acts) invokeRemovalTestHook('after', item.path);
      for (const record of item.records) finished.add(getOwnedKey(record));
      if (item.records.length > 0) {
        saveRemovalProgress(
          args.stack,
          args.keep,
          getPendingRecords(args.candidates, finished),
        );
      }
    }
  }
  if (args.execute) {
    saveRemovalProgress(args.stack, args.keep, getPendingRecords(args.candidates, finished));
  }
}

/** The candidates a run has not finished. */
export function getPendingRecords(
  candidates: readonly OwnedRecord[],
  finished: Set<string>,
): OwnedRecord[] {
  return candidates.filter((record) => !finished.has(getOwnedKey(record)));
}

export function writeRemovalSummary(items: readonly RemovalItem[]): void {
  const counts = ['DELETE', 'RESTORE', 'GONE', 'KEEP', 'SKIP'].map(
    (state) => `${items.filter((item) => ordinalEqual(item.state, state)).length} ${state.toLowerCase()}`,
  );
  writeHost(`Summary: ${counts.join(', ')}`);
}

export function getSkipCount(items: readonly RemovalItem[]): number {
  return items.filter((item) => ordinalEqual(item.state, 'SKIP')).length;
}

/** -Remove without -Apply: the plan for the removal. Writes nothing. */
export function writeRemovalDryRun(args: {
  records: readonly OwnedRecord[];
  plan: readonly OwnedRecord[];
  selectedRuntimes: readonly string[];
  selectedLayers: readonly string[];
}): void {
  const candidates = getRemovalCandidates({
    records: args.records,
    keepRuntimes: args.selectedRuntimes,
    keepLayers: args.selectedLayers,
    produced: getPlannedPathSet(args.plan),
    all: false,
  });
  const items = getRemovalPlanItems({
    candidates,
    createdDirs: S.priorCreatedDirs,
    createdFiles: S.priorCreatedFiles,
    settingsSha: S.priorSettingsSha ?? null,
    report: false,
  });
  writeHost('Removal plan:');
  invokeRemovalItems({ stack: null, keep: [], candidates, items, execute: false });
  writeRemovalSummary(items);
  writeHost('Dry run: nothing was removed or written. Rerun with -Apply to execute this plan.');
  if (S.strict && getSkipCount(items) > 0) process.exitCode = 1;
}

/** -Remove -Apply: after the remaining selection is applied, deletes what the selection no longer produces. */
export function invokeRemovalFlow(
  stack: StackDocument,
  planRecords: readonly OwnedRecord[],
  plan: readonly OwnedRecord[],
): void {
  const candidates = getRemovalCandidates({
    records: S.priorOwned ?? [],
    keepRuntimes: S.selectedRuntimes,
    keepLayers: S.selectedLayers,
    produced: getPlannedPathSet(plan),
    all: false,
  });
  const items = getRemovalPlanItems({
    candidates,
    createdDirs: S.priorCreatedDirs,
    createdFiles: S.priorCreatedFiles,
    settingsSha: S.priorSettingsSha ?? null,
    report: false,
  });
  writeHost('Removal:');
  invokeRemovalItems({ stack, keep: planRecords, candidates, items, execute: true });
  writeRemovalSummary(items);
  const skipped = getSkipCount(items);
  if (skipped > 0) {
    writeHost(`${skipped} items skipped; lock kept; rerun -Remove -Apply to retry.`);
  } else {
    writeHost(
      `Removed. Selection: runtimes ${S.selectedRuntimes.join(', ')}; layers ${S.selectedLayers.join(', ')}.`,
    );
  }
  if (S.strict && skipped > 0) process.exitCode = 1;
}

/** -Uninstall: removes every record, then the lock files when nothing was skipped. */
export function invokeUninstallFlow(): void {
  const candidates = getRemovalCandidates({
    records: S.priorOwned ?? [],
    keepRuntimes: [],
    keepLayers: [],
    produced: new Set(),
    all: true,
  });
  const items = getRemovalPlanItems({
    candidates,
    createdDirs: S.priorCreatedDirs,
    createdFiles: S.priorCreatedFiles,
    settingsSha: S.priorSettingsSha ?? null,
    report: true,
  });
  if (items.length === 0) writeHost('Nothing to remove: the lock records no path.');
  invokeRemovalItems({
    stack: S.priorStack,
    keep: [],
    candidates,
    items,
    execute: S.apply,
  });
  if (items.length > 0) writeRemovalSummary(items);
  const skipped = getSkipCount(items);
  if (!S.apply) {
    writeHost('Dry run: nothing was removed or written. Rerun with -Uninstall -Apply to execute this plan.');
  } else if (skipped === 0) {
    for (const file of [S.stackTarget, `${S.stackTarget}.bak`, `${S.stackTarget}.new`]) {
      if (isFile(file)) unlinkSync(file);
    }
    const kept = items.filter((item) => ordinalEqual(item.state, 'KEEP')).map((item) => item.path);
    if (kept.length === 0) {
      writeHost('Uninstalled: every recorded path was removed, and the lock files with it.');
    } else {
      writeHost(
        `Uninstalled: the lock files are removed. Kept on disk, not restored or deleted: ${kept.join(', ')}.`,
      );
    }
  } else {
    writeHost(`${skipped} items skipped; lock kept; rerun -Uninstall -Apply to retry.`);
  }
  if (S.strict && skipped > 0) process.exitCode = 1;
}

// ---- Apply helpers --------------------------------------------------------------------------------------

/** The directories an install may create, named relative to the workspace. */
export function getInstallerDirectories(
  layers: readonly LayerModel[],
  codex: boolean,
  cursor: boolean,
  copilotInstructions: boolean,
): string[] {
  const dirs = [
    '.claude', '.claude/plugins', '.claude/cache', '.opencode', '.opencode/plugins', '.opencode/agents',
    '.maxstack', '.maxstack/bin', '.pi', '.pi/agent', '.pstack',
  ];
  if (codex) dirs.push('.agents', '.agents/skills', '.codex');
  if (cursor) dirs.push('.cursor', '.cursor/skills');
  if (copilotInstructions) dirs.push('.maxstack/copilot-instructions');
  for (const layer of layers) {
    dirs.push(`.claude/plugins/${layer.name}`, `.claude/cache/${layer.name}`, `.opencode/plugins/${layer.name}`);
  }
  return dirs;
}

/** Whether the workspace holds any of the installer's outputs. */
export function testInstallerOutputs(): boolean {
  for (const path of [
    '.opencode/plugins', '.opencode/agents', '.claude/plugins', '.claude/cache', '.maxstack/bin',
    '.cursor/skills', '.pstack/pstack-t3-instances.json',
  ]) {
    if (pathExists(joinMaxstackPath(S.workspace, convertToMaxstackPath(path)))) return true;
  }
  return false;
}

/** Removes from a layer folder what the layer does not install now. */
export function removeFolderExtras(folder: string, items: readonly string[], top = false): void {
  let entries;
  try {
    entries = readdirSync(folder, { withFileTypes: true });
  } catch {
    return;
  }
  for (const child of entries) {
    const name = child.name;
    if (top && child.isDirectory() && ordinalEqual(name, 'node_modules')) continue;
    if (items.some((item) => ordinalEqual(item, name))) continue;
    const within = items
      .filter((item) => item.startsWith(`${name}/`))
      .map((item) => item.slice(name.length + 1));
    const full = join(folder, name);
    if (within.length > 0 && child.isDirectory() && !testReparsePoint(full)) {
      removeFolderExtras(full, within);
      continue;
    }
    removeOwnedTree(full);
    writeHost(`Removed ${full}: the layer does not install it`);
  }
}

/** The merged OpenCode config, or null when the opencode runtime is not selected. */
export function getConfigDocument(args: {
  layers: readonly LayerModel[];
  openCodeLayers: readonly LayerModel[];
  openCodeSpecs: Map<string, OpenCodeSpec>;
  workspaceInstructionPlan: WorkspaceInstructionPlan;
  baseConfigFile: string;
}): string | null {
  const base = JSON.parse(readText(args.baseConfigFile)) as Record<string, unknown>;
  const serverMaps: Array<Record<string, unknown>> = [];
  const extraPermissions: unknown[] = [];
  for (const layer of args.layers) {
    if (!ordinalEqual(layer.kind, 'config')) continue;
    const layerJson = readLayerJson(layer.root as string);
    const fragmentName = getField(layerJson, 'config');
    const fragmentPath = joinMaxstackPath(
      layer.root as string,
      convertToMaxstackPath(fragmentName ? String(fragmentName) : 'opencode.fragment.jsonc'),
    );
    if (!isFile(fragmentPath)) {
      throw new Error(`Layer '${layer.name}' has no config fragment: ${fragmentPath}`);
    }
    const fragment = JSON.parse(readText(fragmentPath)) as Record<string, unknown>;
    const mcp = getField(fragment, 'mcp');
    const servers = getField(mcp, 'servers');
    if (servers !== null && servers !== undefined && typeof servers === 'object') {
      serverMaps.push(servers as Record<string, unknown>);
    }
    const permissions = getField(fragment, 'permissions');
    if (permissions !== null && permissions !== undefined) extraPermissions.push(permissions);
  }
  const servers: Record<string, unknown> = {};
  for (const map of serverMaps) Object.assign(servers, map);
  const baseMcp = (getField(base, 'mcp') as Record<string, unknown> | null) ?? {};
  base.mcp = baseMcp;
  const baseServers = (getField(baseMcp, 'servers') as Record<string, unknown> | null) ?? {};
  baseMcp.servers = baseServers;
  Object.assign(baseServers, servers);
  const permissions = [
    ...((getField(base, 'permissions') as unknown[] | null) ?? []),
    ...extraPermissions,
  ];
  if (permissions.length > 0) {
    base.permissions = resolveMaxstackOpenCodePermissions(
      permissions as Array<{ action: string; resource: string; effect: string }>,
      S.workspace,
    );
  }
  const pluginEntries = args.openCodeLayers
    .map((layer) => getOpenCodePluginPath(layer, args.openCodeSpecs.get(layer.name) as OpenCodeSpec))
    .filter((entry): entry is string => entry !== null);
  if (pluginEntries.length > 0) base.plugin = pluginEntries;
  if (args.workspaceInstructionPlan.text) {
    base.instructions = [`./${args.workspaceInstructionPlan.files[0].path}`];
  }
  return JSON.stringify(base, null, 2);
}

function getConfigTargetDrift(document: string | null): string {
  if (document === null) return 'unknown';
  return getDriftState(S.configTarget, document);
}

// ---- Option validation and -UpdatePi --------------------------------------------------------------------

/**
 * Refuses the flag combinations the installer cannot mean. Runs after the discovery line, like the PowerShell
 * script, so a caller still learns which workspace the flags applied to.
 */
export function validateWorkspaceInstallerOptions(options: WorkspaceInstallerOptions): void {
  const namesRequested = options.runtimesNamed || options.layersNamed;
  const sourceNamed = options.sourceSpecs.length > 0 || options.layerSourceSpecs.length > 0;
  if (options.apply && options.status) {
    throw new Error('-Apply writes the workspace and -Status only reports it. Choose one.');
  }
  if (options.remove && options.uninstall) {
    throw new Error('-Remove names what to remove and -Uninstall removes everything. Choose one.');
  }
  if ((options.remove || options.uninstall) && options.status) {
    throw new Error('-Status only reports. Choose -Status, -Remove, or -Uninstall.');
  }
  if (
    options.strict &&
    !(options.apply || options.status || options.remove || options.uninstall || options.update)
  ) {
    throw new Error('-Strict applies to -Apply, -Status, -Remove, -Uninstall, and -Update.');
  }
  if (options.status && namesRequested) {
    throw new Error('-Status reports the recorded selection and takes no -Runtimes or -Layers. Select with an apply.');
  }
  if (options.uninstall && namesRequested) {
    throw new Error(
      '-Uninstall removes everything the lock records, so it takes no -Runtimes or -Layers. Use -Remove to name what to remove.',
    );
  }
  if (options.remove && !namesRequested) {
    throw new Error('-Remove names what to remove: give -Runtimes or -Layers. Use -Uninstall to remove everything.');
  }
  if (
    options.updatePi &&
    (options.update ||
      options.remove ||
      options.uninstall ||
      options.status ||
      options.initSettings ||
      namesRequested ||
      sourceNamed ||
      options.check ||
      options.strict ||
      options.layersFileSpecified ||
      options.piCommandSpecified ||
      options.copilotCommandSpecified)
  ) {
    throw new Error('-UpdatePi only accepts -Workspace, optional -PiVersion, and optional -Apply.');
  }
  if (options.piVersion && !options.updatePi) {
    throw new Error('-PiVersion applies only to -UpdatePi.');
  }
  if (options.updatePi) return;
  if ((options.status || options.remove || options.uninstall) && sourceNamed) {
    throw new Error(
      '-Source sets a layer source for an apply or an audit. -Status, -Remove, and -Uninstall read the recorded sources.',
    );
  }
  if (options.update && (options.remove || options.uninstall || options.status)) {
    throw new Error('-Update re-resolves the recorded sources. It is not -Remove, -Uninstall, or -Status.');
  }
  if (options.update && sourceNamed) {
    throw new Error('-Update re-resolves the recorded sources. Set a source with -Source and an apply, then -Update.');
  }
  if (options.update && namesRequested) {
    throw new Error('-Update applies the recorded selection. Change the selection with an apply.');
  }
  if (options.check && !options.update) {
    throw new Error('-Check applies to -Update.');
  }
  if (options.check && options.apply) {
    throw new Error('-Check writes nothing. Drop -Apply, or drop -Check to apply the update.');
  }
  if (options.strict && options.update && options.apply) {
    throw new Error('-Strict with -Update reports and writes nothing. Drop -Apply or -Strict.');
  }
  const initConflicts =
    options.status ||
    options.remove ||
    options.uninstall ||
    options.update ||
    options.check ||
    options.strict ||
    namesRequested ||
    sourceNamed;
  if (options.initSettings && initConflicts) {
    throw new Error(
      '-InitSettings takes no selection, source, status, update, remove, uninstall, check, or strict options.',
    );
  }
}

/** -UpdatePi: refreshes only the workspace-local Pi package under .maxstack/npm. A dry run unless -Apply. */
export function invokeUpdatePi(options: WorkspaceInstallerOptions): number {
  const piPrefix = joinMaxstackPath(S.workspace, '.maxstack/npm');
  const piManifest = joinMaxstackPath(
    piPrefix,
    'node_modules/@earendil-works/pi-coding-agent/package.json',
  );
  if (!isDirectory(piPrefix) || !isFile(piManifest)) {
    throw new Error(
      'No workspace Pi package was found under .maxstack/npm. Install it with npm install --prefix <workspace>/.maxstack/npm --ignore-scripts --no-audit --no-fund @earendil-works/pi-coding-agent',
    );
  }
  const readPackage = (): Record<string, unknown> => {
    const value = JSON.parse(readText(piManifest)) as unknown;
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new Error('The package under .maxstack/npm is not @earendil-works/pi-coding-agent.');
    }
    return value as Record<string, unknown>;
  };
  const before = readPackage();
  if (!ordinalEqual(getField(before, 'name'), '@earendil-works/pi-coding-agent')) {
    throw new Error('The package under .maxstack/npm is not @earendil-works/pi-coding-agent.');
  }
  writeHost(`Pi version before: ${String(getField(before, 'version'))}`);
  const packageSpec = `@earendil-works/pi-coding-agent@${options.piVersion ? options.piVersion : 'latest'}`;
  const safetyArgs = getPiNpmSafetyArgs();
  writeHost(`Would run: npm install --prefix ${piPrefix} ${safetyArgs.join(' ')} ${packageSpec}`);
  if (!S.apply) {
    writeHost(
      'Audit only. No files or workspace configuration changed. Rerun with -UpdatePi -Apply after reviewing.',
    );
    return 0;
  }
  const run = spawnSync('npm', ['install', '--prefix', piPrefix, ...safetyArgs, packageSpec], {
    stdio: 'inherit',
    windowsHide: true,
  });
  if (run.error || run.status !== 0) throw new Error(`npm install failed in ${piPrefix}`);
  writeHost(`Pi version after: ${String(getField(readPackage(), 'version'))}`);
  return 0;
}

// ---- Main flow ------------------------------------------------------------------------------------------

export interface WorkspaceInstallerOptions {
  workspace: string;
  workspaceSpecified: boolean;
  currentDirectory: string;
  scriptRoot: string;
  repoRoot: string;
  layersFile: string | null;
  layersFileSpecified: boolean;
  t3Settings: string | null;
  t3SettingsSpecified: boolean;
  sourceSpecs: string[];
  layerSourceSpecs: string[];
  copilotCommand: string;
  copilotCommandSpecified: boolean;
  piCommand: string;
  piCommandSpecified: boolean;
  requestedRuntimes: string[];
  requestedLayers: string[];
  runtimesNamed: boolean;
  layersNamed: boolean;
  initSettings: boolean;
  apply: boolean;
  status: boolean;
  remove: boolean;
  uninstall: boolean;
  update: boolean;
  updatePi: boolean;
  piVersion: string;
  check: boolean;
  strict: boolean;
}

/** Runs the workspace installer once and returns its exit code. */
export function runWorkspaceInstaller(options: WorkspaceInstallerOptions): number {
  S.workspace = '';
  S.repoRoot = options.repoRoot;
  S.platform = undefined;
  S.apply = options.apply;
  S.removing = options.remove;
  S.uninstalling = options.uninstall;
  S.updating = options.update;
  S.status = options.status;
  S.strict = options.strict;
  S.check = options.check;
  S.initSettings = options.initSettings;
  S.requestedRuntimes = options.requestedRuntimes;
  S.requestedLayers = options.requestedLayers;
  S.sourceSpecs = options.sourceSpecs;
  S.layerSourceSpecs = options.layerSourceSpecs;
  S.t3Settings = options.t3Settings;
  S.copilotCommand = options.copilotCommand;
  S.piCommand = options.piCommand;
  S.piVersion = options.piVersion;
  S.layersFile = options.layersFile;
  S.priorStack = null;
  S.priorOwned = null;
  S.priorLayers = new Map();
  S.priorCreatedDirs = [];
  S.priorCreatedFiles = [];
  S.priorLegacy = false;
  S.priorSettingsSha = null;
  S.selectedRuntimes = [];
  S.selectedLayers = [];

  const resolution = resolveMaxstackWorkspace({
    explicitSpecified: options.workspaceSpecified,
    explicitValue: options.workspace,
    currentDirectory: options.currentDirectory,
    scriptRoot: options.scriptRoot,
  });
  S.workspace = resolution.workspace;
  writeHost(`Workspace: ${safeName(resolution.workspace)} (from ${resolution.origin})`);
  if (resolution.note) writeWarning(resolution.note);
  validateWorkspaceInstallerOptions(options);
  if (options.updatePi) return invokeUpdatePi(options);

  const layersPath = options.layersFile
    ? options.layersFile
    : joinMaxstackPath(options.repoRoot, 'layers.json');
  const workspaceSettingsPath = joinMaxstackPath(S.workspace, 'maxstack.settings.json');
  const baseConfigFile = joinMaxstackPath(options.repoRoot, 'workspace/opencode.jsonc');
  S.configTarget = joinMaxstackPath(S.workspace, 'opencode.jsonc');
  S.stackTarget = joinMaxstackPath(S.workspace, 'stack.lock.json');
  S.agentsTarget = joinMaxstackPath(S.workspace, '.opencode/agents');
  S.opencodePluginsTarget = joinMaxstackPath(S.workspace, '.opencode/plugins');
  S.claudePluginsTarget = joinMaxstackPath(S.workspace, '.claude/plugins');
  S.claudeCacheTarget = joinMaxstackPath(S.workspace, '.claude/cache');
  S.copilotBinTarget = joinMaxstackPath(S.workspace, '.maxstack/bin');
  S.piAgentDir = joinMaxstackPath(S.workspace, '.pi/agent');
  S.piSettingsTarget = joinMaxstackPath(S.piAgentDir, 'settings.json');
  S.piLocalBinTarget = joinMaxstackPath(S.workspace, '.maxstack/npm/node_modules/.bin');
  const copilotCmdTarget = joinMaxstackPath(S.copilotBinTarget, 'copilot.cmd');
  const copilotShTarget = joinMaxstackPath(S.copilotBinTarget, 'copilot.sh');
  const piCmdTarget = joinMaxstackPath(S.copilotBinTarget, 'pi.cmd');
  const piShTarget = joinMaxstackPath(S.copilotBinTarget, 'pi.sh');
  const copilotWrapperPaths = IS_WINDOWS
    ? ['.maxstack/bin/copilot.cmd', '.maxstack/bin/copilot.sh']
    : ['.maxstack/bin/copilot.sh'];
  const piWrapperPaths = IS_WINDOWS
    ? ['.maxstack/bin/pi.cmd', '.maxstack/bin/pi.sh']
    : ['.maxstack/bin/pi.sh'];
  const copilotWrapperDisplay = IS_WINDOWS ? `${copilotCmdTarget} and ${copilotShTarget}` : copilotShTarget;
  const piWrapperDisplay = IS_WINDOWS ? `${piCmdTarget} and ${piShTarget}` : piShTarget;

  if ((S.removing || S.uninstalling) && isMaxstackLinkedPath(S.stackTarget)) {
    throw new Error(
      'stack.lock.json is a symbolic link or junction, so -Remove and -Uninstall refuse to act through it. Replace it with a regular file first.',
    );
  }

  if (S.initSettings) {
    const initManifest = JSON.parse(readText(layersPath)) as Record<string, unknown>;
    const initLayerNames = ((getField(initManifest, 'layers') as unknown[]) ?? []).map((layer) =>
      String(getField(layer, 'name')),
    );
    return invokeInitSettings(workspaceSettingsPath, S.workspace, initLayerNames, S.apply);
  }

  const layerManifest = JSON.parse(readText(layersPath)) as Record<string, unknown>;
  const allLayers = ((getField(layerManifest, 'layers') as unknown[]) ?? []).map((layer) =>
    newLayerModel(layer as Record<string, unknown>),
  );
  const layerNames = allLayers.map((layer) => layer.name);
  if (ordinalUnique(layerNames).length !== layerNames.length) {
    throw new Error('layers.json names a layer twice.');
  }

  let workspaceSettings: SettingsDocument = { present: false, value: null, hash: null };
  let settingsInvalid = false;
  let settingsChanged = false;
  if (S.removing && !S.apply) {
    workspaceSettings = readSettingsForRemoval(workspaceSettingsPath, layerNames);
  } else if (!(S.removing || S.uninstalling)) {
    try {
      workspaceSettings = readMaxstackSettings(workspaceSettingsPath, layerNames);
    } catch (error) {
      if (!S.status) throw error;
      settingsInvalid = true;
      writeHost(`Settings: invalid ${(error as Error).message}`);
    }
  }
  if (
    S.apply &&
    workspaceSettings.present &&
    workspaceSettings.value !== null &&
    hasField(workspaceSettings.value, 'os') &&
    !ordinalEqual(getField(workspaceSettings.value, 'os'), 'auto')
  ) {
    const machineOs = process.platform === 'win32' ? 'windows' : process.platform === 'darwin' ? 'macos' : 'linux';
    if (!ordinalEqual(getField(workspaceSettings.value, 'os'), machineOs)) {
      throw new Error(
        `maxstack.settings.json: os targets a different machine. This apply writes for the detected OS '${machineOs}'; use auto.`,
      );
    }
  }

  const explicitSources = readSourceSpecs(options.sourceSpecs, options.layerSourceSpecs, layerNames);

  const priorStack: StackDocument | null = pathExists(S.stackTarget) && isFile(S.stackTarget) ? readPriorLock() : null;
  const priorLayers = new Map<string, Record<string, unknown>>();
  const recordedOverrides = new Map<string, SourceChoice>();
  const recordedInvalid = new Map<string, { field: string; reason: string }>();
  let priorPi: Record<string, unknown> | null = null;
  let priorCopilot: Record<string, unknown> | null = null;
  let priorOwned: OwnedRecord[] | null = null;
  let priorCreatedDirs: string[] = [];
  let priorCreatedFiles: string[] = [];
  let priorLegacy = false;
  if (priorStack !== null) {
    const priorSchema = getField(priorStack, 'ownedSchema');
    priorLegacy = priorSchema !== OWNED_SCHEMA_VERSION;
    for (const priorLayer of (priorStack.layers as Array<Record<string, unknown>> | undefined) ?? []) {
      priorLayers.set(String(priorLayer.name), priorLayer);
    }
    const recorded = getRecordedOverrides(priorStack);
    for (const [name, choice] of recorded.overrides) recordedOverrides.set(name, choice);
    for (const [name, fault] of recorded.invalid) recordedInvalid.set(name, fault);
    priorPi = (getField(priorStack, 'pi') as Record<string, unknown> | null) ?? null;
    priorCopilot = (getField(priorStack, 'copilot') as Record<string, unknown> | null) ?? null;
    if (hasField(priorStack, 'owned')) {
      priorOwned = ((getField(priorStack, 'owned') as unknown[]) ?? []).filter(
        (record): record is OwnedRecord => record !== null && record !== undefined,
      );
    }
    if (hasField(priorStack, 'createdDirs')) priorCreatedDirs = (getField(priorStack, 'createdDirs') as string[]) ?? [];
    if (hasField(priorStack, 'createdFiles')) priorCreatedFiles = (getField(priorStack, 'createdFiles') as string[]) ?? [];
    if (
      priorLegacy &&
      (priorOwned ?? []).some(
        (record) => ordinalEqual(record.path, 'opencode.jsonc') && ordinalEqual(record.kind, 'file'),
      ) &&
      !isFile(joinMaxstackPath(S.workspace, 'opencode.jsonc.bak'))
    ) {
      priorCreatedFiles = [...priorCreatedFiles, 'opencode.jsonc'];
    }
  }
  S.priorStack = priorStack;
  S.priorOwned = priorOwned;
  S.priorLayers = priorLayers;
  S.priorCreatedDirs = priorCreatedDirs;
  S.priorCreatedFiles = priorCreatedFiles;
  S.priorLegacy = priorLegacy;
  S.priorSettingsSha = (getField(priorPi, 'settingsSha256') as string | null) ?? null;

  const declaredSources = new Map<string, SettingsChoice>();
  if (
    workspaceSettings.present &&
    workspaceSettings.value !== null &&
    hasField(workspaceSettings.value, 'layers')
  ) {
    for (const name of getSettingsNames(workspaceSettings, 'layers')) {
      const layerBlock = getField(getField(workspaceSettings.value, 'layers'), name);
      if (!hasField(layerBlock, 'source')) continue;
      declaredSources.set(
        name,
        getSettingsLayerSource(
          name,
          String(getField(layerBlock, 'source')),
          S.workspace,
          options.repoRoot,
        ),
      );
    }
  }
  const takesDeclared = S.apply;
  const sourceChoices = new Map<string, SettingsChoice>();
  for (const [name, choice] of declaredSources) {
    if (takesDeclared || ordinalEqual(choice.kind, 'unavailable')) sourceChoices.set(name, choice);
  }
  for (const [name, choice] of explicitSources) sourceChoices.set(name, choice as SettingsChoice);
  const settingsChoiceNames = [...sourceChoices.keys()].filter((name) => !explicitSources.has(name));
  if (!(S.removing || S.uninstalling)) {
    if (workspaceSettings.present) {
      writeHost(
        'Settings: maxstack.settings.json is present; omitted names in declared dimensions are unlisted and remain selected.',
      );
      const priorSettings = getField(priorStack, 'settings');
      if (
        priorSettings !== null &&
        priorSettings !== undefined &&
        !ordinalEqual(getField(priorSettings, 'sha256'), workspaceSettings.hash)
      ) {
        settingsChanged = true;
        writeHost('Settings: changed since the last apply.');
      }
      for (const runtime of SETTINGS_RUNTIME_IDS) {
        const runtimeBlock = getField(getField(workspaceSettings.value, 'runtimes'), runtime);
        if (
          workspaceSettings.value !== null &&
          hasField(workspaceSettings.value, 'runtimes') &&
          hasField(getField(workspaceSettings.value, 'runtimes'), runtime) &&
          hasField(runtimeBlock, 'cli') &&
          ordinalEqual(getField(runtimeBlock, 'cli'), 'install')
        ) {
          writeHost(`Settings: runtimes.${runtime}.cli install is recorded; CLI installation is unsupported in this release.`);
        }
      }
      const t3 = getField(workspaceSettings.value, 't3');
      if (hasField(t3, 'cli') && ordinalEqual(getField(t3, 'cli'), 'install')) {
        writeHost('Settings: t3.cli install is recorded; CLI installation is unsupported in this release.');
      }
      writeSettingsSourceNotes(workspaceSettings, declaredSources, recordedOverrides, !S.apply);
    } else if (!settingsInvalid) {
      const priorSettings = getField(priorStack, 'settings');
      if (priorSettings !== null && priorSettings !== undefined) {
        settingsChanged = true;
        writeHost('Settings: missing since the last apply.');
      }
    }
  }

  let priorOpenCodeSha: string | null = null;
  if (priorOwned !== null) {
    const priorConfigRecord = priorOwned.find(
      (record) => ordinalEqual(record.path, 'opencode.jsonc') && ordinalEqual(record.kind, 'file'),
    );
    if (priorConfigRecord) priorOpenCodeSha = priorConfigRecord.sha256 ?? null;
  }

  if (S.removing || S.uninstalling) {
    const hasOwned = priorStack !== null && priorOwned !== null;
    const priorSchema = getField(priorStack, 'ownedSchema');
    const schemaOk = priorStack !== null && priorSchema === OWNED_SCHEMA_VERSION;
    const usable = hasOwned && (S.uninstalling || schemaOk);
    if (!usable && priorStack !== null) {
      const why =
        priorOwned === null
          ? 'it has no owned list'
          : `its ownedSchema is ${String(getField(priorStack, 'ownedSchema'))}, and -Remove needs version ${OWNED_SCHEMA_VERSION}, which names each record's runtime and layers`;
      throw new Error(
        `stack.lock.json has no usable ownership record: ${why}. Run Install-Workspace.ps1 -Apply once to write it, then rerun.`,
      );
    }
    if (!usable) {
      if (testInstallerOutputs()) {
        throw new Error(
          `There is no usable ownership record (no ${S.stackTarget}). Run Install-Workspace.ps1 -Apply once to create it, then rerun.`,
        );
      }
      writeHost(`Nothing to remove: ${S.workspace} has no stack.lock.json and none of the installer's outputs.`);
      return 0;
    }
  }
  if (S.updating) {
    if (priorStack === null) {
      throw new Error(
        `-Update needs a stack.lock.json with a selection, and ${S.workspace} has none. Run Install-Workspace.ps1 -Apply first.`,
      );
    }
    if (getField(priorStack, 'selection') === null) {
      throw new Error(
        'stack.lock.json predates the selection, so -Update cannot tell which layers and runtimes to update. Run Install-Workspace.ps1 -Apply once, then -Update.',
      );
    }
  }
  if (S.uninstalling) {
    writeInvalidRecordedSources(recordedInvalid, [...explicitSources.keys()]);
    if (!S.apply) {
      writeHost('Settings: -Uninstall does not read maxstack.settings.json; it removes what the lock recorded.');
    }
    invokeUninstallFlow();
    return currentExitCode();
  }

  const recordedSelection = readRecordedSelection(priorStack, layerNames);
  const recordedRuntimes = recordedSelection ? recordedSelection.runtimes : null;
  const recordedLayers = recordedSelection ? recordedSelection.layers : null;
  const namedRuntimes = options.runtimesNamed
    ? getNamedValues(options.requestedRuntimes, RUNTIME_NAMES, 'Runtimes')
    : [];
  const namedLayers = options.layersNamed
    ? getNamedValues(options.requestedLayers, layerNames, 'Layers')
    : [];
  let settingsRuntimes: string[] = [];
  let settingsLayers: string[] = [];
  if (!(S.updating || S.status)) {
    settingsRuntimes = getSettingsNames(workspaceSettings, 'runtimes');
    settingsLayers = getSettingsNames(workspaceSettings, 'layers');
  }
  const pendingRuntimes = getSettingsNames(workspaceSettings, 'runtimes').filter(
    (name) => recordedRuntimes === null || !ordinalIn(name, recordedRuntimes),
  );
  const pendingLayers = getSettingsNames(workspaceSettings, 'layers').filter(
    (name) => recordedLayers === null || !ordinalIn(name, recordedLayers),
  );
  const unlistedRuntimes =
    workspaceSettings.present &&
    workspaceSettings.value !== null &&
    hasField(workspaceSettings.value, 'runtimes')
      ? (recordedRuntimes ?? []).filter(
          (name) => !ordinalIn(name, getSettingsNames(workspaceSettings, 'runtimes')),
        )
      : [];
  const unlistedLayers =
    workspaceSettings.present &&
    workspaceSettings.value !== null &&
    hasField(workspaceSettings.value, 'layers')
      ? (recordedLayers ?? []).filter(
          (name) => !ordinalIn(name, getSettingsNames(workspaceSettings, 'layers')),
        )
      : [];

  let selectedRuntimes: string[] = [];
  let selectedLayers: string[] = [];
  if (S.removing) {
    const removesSomething =
      namedRuntimes.filter((name) => ordinalIn(name, recordedRuntimes ?? [])).length +
        namedLayers.filter((name) => ordinalIn(name, recordedLayers ?? [])).length >
      0;
    const leftovers = getRemovalCandidates({
      records: priorOwned ?? [],
      keepRuntimes: recordedRuntimes ?? [],
      keepLayers: recordedLayers ?? [],
      produced: new Set(),
      all: false,
    });
    if (!removesSomething && leftovers.length === 0) {
      for (const name of namedRuntimes) writeHost(`runtime '${name}' is not selected, so there is nothing to remove for it.`);
      for (const name of namedLayers) writeHost(`layer '${name}' is not selected, so there is nothing to remove for it.`);
      writeHost('Nothing to remove.');
      return 0;
    }
    selectedRuntimes = getRemainingSelection(recordedRuntimes ?? [], namedRuntimes, 'runtime');
    selectedLayers = getRemainingSelection(recordedLayers ?? [], namedLayers, 'layer');
    assertRemainingSelection(selectedRuntimes, selectedLayers);
    const removedRuntimes = (recordedRuntimes ?? []).filter((name) => !ordinalIn(name, selectedRuntimes));
    const removedLayers = (recordedLayers ?? []).filter((name) => !ordinalIn(name, selectedLayers));
    writeRemovalSettingsNotes(
      readSettingsForRemoval(workspaceSettingsPath, layerNames),
      removedRuntimes,
      removedLayers,
    );
  } else {
    const allNamedRuntimes = [...settingsRuntimes, ...namedRuntimes];
    const allNamedLayers = [...settingsLayers, ...namedLayers];
    const hasRuntimeNames = options.runtimesNamed || settingsRuntimes.length > 0;
    const hasLayerNames = options.layersNamed || settingsLayers.length > 0;
    selectedRuntimes = mergeSelected(recordedRuntimes, DEFAULT_RUNTIME_NAMES, allNamedRuntimes, hasRuntimeNames, 'runtimes');
    selectedLayers = mergeSelected(recordedLayers, layerNames, allNamedLayers, hasLayerNames, 'layers');
    assertSelectionRuntimes(selectedRuntimes, settingsRuntimes);
  }
  S.selectedRuntimes = selectedRuntimes;
  S.selectedLayers = selectedLayers;

  const t3SnapshotEnabled = !(
    workspaceSettings.present &&
    workspaceSettings.value !== null &&
    hasField(workspaceSettings.value, 't3') &&
    hasField(getField(workspaceSettings.value, 't3'), 'snapshot') &&
    !isTrue(getField(getField(workspaceSettings.value, 't3'), 'snapshot'))
  );
  const t3SourceSpecified =
    options.t3SettingsSpecified || Boolean(process.env.MAXSTACK_T3_SETTINGS);
  let t3SourcePath = options.t3SettingsSpecified
    ? options.t3Settings
    : (process.env.MAXSTACK_T3_SETTINGS ?? null);
  let t3Report: T3Report | null = null;
  if (!(S.removing || S.uninstalling) && t3SnapshotEnabled && t3SourceSpecified) {
    if (!t3SourcePath || !t3SourcePath.trim()) throw new Error('-T3Settings needs a file path.');
    t3SourcePath = resolve(t3SourcePath);
    t3Report = getT3SettingsReport({
      path: t3SourcePath,
      workspace: S.workspace,
      runtimeNames: selectedRuntimes,
      layerNames,
    });
    writeT3SettingsReport(t3Report, S.workspace, true);
    if (S.apply && ordinalEqual(t3Report.sourceState, 'present')) {
      assertT3SnapshotDestination(S.workspace);
    }
  }
  if (!(S.removing || S.uninstalling)) {
    const claudeAvailable = ordinalIn('claude', [...(recordedRuntimes ?? []), ...getSettingsNames(workspaceSettings, 'runtimes')]);
    writePendingSettingsNotes(pendingRuntimes, pendingLayers, claudeAvailable, S.apply, S.updating);
    for (const name of unlistedRuntimes) {
      writeHost(`Settings: unlisted runtime '${name}'; it remains selected. Remove it with -Remove -Runtimes ${name}.`);
    }
    for (const name of unlistedLayers) {
      writeHost(`Settings: unlisted layer '${name}'; it remains selected. Remove it with -Remove -Layers ${name}.`);
    }
    if (workspaceSettings.present && workspaceSettings.value !== null && hasField(workspaceSettings.value, 'runtimes')) {
      const listed = getSettingsNames(workspaceSettings, 'runtimes');
      for (const name of namedRuntimes.filter((entry) => !ordinalIn(entry, listed))) {
        writeHost(`Settings: runtime '${name}' is selected by a flag and is not in maxstack.settings.json; add it there to keep it declared.`);
      }
    }
    if (workspaceSettings.present && workspaceSettings.value !== null && hasField(workspaceSettings.value, 'layers')) {
      const listed = getSettingsNames(workspaceSettings, 'layers');
      for (const name of namedLayers.filter((entry) => !ordinalIn(entry, listed))) {
        writeHost(`Settings: layer '${name}' is selected by a flag and is not in maxstack.settings.json; add it there to keep it declared.`);
      }
    }
  }
  const unselectedNotes = getUnselectedNotes(allLayers, selectedLayers, selectedRuntimes);
  if (!S.removing) {
    for (const note of unselectedNotes) {
      writeWarning(
        `${note.kind} '${note.name}' is in layers.json but not selected, so this run does not install it. Add it with ${note.flag} ${note.name}.`,
      );
    }
  }
  const copilotSelected = ordinalIn('copilot', selectedRuntimes);
  const codexSelected = ordinalIn('codex', selectedRuntimes);
  const antigravitySelected = ordinalIn('antigravity', selectedRuntimes);
  const cursorSelected = ordinalIn('cursor', selectedRuntimes);
  const piSelected = ordinalIn('pi', selectedRuntimes);
  const openCodeSelected = ordinalIn('opencode', selectedRuntimes);
  const claudeSelected = ordinalIn('claude', selectedRuntimes);

  for (const layer of allLayers) {
    const active: Record<string, unknown> = {};
    if (ordinalIn(layer.name, selectedLayers)) {
      for (const runtime of selectedRuntimes) {
        if (Object.hasOwn(layer.declared, runtime)) active[runtime] = layer.declared[runtime];
        else if (ordinalEqual(runtime, 'codex')) active[runtime] = {};
        else if (ordinalEqual(runtime, 'cursor')) active[runtime] = {};
      }
      if (antigravitySelected) {
        active.codex = {};
        active.antigravity = {};
      }
      if (Object.keys(active).length === 0) {
        writeHost(`Layer '${layer.name}' declares none of the selected runtimes, so it installs nothing.`);
      }
    }
    layer.runtimes = active;
  }

  if (S.apply) {
    for (const name of ordinalSorted([...recordedInvalid.keys()])) {
      if (sourceChoices.has(name) || !ordinalIn(name, selectedLayers)) continue;
      throw new Error(
        `${formatRecordedFault(name, recordedInvalid.get(name) as { field: string; reason: string })} Repair it with: bun scripts/install/main.ts -Source ${name}=default -Apply`,
      );
    }
  }
  writeInvalidRecordedSources(recordedInvalid, [...sourceChoices.keys()]);
  setLayerSources({
    layers: allLayers,
    explicit: sourceChoices as Map<string, SourceChoice>,
    recorded: recordedOverrides,
    updating: S.updating,
    selectedLayers,
    fromSettings: settingsChoiceNames,
  });
  writeSettingsSourceProblems(
    allLayers,
    S.uninstalling ? (recordedLayers ?? []) : selectedLayers,
    S.apply,
  );
  const layers = allLayers.filter((layer) => Object.keys(layer.runtimes).length > 0);
  const unselectedLayerNames = layerNames.filter((name) => !ordinalIn(name, selectedLayers));

  for (const layer of layers) {
    if (!ordinalEqual(layer.sourceKind, 'local') || !(layer.folderMissing || layer.unreadable)) continue;
    if (!S.apply) continue;
    const repair =
      !S.removing && layer.override ? ` or drop the override with -Source ${layer.name}=default -Apply` : '';
    if (layer.folderMissing) {
      if (S.removing || S.uninstalling) {
        throw new Error(`Layer '${layer.name}' has no folder at ${layer.repoRoot}. Restore the folder, then rerun.`);
      }
      const repository = layer.recordUrl ? `Clone ${layer.recordUrl} to ${layer.repoRoot}, ` : '';
      throw new Error(
        `Layer '${layer.name}' has no folder at ${layer.repoRoot}. ${repository}or pass -Source ${layer.name}=local:<path>, or set layers.${layer.name}.source in maxstack.settings.json to local:<path>${repair}.`,
      );
    }
    throw new Error(
      `Layer '${layer.name}' cannot be read at ${layer.repoRoot}: ${layer.unreadable}${unreadableRemedy(layer.unreadable as string)}${repair}, then rerun.`,
    );
  }

  const installerDirs = getInstallerDirectories(
    layers,
    codexSelected || antigravitySelected,
    cursorSelected,
    copilotSelected,
  );
  if (S.apply && t3Report !== null && ordinalEqual(t3Report.sourceState, 'present')) {
    installerDirs.push('.maxstack', '.maxstack/t3');
  }
  let existedBefore: string[] = [];
  let existedBeforeFiles: string[] = [];
  let settingsKeysBefore: string[] = [];
  let settingsFileBefore = false;
  if (S.apply) {
    existedBefore = installerDirs.filter((dir) =>
      isDirectory(joinMaxstackPath(S.workspace, dir)),
    );
    settingsFileBefore = isFile(S.piSettingsTarget);
    if (settingsFileBefore) {
      try {
        const settingsBefore = JSON.parse(readText(S.piSettingsTarget)) as Record<string, unknown>;
        if (settingsBefore !== null) settingsKeysBefore = Object.keys(settingsBefore);
      } catch {
        settingsKeysBefore = [];
      }
    }
    existedBeforeFiles = REPLACED_FILE_NAMES.filter((path) =>
      isFile(joinMaxstackPath(S.workspace, path)),
    );
  }

  if (S.apply) {
    for (const layer of layers) {
      if (layer.root === null) layer.root = getLayerRoot(layer, S.claudeCacheTarget);
    }
    const knownLayers = layers.filter((layer) => layer.root !== null);
    getWorkspaceInstructionPlan(knownLayers, selectedRuntimes, true);
  }

  if (S.apply && cursorSelected) {
    assertCursorSkillsPath();
    const cursorStageRoot = join(tmpdir(), `maxstack-cursor-preflight-${randomUUID().replaceAll('-', '')}`);
    mkdirSync(cursorStageRoot, { recursive: true });
    try {
      for (const layer of layers.filter((entry) => entry.url !== null)) {
        const stageCache = syncGitPlugin(layer, join(cursorStageRoot, '.claude/cache'));
        layer.root = joinSourceSub(stageCache, layer.sourcePath);
        if (!isDirectory(layer.root)) {
          throw new Error(`Layer '${layer.name}' has no ${layer.sourcePath} folder at the pinned commit.`);
        }
      }
      const stagedCursorSkills = getLayerSkills(layers, 'cursor');
      assertCursorSkillTargets(stagedCursorSkills, priorOwned);
      if (codexSelected || antigravitySelected) {
        const stagedAgentSkills = getLayerSkills(layers);
        assertCodexSkillTargets(stagedAgentSkills, priorOwned, antigravitySelected);
      }
    } finally {
      const tempRoot = trimEndingSeparator(resolve(tmpdir()));
      const stageFull = resolve(cursorStageRoot);
      if (!stageFull.toLowerCase().startsWith(`${tempRoot.toLowerCase()}/`)) {
        throw new Error(`Cursor preflight cleanup target '${stageFull}' is outside the temporary directory.`);
      }
      removeOwnedTree(stageFull);
    }
  }

  if (S.apply && (codexSelected || antigravitySelected)) {
    assertCodexSkillsPath();
    if (!cursorSelected) {
      const skillStageRoot = join(tmpdir(), `maxstack-agents-preflight-${randomUUID().replaceAll('-', '')}`);
      mkdirSync(skillStageRoot, { recursive: true });
      try {
        for (const layer of layers.filter((entry) => entry.url !== null)) {
          const stageCache = syncGitPlugin(layer, join(skillStageRoot, '.claude/cache'));
          layer.root = joinSourceSub(stageCache, layer.sourcePath);
          if (!isDirectory(layer.root)) {
            throw new Error(`Layer '${layer.name}' has no ${layer.sourcePath} folder at the pinned commit.`);
          }
        }
        const stagedSkills = getLayerSkills(layers);
        assertCodexSkillTargets(stagedSkills, priorOwned, antigravitySelected);
      } finally {
        const tempRoot = trimEndingSeparator(resolve(tmpdir()));
        const stageFull = resolve(skillStageRoot);
        if (!stageFull.toLowerCase().startsWith(`${tempRoot.toLowerCase()}/`)) {
          throw new Error(`Skill preflight cleanup target '${stageFull}' is outside the temporary directory.`);
        }
        removeOwnedTree(stageFull);
      }
    }
  }

  if (S.apply) {
    for (const layer of layers.filter((entry) => entry.url !== null)) {
      const cache = syncGitPlugin(layer, S.claudeCacheTarget);
      layer.root = joinSourceSub(cache, layer.sourcePath);
      if (!isDirectory(layer.root)) {
        throw new Error(`Layer '${layer.name}' has no ${layer.sourcePath} folder at the pinned commit.`);
      }
    }
  }
  for (const layer of layers.filter((entry) => entry.url !== null)) {
    layer.root = getLayerRoot(layer, S.claudeCacheTarget);
  }

  const workspaceInstructionPlan = getWorkspaceInstructionPlan(layers, selectedRuntimes);
  const workspaceInstructionFiles = workspaceInstructionPlan.files;
  let copilotInstructionDirectory: string | null = null;
  if (copilotSelected && workspaceInstructionPlan.text) {
    copilotInstructionDirectory = joinMaxstackPath(S.workspace, '.maxstack/copilot-instructions');
    assertCopilotInstructionDirectory(copilotInstructionDirectory);
  }
  let t3InstancesPlan = getT3InstancesPlan(layers, selectedLayers, workspaceSettings);
  if (S.removing) t3InstancesPlan = null;

  let codexSkills: SkillEntry[] = [];
  let cursorSkills: SkillEntry[] = [];
  let codexHookConfigPlan: HookConfigPlan | null = null;
  let cursorHookConfigPlan: HookConfigPlan | null = null;
  let antigravityHookConfigPlan: HookConfigPlan | null = null;
  if (codexSelected || antigravitySelected) {
    codexSkills = getLayerSkills(layers);
    if (S.apply) assertCodexSkillTargets(codexSkills, priorOwned, antigravitySelected);
  }
  if (cursorSelected) {
    cursorSkills = getLayerSkills(layers, 'cursor');
    if (S.apply) assertCursorSkillTargets(cursorSkills, priorOwned);
  }
  if (codexSelected && !(S.removing || S.uninstalling)) {
    codexHookConfigPlan = getCodexHookConfigPlan(layers, openCodeSelected);
  }
  if (cursorSelected && !S.uninstalling) {
    cursorHookConfigPlan = getCursorHookConfigPlan(layers, openCodeSelected, claudeSelected);
  }
  if (antigravitySelected && !S.uninstalling) {
    antigravityHookConfigPlan = getAntigravityHookConfigPlan(layers, openCodeSelected, claudeSelected);
  }
  const agentHookPlans = [codexHookConfigPlan, cursorHookConfigPlan, antigravityHookConfigPlan].filter(
    (plan): plan is HookConfigPlan => plan !== null,
  );

  const claudeRecords = layers
    .map((layer) => getClaudeRecord(layer))
    .filter((record): record is Record<string, unknown> => record !== null);

  const openCodeLayers = layers.filter((layer) => Object.hasOwn(layer.runtimes, 'opencode'));
  const openCodeSpecs = new Map<string, OpenCodeSpec>();
  for (const layer of openCodeLayers) openCodeSpecs.set(layer.name, getOpenCodeSpec(layer));

  const priorOpenCodeFolders = [...priorLayers.values()]
    .map((record) => getField(getField(record, 'opencode'), 'folder'))
    .filter((folder): folder is string => Boolean(folder))
    .map((folder) => basename(folder));

  const copilotLayers = layers.filter((layer) => Object.hasOwn(layer.runtimes, 'copilot'));
  const copilotDirs = copilotLayers.map((layer) => joinMaxstackPath(S.claudePluginsTarget, layer.name));
  const copilotExecutable = copilotLayers.length > 0 ? findWrappedExecutable(options.copilotCommand) : null;
  let copilotCmdText: string | null = null;
  let copilotShText: string | null = null;
  let copilotKept = false;
  const skippedRuntimeWrappers: Array<{ runtime: string; paths: string[] }> = [];
  if (copilotExecutable !== null) {
    copilotCmdText = newCopilotCmdText(copilotExecutable, copilotDirs, copilotInstructionDirectory);
    copilotShText = newCopilotShText(copilotDirs, copilotInstructionDirectory);
  } else if (copilotLayers.length > 0) {
    const copilotKeptPair = getKeptWrapperPair('.maxstack/bin/copilot.cmd', '.maxstack/bin/copilot.sh');
    copilotKept = copilotKeptPair !== null;
    if (copilotKeptPair !== null) {
      copilotCmdText = copilotKeptPair.cmd;
      copilotShText = copilotKeptPair.sh;
    }
    const copilotNotFound = `no '${options.copilotCommand}' application outside .maxstack/bin`;
    if (copilotKept) {
      writeWarning(
        `Copilot CLI not found: ${copilotNotFound}. Kept ${copilotWrapperDisplay} because Copilot was not found on this run. The lock records them, so they stay as they are and still name the Copilot they were written for. Install Copilot, then rerun with -Apply.`,
      );
    } else {
      writeWarning(
        `Copilot CLI not found: ${copilotNotFound}. Skipping ${copilotWrapperDisplay}. Install Copilot, then rerun with -Apply.`,
      );
      skippedRuntimeWrappers.push({ runtime: 'copilot', paths: copilotWrapperPaths });
    }
  }

  const piLayers = layers.filter((layer) => Object.hasOwn(layer.runtimes, 'pi'));
  const piRecords = piLayers
    .map((layer) => getPiLayerRecord(layer))
    .filter((record): record is PiLayerRecord => record !== null);
  const piByLayer = new Map<string, PiLayerRecord>();
  for (const record of piRecords) piByLayer.set(record.layer, record);
  const piPending = piRecords.some((record) => record.pending);
  const piPackageEntries = piRecords
    .filter((record) => record.package)
    .map((record) => record.packageEntry as string);
  const piSkillEntries = piRecords.filter((record) => record.skills).map((record) => `../../${record.skills as string}`);
  const piExecutable = piLayers.length > 0 ? findPiExecutable() : null;
  const piLocal =
    piExecutable !== null && ordinalEqual(dirname(piExecutable), S.piLocalBinTarget);
  let piCmdText: string | null = null;
  let piShText: string | null = null;
  let piUpdaterText: string | null = null;
  let piUpdaterPreserveRecord: OwnedRecord | null = null;
  let piUpdaterRemoveStale = false;
  let piKept = false;
  if (piExecutable !== null) {
    const piNpmPrefix = joinMaxstackPath(S.workspace, '.maxstack/npm');
    piCmdText = newPiCmdText(piExecutable, S.piAgentDir, piNpmPrefix, piLocal);
    if (IS_WINDOWS && piLocal) piUpdaterText = readText(join(options.scriptRoot, 'pi-self-update.mjs'));
    piShText = newPiShText(
      S.piAgentDir,
      piLocal ? piExecutable : '',
      piNpmPrefix,
      piLocal,
      piExecutable,
    );
    if (IS_WINDOWS && !piLocal) {
      const helperRelative = '.maxstack/bin/pi-self-update.mjs';
      const helperRecord = getPriorOwnedFileRecord(helperRelative);
      if (helperRecord !== null) {
        const helperPath = joinMaxstackPath(S.workspace, helperRelative);
        if (testRecordedFile(helperPath, helperRecord.sha256 ?? null)) {
          piUpdaterRemoveStale = true;
        } else {
          writeWarning(
            `Kept ${helperPath}: it changed since the last apply, so it was not removed during the external Pi transition.`,
          );
          piUpdaterPreserveRecord = {
            path: helperRecord.path,
            kind: helperRecord.kind,
            sha256: helperRecord.sha256,
            runtime: helperRecord.runtime,
            layers: [...(helperRecord.layers ?? [])],
            preserve: true,
          };
        }
      }
    }
  } else if (piLayers.length > 0) {
    const piKeptPair = getKeptWrapperPair('.maxstack/bin/pi.cmd', '.maxstack/bin/pi.sh');
    piKept = piKeptPair !== null;
    if (piKeptPair !== null) {
      piCmdText = piKeptPair.cmd;
      piShText = piKeptPair.sh;
      const helperPath = joinMaxstackPath(S.workspace, '.maxstack/bin/pi-self-update.mjs');
      const helperRecord = getPriorOwnedFileRecord('.maxstack/bin/pi-self-update.mjs');
      if (
        IS_WINDOWS &&
        helperRecord !== null &&
        isFile(helperPath) &&
        ordinalEqual(sha256FileOrNull(helperPath), helperRecord.sha256 ?? null)
      ) {
        piUpdaterText = readText(helperPath);
      } else if (IS_WINDOWS && helperRecord !== null) {
        writeWarning(
          `Kept Pi updater ownership for ${helperPath}: the helper is missing or changed, so status and uninstall can still report it.`,
        );
        piUpdaterPreserveRecord = {
          path: helperRecord.path,
          kind: helperRecord.kind,
          sha256: helperRecord.sha256,
          runtime: helperRecord.runtime,
          layers: [...(helperRecord.layers ?? [])],
          preserve: true,
        };
        if (S.apply) {
          throw new Error(
            `Pi updater helper ${helperPath} is missing or changed. Restore the recorded helper before applying while Pi is unavailable.`,
          );
        }
      }
    }
    const notFound = `no '${options.piCommand}' application outside .maxstack/bin, and no pi under ${S.piLocalBinTarget}`;
    if (piKept) {
      writeWarning(
        `Pi CLI not found: ${notFound}. Kept ${piWrapperDisplay} because Pi was not found on this run. The lock records them, so they stay as they are and still name the Pi they were written for. Install Pi, then rerun with -Apply.`,
      );
    } else {
      writeWarning(
        `Pi CLI not found: ${notFound}. Skipping ${piWrapperDisplay}. Install Pi, then rerun with -Apply.`,
      );
      skippedRuntimeWrappers.push({ runtime: 'pi', paths: piWrapperPaths });
    }
  }
  let piSettings: PiSettingsResult | null = null;
  if (piSelected && (piLayers.length > 0 || isFile(S.piSettingsTarget))) {
    piSettings = getPiSettings(
      piPackageEntries,
      piSkillEntries,
      getOwnedPiEntries(priorOwned, priorPi, 'packages'),
      getOwnedPiEntries(priorOwned, priorPi, 'skills'),
    );
  }

  const configUnknown =
    layers.some((layer) => ordinalEqual(layer.kind, 'config') && layer.root === null);
  let document: string | null = null;
  if (openCodeSelected && !configUnknown) {
    document = getConfigDocument({
      layers,
      openCodeLayers,
      openCodeSpecs,
      workspaceInstructionPlan,
      baseConfigFile,
    });
  }

  const piUnknown: { packages: string[]; skills: string[] } = { packages: [], skills: [] };
  for (const record of piRecords) {
    if (!record.pending) continue;
    piUnknown.packages.push(`../../${record.unknownPackage}`);
    piUnknown.skills.push(`../../${record.unknownSkills}`);
  }

  let configBackupTarget: BackupTarget = { action: 'none', path: null };
  let configSourceSha: string | null = null;
  if (document !== null) {
    configSourceSha = sha256FileOrNull(S.configTarget);
    configBackupTarget = getBackupTarget(
      S.configTarget,
      priorOpenCodeSha,
      document,
      ordinalIn('opencode.jsonc', priorCreatedFiles),
      getPriorOriginalSha('opencode.jsonc'),
    );
  }
  let settingsBackupTarget: BackupTarget = { action: 'none', path: null };
  if (piSettings !== null && !piPending) {
    settingsBackupTarget = getBackupTarget(
      S.piSettingsTarget,
      S.priorSettingsSha,
      piSettings.text,
      ordinalIn('.pi/agent/settings.json', priorCreatedFiles),
      getPriorOriginalSha('.pi/agent/settings.json'),
    );
  }

  const keptJournals = new Set<string>();
  if (S.apply && !S.removing && !S.uninstalling && priorOwned !== null) {
    for (const record of priorOwned.filter(
      (entry) => ordinalEqual(entry.kind, 'dir') && getField(entry, 'quarantine') !== null,
    )) {
      const entry = resolveWorkspaceEntry(record.path);
      if (!entry.ok) continue;
      const quarantine = `${entry.full}${QUARANTINE_SUFFIX}`;
      if (!pathExists(quarantine)) continue;
      const leaf = quarantine.slice(quarantine.lastIndexOf('/') + 1);
      if (!testReparsePoint(quarantine) && ordinalEqual(getTreeSha256(quarantine), record.sha256 ?? null)) {
        removeOwnedTree(quarantine);
        writeHost(`Deleted ${leaf}, the quarantine an interrupted removal left for ${record.path}.`);
      } else {
        keptJournals.add(record.path);
        writeHost(
          `SKIP     ${record.path}  kept: ${leaf} holds files that changed since its removal began, so it is not deleted. The folder is written again beside it; delete or move ${leaf} aside by hand.`,
        );
      }
    }
  }

  let plan: OwnedRecord[] = [];
  if (S.apply || S.removing || S.updating || priorOwned !== null) {
    plan = getOwnedPlan({
      document,
      layers,
      claudeRecords,
      openCodeLayers,
      openCodeSpecs,
      copilotCmdText,
      copilotShText,
      piCmdText,
      piShText,
      piUpdaterText,
      piUpdaterPreserveRecord,
      piSettings,
      piPending,
      piUnknown,
      codexSkills,
      skillRuntimeClaims: [codexSelected ? 'codex' : '', antigravitySelected ? 'antigravity' : ''].filter(Boolean),
      cursorSkills,
      workspaceInstructionFiles,
      agentHookPlans,
      configBackupTarget,
      settingsBackupTarget,
    });
    if (t3InstancesPlan !== null) {
      plan.push({
        path: t3InstancesPlan.path as string,
        kind: 'file',
        sha256: t3InstancesPlan.sha256 as string,
        runtime: t3InstancesPlan.runtime as string,
        layers: [...((t3InstancesPlan.layers as string[]) ?? [])],
        preserve: Boolean(t3InstancesPlan.preserve),
      });
    }
  }
  const priorT3Snapshot = (priorOwned ?? []).filter(
    (record) =>
      ordinalEqual(getField(record, 'path'), '.maxstack/t3/settings.snapshot.json') &&
      ordinalEqual(getField(record, 'kind'), 'file'),
  );
  const preserveT3SnapshotRecord =
    priorT3Snapshot.length > 0 && (t3Report === null || !ordinalEqual(t3Report.sourceState, 'present'));
  let t3SnapshotPlan: OwnedRecord | null = null;
  if (t3Report !== null && ordinalEqual(t3Report.sourceState, 'present')) {
    const snapshotPath = joinMaxstackPath(S.workspace, '.maxstack/t3/settings.snapshot.json');
    let snapshotPreserve = false;
    if (pathExists(snapshotPath)) {
      const priorSnapshot = priorT3Snapshot.length > 0 ? priorT3Snapshot[0] : null;
      snapshotPreserve = priorSnapshot === null;
      if (priorSnapshot !== null) {
        snapshotPreserve = testReparsePoint(snapshotPath) || !isFile(snapshotPath);
        if (!snapshotPreserve) {
          snapshotPreserve = !ordinalEqual(sha256FileOrNull(snapshotPath), priorSnapshot.sha256 ?? null);
        }
      }
      if (snapshotPreserve) {
        const reason =
          priorSnapshot === null
            ? 'it exists and was not written by maxstack'
            : 'it changed since the last apply, so it was not overwritten';
        writeHost(`Kept .maxstack/t3/settings.snapshot.json: ${reason}.`);
      }
    }
    t3SnapshotPlan = {
      path: '.maxstack/t3/settings.snapshot.json',
      kind: 'file',
      sha256: t3Report.snapshotSha256,
      runtime: null,
      layers: [],
      preserve: snapshotPreserve,
    };
    plan.push(t3SnapshotPlan);
  } else if (preserveT3SnapshotRecord) {
    plan.push(priorT3Snapshot[0]);
  }

  let staleOpenCodeFolders: string[] = [];
  if (openCodeSelected) {
    staleOpenCodeFolders = getStalePluginFolders(openCodeLayers.map((layer) => layer.name)).filter(
      (name) => !ordinalIn(name, unselectedLayerNames),
    );
  }

  let updateChanges = 0;
  if (S.updating) {
    updateChanges = writeUpdateReport({
      layers: allLayers,
      priorStack: priorStack as Record<string, unknown> | null,
      selectedLayers,
      selectedRuntimes,
      plan,
      owned: priorOwned,
      notSelected: getNotSelectedPaths(selectedRuntimes),
    });
  }

  if (S.status) {
    if (priorStack === null) {
      writeHost('Selection: none recorded; an apply selects all');
    } else {
      const legacyNote = getField(priorStack, 'selection') === null ? ' (the lock predates the selection, so all)' : '';
      writeHost(`${formatSelection(selectedRuntimes, selectedLayers)}${legacyNote}`);
    }
    writeSourcePinBlock(getRecordedSourceEntries(priorStack as Record<string, unknown> | null));
    if (codexSelected) {
      writeCodexNotes({
        layers,
        applying: false,
        openCodeSelected,
        workspaceInstructionPlan,
        hookConfigPlan: codexHookConfigPlan,
      });
    }
    if (priorOwned === null) {
      writeHost('no ownership record; run -Apply once to create it');
      if (S.strict) process.exitCode = 1;
      return currentExitCode();
    }
    const notSelected = getNotSelectedPaths(selectedRuntimes);
    const skippedLayerNames = allLayers
      .filter((layer) => layer.settingsSourced && layer.settingsFault !== null)
      .map((layer) => layer.name);
    const results = getOwnershipReport({
      recorded: priorOwned,
      plan,
      selectedRuntimes,
      notSelected,
      skippedLayers: skippedLayerNames,
    });
    for (const note of unselectedNotes) {
      results.push({ state: 'not selected', label: `${note.kind} ${note.name} (add with ${note.flag} ${note.name})` });
    }
    for (const result of results) writeHost(`${result.state.padEnd(12)} ${result.label}`);
    const states = ['matching', 'drifted', 'modified', 'missing', 'untracked', 'not selected'];
    if (results.some((result) => ordinalEqual(result.state, 'skipped'))) states.push('skipped');
    const counts = states.map(
      (state) => `${results.filter((result) => ordinalEqual(result.state, state)).length} ${state}`,
    );
    writeHost(`Summary: ${counts.join(', ')}`);
    const t3Strict = t3Report !== null && (t3Report.strictFailures ?? []).length > 0;
    const ownershipStrict = results.some((result) => {
      const unmatched = !ordinalIn(result.state, ['matching', 'not selected', 'skipped']);
      const staleSnapshot =
        t3Report !== null &&
        t3Report.stale &&
        ordinalEqual(result.state, 'drifted') &&
        ordinalEqual(result.label, '.maxstack/t3/settings.snapshot.json');
      return unmatched && !staleSnapshot;
    });
    if (
      S.strict &&
      (ownershipStrict ||
        settingsInvalid ||
        settingsChanged ||
        pendingRuntimes.length > 0 ||
        pendingLayers.length > 0 ||
        unlistedRuntimes.length > 0 ||
        unlistedLayers.length > 0 ||
        t3Strict)
    ) {
      process.exitCode = 1;
    }
    return currentExitCode();
  }

  if (!S.apply) {
    writeHost(`Workspace:      ${S.workspace}`);
    writeHost(formatSelection(selectedRuntimes, selectedLayers));
    writeSourcePinBlock(getResolvedSourceEntries(allLayers));
    if (codexSelected) {
      writeCodexNotes({
        layers,
        applying: false,
        openCodeSelected,
        workspaceInstructionPlan,
        hookConfigPlan: codexHookConfigPlan,
      });
    }
    for (const layer of layers) {
      let where: string;
      if (layer.root) where = layer.root;
      else if (ordinalEqual(layer.sourceKind, 'local')) {
        const reason = layer.folderMissing ? 'folder missing' : `unreadable: ${safeName(String(layer.unreadable))}`;
        where = `${safeName(String(layer.localPath))}: ${reason}`;
      } else {
        where = `pinned ${layer.url} at ${layer.commit}`;
      }
      writeHost(`Layer:          ${layer.name} (${layer.kind}) at ${where}`);
    }
    if (workspaceInstructionPlan.text) {
      for (const file of workspaceInstructionFiles) {
        let state = getDriftState(
          joinMaxstackPath(S.workspace, convertToMaxstackPath(file.path)),
          file.text,
        );
        if (isTrue(getField(file, 'preserve'))) state = 'modified by hand; would keep';
        writeHost(`Workspace instructions: would write or keep ${file.path} (${state})`);
      }
    } else {
      writeHost('Workspace instructions: none selected layers declare workspaceInstructions.');
    }
    if (t3InstancesPlan !== null) {
      const t3Path = joinMaxstackPath(S.workspace, convertToMaxstackPath(t3InstancesPlan.path as string));
      const t3State = isTrue(t3InstancesPlan.preserve)
        ? 'modified by hand; would keep'
        : getDriftState(t3Path, t3InstancesPlan.text as string);
      writeHost(`T3 instance list: would write or keep ${t3InstancesPlan.path} (${t3State})`);
    } else if (getPriorOwnedFileRecord('.pstack/pstack-t3-instances.json') !== null) {
      const t3Path = joinMaxstackPath(S.workspace, '.pstack/pstack-t3-instances.json');
      const t3Record = getPriorOwnedFileRecord('.pstack/pstack-t3-instances.json') as OwnedRecord;
      const t3State = !isFile(t3Path)
        ? 'missing; ownership will be cleared'
        : testReparsePoint(t3Path) || !ordinalEqual(sha256FileOrNull(t3Path), t3Record.sha256 ?? null)
          ? 'modified by hand; would keep'
          : 'would remove';
      writeHost(`T3 instance list: ${t3State} .pstack/pstack-t3-instances.json`);
    }
    if (openCodeSelected) {
      writeHost(`Config target:  ${S.configTarget}`);
      const configState = configUnknown
        ? 'unknown until -Apply syncs the layer cache'
        : getConfigTargetDrift(document);
      writeHost(`Drift:          ${S.configTarget}: ${configState}`);
    }
    if (claudeSelected) {
      const wantedClaude = claudeRecords.map((record) => record.plugin);
      for (const record of claudeRecords) {
        const child = joinMaxstackPath(S.claudePluginsTarget, String(record.plugin));
        const target = isLinkRecordKind(record.kind)
          ? joinMaxstackPath(S.workspace, String(record.target))
          : null;
        const prior = getField(priorLayers.get(String(record.layer)), 'claude') as Record<string, unknown> | null;
        writeHost(
          `Drift:          ${child}: ${getClaudeChildState(record, prior, child, target)}`,
        );
      }
      if (isDirectory(S.claudePluginsTarget)) {
        for (const entry of readdirSync(S.claudePluginsTarget, { withFileTypes: true })) {
          if (!ordinalIn(entry.name, wantedClaude) && !ordinalIn(entry.name, unselectedLayerNames)) {
            writeHost(`Drift:          ${join(S.claudePluginsTarget, entry.name)}: stale`);
          }
        }
      }
    }
    for (const layer of openCodeLayers) {
      const folder = joinMaxstackPath(S.opencodePluginsTarget, layer.name);
      const relative = `.opencode/plugins/${layer.name}`;
      const record = (priorOwned ?? []).find(
        (entry) => ordinalEqual(entry.path, relative) && ordinalEqual(entry.kind, 'dir'),
      );
      const planned = plan.find(
        (entry) => ordinalEqual(entry.path, relative) && ordinalEqual(entry.kind, 'dir'),
      );
      const state = record === undefined ? 'missing' : getOwnedState(record, planned ?? null);
      writeHost(`Drift:          ${folder}: ${state}`);
    }
    for (const name of staleOpenCodeFolders) {
      writeHost(`Drift:          ${join(S.opencodePluginsTarget, name)}: stale`);
    }
    if (copilotSelected) {
      if (copilotCmdText) {
        writeHost(`Drift:          ${copilotCmdTarget}: ${getDriftState(copilotCmdTarget, copilotCmdText)}`);
        writeHost(`Drift:          ${copilotShTarget}: ${getDriftState(copilotShTarget, copilotShText as string)}`);
      } else {
        for (const path of [copilotCmdTarget, copilotShTarget]) {
          if (isFile(path)) writeHost(`Drift:          ${path}: stale`);
        }
      }
    }
    if (piSelected) {
      if (piCmdText) {
        writeHost(`Drift:          ${piCmdTarget}: ${getDriftState(piCmdTarget, piCmdText)}`);
        writeHost(`Drift:          ${piShTarget}: ${getDriftState(piShTarget, piShText as string)}`);
      } else {
        for (const path of [piCmdTarget, piShTarget]) {
          if (isFile(path)) writeHost(`Drift:          ${path}: stale`);
        }
      }
      if (piPending) {
        writeHost(`Drift:          ${S.piSettingsTarget}: unknown until -Apply syncs the pstack cache`);
      } else if (piSettings) {
        writeHost(`Drift:          ${S.piSettingsTarget}: ${getDriftState(S.piSettingsTarget, piSettings.text)}`);
      }
    }
    if (S.removing) {
      writeRemovalDryRun({ records: priorOwned ?? [], plan, selectedRuntimes, selectedLayers });
      return currentExitCode();
    }
    if (S.updating) {
      writeUpdateSummary(updateChanges);
      writeHost('Dry run: nothing was written. Rerun with -Update -Apply to move the sources and apply the change.');
      if (S.strict && updateChanges > 0) process.exitCode = 1;
      return currentExitCode();
    }
    writeHost('Audit only. No files or workspace configuration changed. Rerun with -Apply after reviewing.');
    return currentExitCode();
  }

  if (openCodeSelected) {
    mkdirSync(dirname(S.configTarget), { recursive: true });
    if (isFile(S.configTarget) && ordinalEqual(readText(S.configTarget).trim(), (document as string).trim())) {
      writeHost(`Config already matches: ${S.configTarget}`);
    } else {
      if (ordinalIn(configBackupTarget.action, ['original', 'edited'])) {
        copyFileSync(S.configTarget, configBackupTarget.path as string);
        writeHost(`Backed up the previous config to ${configBackupTarget.path}`);
      } else if (ordinalEqual(configBackupTarget.action, 'duplicate')) {
        writeHost(`The previous config is already kept in ${configBackupTarget.path}, so no new copy was made.`);
      }
      assertUnchangedSince(S.configTarget, configSourceSha);
      writeFileAtomic(S.configTarget, document as string);
      writeHost(`Wrote ${S.configTarget}`);
    }
  }

  writeWorkspaceInstructionFiles(workspaceInstructionFiles, priorOwned);
  writeT3InstancesFile(t3InstancesPlan);

  const agentNamesByLayer = new Map<string, string[]>();
  for (const layer of openCodeLayers) {
    const spec = openCodeSpecs.get(layer.name) as OpenCodeSpec;
    const claudeDeclared = Object.hasOwn(layer.runtimes, 'claude');
    const folder = joinMaxstackPath(S.opencodePluginsTarget, layer.name);
    mkdirSync(folder, { recursive: true });
    const items = getOpenCodeItems(layer, layer.root as string).filter(
      (item) => !ordinalEqual(item, '.claude-plugin') || claudeDeclared,
    );
    removeFolderExtras(folder, items, true);
    for (const item of items) {
      const source = joinMaxstackPath(layer.root as string, item);
      if (!pathExists(source)) throw new Error(`Plugin layer '${layer.name}' is missing: ${source}`);
      const destination = joinMaxstackPath(folder, item);
      removeOwnedTree(destination);
      mkdirSync(dirname(destination), { recursive: true });
      copyTree(source, destination);
    }
    const entryPath = joinMaxstackPath(folder, convertToMaxstackPath(spec.entry));
    if (!isFile(entryPath)) {
      throw new Error(
        `Plugin layer '${layer.name}' has no entry at ${entryPath}. Check runtimes.opencode.entry in layers.json.`,
      );
    }
    writeHost(`Copied plugin layer '${layer.name}' into ${folder}`);

    const installDir = ordinalEqual(spec.dir, '') ? folder : joinMaxstackPath(folder, convertToMaxstackPath(spec.dir));
    const shippedLocks = getShippedLocks(installDir);
    if (
      isFile(joinMaxstackPath(installDir, 'package.json')) &&
      !pathExists(joinMaxstackPath(installDir, 'node_modules/@opencode/plugin'))
    ) {
      writeHost('Installing plugin dependencies');
      const run = spawnSync(
        'npm',
        ['install', '--prefix', installDir, '--omit=dev', '--no-audit', '--no-fund', '--ignore-scripts'],
        { stdio: 'inherit', windowsHide: true },
      );
      if (run.error || run.status !== 0) throw new Error(`npm install failed in ${installDir}`);
      writeIgnoredScriptWarning(layer.name, installDir);
    }
    resolveNpmLocks(installDir, shippedLocks);

    agentNamesByLayer.set(layer.name, []);
    if (spec.agents) {
      const agentsSource = joinMaxstackPath(layer.root as string, convertToMaxstackPath(spec.agents));
      if (!isDirectory(agentsSource)) {
        throw new Error(`Plugin layer '${layer.name}' names agents at ${agentsSource}, which does not exist.`);
      }
      mkdirSync(S.agentsTarget, { recursive: true });
      for (const name of agentFileNames(agentsSource)) {
        const destination = joinMaxstackPath(S.agentsTarget, name);
        copyFileSync(join(agentsSource, name), destination);
        removeAgentModel(destination);
        writeHost(`Installed agent profile ${name}`);
        (agentNamesByLayer.get(layer.name) as string[]).push(name);
      }
    }
  }

  for (const name of staleOpenCodeFolders) {
    if (name.endsWith(QUARANTINE_SUFFIX)) {
      const recordedBase = `.opencode/plugins/${name.slice(0, name.length - QUARANTINE_SUFFIX.length)}`;
      if ((priorOwned ?? []).some((entry) => ordinalEqual(entry.kind, 'dir') && ordinalEqual(entry.path, recordedBase))) {
        continue;
      }
    }
    if (ordinalIn(name, priorOpenCodeFolders) || ordinalIn(name, RETIRED_OPENCODE_FOLDERS)) {
      const full = join(S.opencodePluginsTarget, name);
      removeOwnedTree(full);
      writeHost(`Removed the stale plugin folder ${full}`);
    } else {
      writeHost(
        `Drift:          ${join(S.opencodePluginsTarget, name)}: stale, kept because the previous stack.lock.json does not record it`,
      );
    }
  }

  const layerByName = new Map<string, LayerModel>();
  for (const layer of layers) layerByName.set(layer.name, layer);
  if (claudeSelected) {
    mkdirSync(S.claudePluginsTarget, { recursive: true });
    for (const record of claudeRecords) {
      const child = joinMaxstackPath(S.claudePluginsTarget, String(record.plugin));
      const kind = getField(record, 'kind');
      if (isLinkRecordKind(kind)) {
        const target = joinMaxstackPath(S.workspace, String(record.target));
        if (!testClaudeLink(child, target, String(kind))) {
          removeOwnedTree(child);
          createMaxstackDirectoryLink(child, target);
          writeHost(`Linked Claude plugin '${String(record.plugin)}' to ${target}`);
        }
      } else if (ordinalEqual(kind, 'copy') && getField(record, 'items') !== null) {
        removeOwnedTree(child);
        copyLayerItems(
          (layerByName.get(String(record.layer)) as LayerModel).root as string,
          (record.items as string[]).map(String),
          child,
        );
        writeHost(
          `Copied Claude plugin '${String(record.plugin)}' from ${(layerByName.get(String(record.layer)) as LayerModel).root}`,
        );
      } else {
        removeOwnedTree(child);
        copyWholeFolder((layerByName.get(String(record.layer)) as LayerModel).root as string, child);
        if (getField(record, 'url') !== null) {
          writeHost(`Copied Claude plugin '${String(record.plugin)}' from ${String(record.url)} at ${String(record.commit)}`);
        } else {
          writeHost(
            `Copied Claude plugin '${String(record.plugin)}' from ${(layerByName.get(String(record.layer)) as LayerModel).root}`,
          );
        }
      }
      let declared: unknown = null;
      try {
        declared = getField(
          JSON.parse(readText(joinMaxstackPath(child, '.claude-plugin/plugin.json'))) as unknown,
          'name',
        );
      } catch {
        declared = null;
      }
      if (!ordinalEqual(declared, record.plugin)) {
        throw new Error(
          `Claude plugin '${String(record.plugin)}' materialised at ${child} names '${String(declared)}' in its manifest.`,
        );
      }
    }
    if (isDirectory(S.claudePluginsTarget)) {
      const wantedClaude = claudeRecords.map((record) => String(record.plugin));
      for (const entry of readdirSync(S.claudePluginsTarget, { withFileTypes: true })) {
        if (!ordinalIn(entry.name, wantedClaude) && !ordinalIn(entry.name, unselectedLayerNames)) {
          removeOwnedTree(join(S.claudePluginsTarget, entry.name));
          writeHost(`Removed the stale Claude plugin ${entry.name}`);
        }
      }
    }
  }

  if (copilotKept) {
    writeHost(`Kept ${copilotWrapperDisplay} as they were, because Copilot was not found on this run`);
  } else if (copilotCmdText) {
    mkdirSync(S.copilotBinTarget, { recursive: true });
    if (IS_WINDOWS) writeFileSync(copilotCmdTarget, copilotCmdText, 'utf8');
    writeFileSync(copilotShTarget, copilotShText as string, 'utf8');
    setShellExecutable(copilotShTarget);
    writeHost(IS_WINDOWS ? `Wrote ${copilotCmdTarget} and ${copilotShTarget}` : `Wrote ${copilotShTarget}`);
  } else if (copilotSelected && copilotLayers.length === 0) {
    for (const path of IS_WINDOWS ? [copilotCmdTarget, copilotShTarget] : [copilotShTarget]) {
      if (isFile(path)) removeWrapperIfRecorded(path);
    }
  }

  for (const record of piRecords) {
    if (record.package) assertPiKeyInstalled(record);
    if (
      record.skills &&
      !isDirectory(joinMaxstackPath(S.workspace, convertToMaxstackPath(record.skills)))
    ) {
      throw new Error(
        `Layer '${record.layer}' has no skills folder at ${record.skills} after the install. Check runtimes.pi and the layer's files list.`,
      );
    }
  }
  if (piSettings) {
    const piSettingsText = piSettings.text;
    mkdirSync(S.piAgentDir, { recursive: true });
    if (isFile(S.piSettingsTarget) && ordinalEqual(readText(S.piSettingsTarget).trim(), piSettingsText.trim())) {
      writeHost(`Pi settings already match: ${S.piSettingsTarget}`);
    } else {
      if (ordinalIn(settingsBackupTarget.action, ['original', 'edited'])) {
        copyFileSync(S.piSettingsTarget, settingsBackupTarget.path as string);
        writeHost(`Backed up the previous Pi settings to ${settingsBackupTarget.path}`);
      } else if (ordinalEqual(settingsBackupTarget.action, 'duplicate')) {
        writeHost(`The previous Pi settings are already kept in ${settingsBackupTarget.path}, so no new copy was made.`);
      }
      assertUnchangedSince(S.piSettingsTarget, piSettings.sourceSha);
      writeFileAtomic(S.piSettingsTarget, piSettingsText);
      writeHost(`Wrote ${S.piSettingsTarget}`);
    }
  }
  if (piKept) {
    writeHost(`Kept ${piWrapperDisplay} as they were, because Pi was not found on this run`);
  } else if (piCmdText) {
    mkdirSync(S.copilotBinTarget, { recursive: true });
    if (IS_WINDOWS) writeFileSync(piCmdTarget, piCmdText, 'utf8');
    if (IS_WINDOWS && piUpdaterText) {
      writeFileSync(joinMaxstackPath(S.workspace, '.maxstack/bin/pi-self-update.mjs'), piUpdaterText, 'utf8');
    }
    if (IS_WINDOWS && piUpdaterRemoveStale) {
      removeWrapperIfRecorded(joinMaxstackPath(S.workspace, '.maxstack/bin/pi-self-update.mjs'));
    }
    writeFileSync(piShTarget, piShText as string, 'utf8');
    setShellExecutable(piShTarget);
    writeHost(IS_WINDOWS ? `Wrote ${piCmdTarget} and ${piShTarget}` : `Wrote ${piShTarget}`);
  } else if (piSelected && piLayers.length === 0) {
    for (const path of IS_WINDOWS ? [piCmdTarget, piShTarget] : [piShTarget]) {
      if (isFile(path)) removeWrapperIfRecorded(path);
    }
  }

  if (S.apply && (codexSelected || antigravitySelected) && !(S.removing || S.uninstalling)) {
    writeCodexSkills(codexSkills, priorOwned, true);
  }
  if (S.apply && cursorSelected) {
    writeCursorSkills(cursorSkills, priorOwned, !S.removing);
  }
  if (S.apply && codexSelected && !S.removing) writeHookConfig(codexHookConfigPlan);
  if (S.apply && cursorSelected) writeHookConfig(cursorHookConfigPlan);
  if (S.apply && antigravitySelected) writeHookConfig(antigravityHookConfigPlan);

  const claudeByLayer = new Map<string, Record<string, unknown>>();
  for (const record of claudeRecords) claudeByLayer.set(String(record.layer), record);
  const layerRecords = allLayers.map((layer) => {
    const record = claudeByLayer.get(layer.name);
    let claude: Record<string, unknown>;
    if (record) {
      const child = joinMaxstackPath(S.claudePluginsTarget, String(record.plugin));
      const treeRoot = isLinkRecordKind(record.kind)
        ? joinMaxstackPath(S.workspace, String(record.target))
        : child;
      const treeSha = getLegacyTreeSha256(treeRoot);
      if (isLinkRecordKind(record.kind)) {
        claude = {
          enabled: true,
          plugin: record.plugin,
          kind: record.kind,
          child: `.claude/plugins/${String(record.plugin)}`,
          target: record.target,
          treeSha256: treeSha,
        };
      } else if (ordinalEqual(record.kind, 'copy')) {
        claude = {
          enabled: true,
          plugin: record.plugin,
          kind: 'copy',
          child: `.claude/plugins/${String(record.plugin)}`,
          treeSha256: treeSha,
        };
      } else {
        claude = {
          enabled: true,
          plugin: record.plugin,
          kind: 'git',
          child: `.claude/plugins/${String(record.plugin)}`,
          repository: record.url,
          path: record.path,
          commit: record.commit,
          treeSha256: treeSha,
        };
      }
    } else {
      claude = { enabled: false };
    }
    const spec = openCodeSpecs.get(layer.name);
    const opencode = spec
      ? {
          enabled: true,
          folder: `.opencode/plugins/${layer.name}`,
          entry: spec.entry,
          loader: spec.loader,
          plugin: getOpenCodePluginPath(layer, spec),
          agents: agentNamesByLayer.get(layer.name) ?? [],
        }
      : { enabled: false };
    const copilotRecord = Object.hasOwn(layer.runtimes, 'copilot')
      ? { enabled: true, pluginDir: `.claude/plugins/${layer.name}` }
      : { enabled: false };
    const piRecord = piByLayer.has(layer.name)
      ? {
          enabled: true,
          package: (piByLayer.get(layer.name) as PiLayerRecord).package,
          skills: (piByLayer.get(layer.name) as PiLayerRecord).skills,
        }
      : { enabled: false };
    return {
      name: layer.name,
      kind: layer.kind,
      path: layer.localPath,
      source: newSourceRecord(layer),
      commit: layer.commit,
      claude,
      opencode,
      copilot: copilotRecord,
      pi: piRecord,
    };
  });

  const copilotLock = copilotCmdText
    ? {
        enabled: true,
        executable: copilotExecutable ? basename(copilotExecutable) : getField(priorCopilot, 'executable'),
        wrappers: copilotWrapperPaths,
        ...(IS_WINDOWS ? { cmdSha256: getTextSha256(copilotCmdText) } : {}),
        shSha256: getTextSha256(copilotShText as string),
      }
    : {
        enabled: false,
        reason: !copilotSelected
          ? 'not selected'
          : copilotLayers.length === 0
            ? 'no layer declares copilot'
            : `no '${options.copilotCommand}' application outside .maxstack/bin`,
      };

  let settingsSha = S.priorSettingsSha;
  if (isFile(S.piSettingsTarget)) {
    if (piSettings) settingsSha = sha256FileOrNull(S.piSettingsTarget);
  } else {
    settingsSha = null;
  }

  const piLock = piCmdText
    ? {
        enabled: true,
        executable: piExecutable ? basename(piExecutable) : getField(priorPi, 'executable'),
        wrappers: piWrapperPaths,
        ...(IS_WINDOWS ? { cmdSha256: getTextSha256(piCmdText) } : {}),
        shSha256: getTextSha256(piShText as string),
        agentDir: '.pi/agent',
        packages: piPackageEntries,
        skills: piSkillEntries,
        settingsSha256: settingsSha,
      }
    : {
        enabled: false,
        reason: !piSelected
          ? 'not selected'
          : piLayers.length === 0
            ? 'no layer declares pi'
            : `no '${options.piCommand}' application outside .maxstack/bin, and no pi under .maxstack/npm`,
        agentDir: '.pi/agent',
        packages: piPackageEntries,
        skills: piSkillEntries,
        settingsSha256: settingsSha,
      };

  const priorCreatedKeys: string[] = [];
  if (priorOwned !== null) {
    for (const record of priorOwned) {
      if (ordinalEqual(record.kind, 'json-entries') && isTrue(getField(record, 'createdKey'))) {
        priorCreatedKeys.push(String(record.key));
      }
    }
  }
  let settingsNow: Record<string, unknown> | null = null;
  if (isFile(S.piSettingsTarget)) {
    try {
      settingsNow = JSON.parse(readText(S.piSettingsTarget)) as Record<string, unknown>;
    } catch {
      settingsNow = null;
    }
  }
  const createdKeys = new Map<string, boolean>();
  for (const key of ['packages', 'skills']) {
    const presentNow = settingsNow !== null && hasField(settingsNow, key);
    const createdHere = settingsFileBefore && !settingsKeysBefore.includes(key);
    createdKeys.set(key, Boolean(presentNow && (createdHere || priorCreatedKeys.includes(key))));
  }
  if (S.apply && t3Report !== null && ordinalEqual(t3Report.sourceState, 'present')) {
    if (!isTrue(getField(t3SnapshotPlan, 'preserve'))) {
      const t3SnapshotSha = writeT3Snapshot(S.workspace, t3Report);
      if (!ordinalEqualIgnoreCase(t3SnapshotSha, t3Report.snapshotSha256)) {
        throw new Error('T3 snapshot hash changed while it was written.');
      }
    }
  }
  const createdDirs = getCreatedPaths(installerDirs, priorCreatedDirs, existedBefore, 'dir');
  const createdFiles = getCreatedPaths(REPLACED_FILE_NAMES, priorCreatedFiles, existedBeforeFiles, 'file');

  const ownedPlan = preserveT3SnapshotRecord
    ? plan.filter((record) => !ordinalEqual(record.path, '.maxstack/t3/settings.snapshot.json'))
    : plan;
  const owned = getOwnedRecords(ownedPlan, createdKeys);
  if (preserveT3SnapshotRecord) owned.push(priorT3Snapshot[0]);
  for (const keptPath of keptJournals) {
    for (const record of owned.filter(
      (entry) => ordinalEqual(entry.path, keptPath) && ordinalEqual(entry.kind, 'dir'),
    )) {
      const quarantine = resolveWorkspaceEntry(keptPath);
      if (quarantine.full !== null) {
        record.quarantine = `${quarantine.full}${QUARANTINE_SUFFIX}`.slice(
          `${quarantine.full}${QUARANTINE_SUFFIX}`.lastIndexOf('/') + 1,
        );
      }
    }
  }

  const stack: StackDocument = {
    generatedAt: new Date().toISOString(),
    workspace: basename(trimEndingSeparator(S.workspace)),
    selection: { runtimes: selectedRuntimes, layers: selectedLayers },
    configSha256: document !== null ? getTextSha256(document) : null,
    copilot: copilotLock,
    pi: piLock,
    layers: layerRecords,
    ownedSchema: OWNED_SCHEMA_VERSION,
    owned,
    createdDirs,
    createdFiles,
  };
  if (workspaceSettings.present && !(S.updating || S.removing)) {
    stack.settings = { file: 'maxstack.settings.json', version: 1, sha256: workspaceSettings.hash };
  } else if ((S.updating || S.removing) && getField(priorStack, 'settings') !== null) {
    stack.settings = getField(priorStack, 'settings') as Record<string, unknown>;
  }
  if (S.removing) {
    invokeRemovalFlow(stack, owned, plan);
    return currentExitCode();
  }
  const knownNow = [...owned, ...(priorOwned ?? [])].filter((record) => record !== null);
  const settingsNowSha =
    piSettings !== null && !piPending ? getTextSha256(piSettings.text) : S.priorSettingsSha;
  invokeStrayReport(knownNow, (stack.configSha256 as string | null) ?? null, settingsNowSha, keptJournals);
  writeLockAtomically(`${JSON.stringify(stack, null, 2)}\n`);
  writeHost(`Wrote ${S.stackTarget}`);

  if (codexSelected) {
    writeCodexNotes({
      layers,
      applying: true,
      openCodeSelected,
      workspaceInstructionPlan,
      hookConfigPlan: codexHookConfigPlan,
    });
  }
  writeHost('Workspace bundle installed from the layer manifest.');
  writeHost(
    'Restart the running OpenCode server, then start a new T3 session to load it: T3 can reuse that server across sessions. Claude Code reads plugins when a session starts. Pi reads its settings when a session starts.',
  );
  if (skippedRuntimeWrappers.length > 0) {
    writeHost('INCOMPLETE: selected runtime wrappers were skipped:');
    for (const skipped of skippedRuntimeWrappers) {
      writeHost(`  ${skipped.runtime}: ${skipped.paths.join(', ')}`);
    }
    writeHost('Install the missing CLI, then rerun with -Apply.');
    if (S.strict) process.exitCode = 1;
  }
  return currentExitCode();
}
